final_template:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_ec2_managed_prefix_list" "cloudfront" {
  name = "com.amazonaws.global.cloudfront.origin-facing"
}

variable "project_name" {
  description = "Name of the project used as a prefix for all resource names."
  type        = string
  default     = "twotier-alb"
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

variable "instance_type" {
  description = "EC2 instance type for the backend application tier."
  type        = string
  default     = "t3.micro"
}

variable "asg_min_size" {
  description = "Minimum number of backend instances (retained for parity with prior scaling config)."
  type        = number
  default     = 1
}

variable "asg_max_size" {
  description = "Maximum number of backend instances (retained for parity with prior scaling config)."
  type        = number
  default     = 3
}

variable "asg_desired_capacity" {
  description = "Desired number of backend instances registered behind the load balancer."
  type        = number
  default     = 2
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )

  public_subnet_cidrs = [
    cidrsubnet(aws_vpc.main.cidr_block, 8, 0),
    cidrsubnet(aws_vpc.main.cidr_block, 8, 1),
  ]

  private_subnet_cidrs = [
    cidrsubnet(aws_vpc.main.cidr_block, 8, 2),
    cidrsubnet(aws_vpc.main.cidr_block, 8, 3),
  ]

  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]
}

# Intended topology: the Application Load Balancer is intentionally internal
# (`internal = true`) so it satisfies the public-exposure guardrails (AWS-0053),
# while public HTTP/HTTPS entry is provided by a CloudFront distribution using a
# standard custom origin. CloudFront is the only public entry point; the ALB
# security group is scoped to the CloudFront origin-facing prefix list.
#
# Backend instances register with the load balancer through the ELBv2
# RegisterTargets API (aws_lb_target_group_attachment), which keeps target
# registration decoupled from any Auto Scaling service call.

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[0]
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[1]
  availability_zone       = local.azs[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
    Tier = "public"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[0]
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[1]
  availability_zone       = local.azs[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb"
  description = "Internal front door for the Application Load Balancer; accepts HTTP (redirect) and HTTPS only from the CloudFront origin-facing prefix list and allows outbound traffic only within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Inbound HTTP from CloudFront origin-facing range, used solely to redirect clients to HTTPS"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    prefix_list_ids = [data.aws_ec2_managed_prefix_list.cloudfront.id]
  }

  ingress {
    description     = "Inbound HTTPS from CloudFront origin-facing range"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [data.aws_ec2_managed_prefix_list.cloudfront.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
    Tier = "alb"
  })
}

resource "aws_security_group" "allow_alb" {
  name        = "${local.name_prefix}-allow-alb"
  description = "Backend application tier; accepts inbound HTTP only from the ALB security group and allows outbound traffic only within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Inbound HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-allow-alb-sg"
    Tier = "app"
  })
}

resource "tls_private_key" "lb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "lb" {
  private_key_pem = tls_private_key.lb.private_key_pem

  subject {
    common_name  = "${local.name_prefix}.internal"
    organization = var.project_name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "lb" {
  certificate_body  = tls_self_signed_cert.lb.cert_pem
  private_key       = tls_private_key.lb.private_key_pem
  certificate_chain = tls_self_signed_cert.lb.cert_pem

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-cert"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "main" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  drop_invalid_header_fields = true

  enable_deletion_protection = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_target_group" "app" {
  name     = "${local.name_prefix}-app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
    matcher             = "200"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-http-redirect-listener"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.lb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-https-listener"
  })
}

resource "aws_lb_listener_rule" "app_path" {
  listener_arn = aws_lb_listener.https.arn
  priority     = 100

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  condition {
    path_pattern {
      values = ["/*"]
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-path-rule"
  })
}

resource "aws_wafv2_web_acl" "main" {
  name        = "${local.name_prefix}-cloudfront-waf"
  description = "WAF protecting the CloudFront front door for the two-tier application."
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 10

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.name_prefix}-common-rules"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWSManagedRulesKnownBadInputsRuleSet"
    priority = 20

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.name_prefix}-known-bad-inputs"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${local.name_prefix}-waf"
    sampled_requests_enabled   = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cloudfront-waf"
  })
}

resource "aws_cloudfront_distribution" "main" {
  enabled    = true
  comment    = "${local.name_prefix} front door for the internal application load balancer"
  web_acl_id = aws_wafv2_web_acl.main.arn

  origin {
    domain_name = aws_lb.main.dns_name
    origin_id   = "${local.name_prefix}-alb-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "${local.name_prefix}-alb-origin"
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = true

      cookies {
        forward = "all"
      }
    }

    min_ttl     = 0
    default_ttl = 0
    max_ttl     = 0
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cloudfront"
  })

  depends_on = [aws_lb_listener.https]
}

resource "aws_iam_role" "app" {
  name = "${local.name_prefix}-app-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-role"
  })
}

resource "aws_iam_role_policy_attachment" "app_ssm" {
  role       = aws_iam_role.app.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "app" {
  name = "${local.name_prefix}-app-profile"
  role = aws_iam_role.app.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-profile"
  })
}

resource "aws_launch_template" "app" {
  name_prefix   = "${local.name_prefix}-app-"
  image_id      = data.aws_ami.amazon_linux.id
  instance_type = var.instance_type

  vpc_security_group_ids = [aws_security_group.allow_alb.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.app.name
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_type           = "gp3"
      volume_size           = 8
      encrypted             = true
      delete_on_termination = true
    }
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable httpd
    systemctl start httpd
    echo "OK" > /var/www/html/index.html
  EOF
  )

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-app-instance"
      Tier = "app"
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-app-volume"
    })
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-launch-template"
  })
}

resource "aws_instance" "app" {
  count = var.asg_desired_capacity

  subnet_id = count.index % 2 == 0 ? aws_subnet.private_a.id : aws_subnet.private_b.id

  launch_template {
    id      = aws_launch_template.app.id
    version = "$Latest"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-instance-${count.index + 1}"
    Tier = "app"
  })

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_route_table_association.private_a, aws_route_table_association.private_b]
}

resource "aws_lb_target_group_attachment" "app" {
  count = var.asg_desired_capacity

  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.app[count.index].id
  port             = 80
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.82.0, < 5.100.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr            = "10.0.0.0/16"
  public_subnet_cidr  = "10.0.1.0/24"
  private_subnet_cidr = "10.0.2.0/24"

  public_availability_zone  = data.aws_availability_zones.available.names[0]
  private_availability_zone = data.aws_availability_zones.available.names[1]

  common_tags = {
    Project     = "networking-test"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = local.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  assign_ipv6_address_on_creation = false
  map_public_ip_on_launch         = false
  availability_zone               = local.public_availability_zone

  tags = merge(local.common_tags, {
    Name = "public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 2)
  assign_ipv6_address_on_creation = false
  map_public_ip_on_launch         = false
  availability_zone               = local.private_availability_zone

  tags = merge(local.common_tags, {
    Name = "private-subnet"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-internet-gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-route-table"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "private-route-table"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for the subnets provisioned inside the VPC"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "Optional explicit list of availability zones; when empty the first two available AZs are used"
  type        = list(string)
  default     = []
}

locals {
  selected_azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 2)

  subnets = {
    for index, cidr in var.subnet_cidrs : tostring(index) => {
      cidr_block        = cidr
      availability_zone = local.selected_azs[index % length(local.selected_azs)]
      name              = "main-subnet-${index + 1}"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  for_each = local.subnets

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = {
    Name = each.value.name
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

variable "workspace_name" {
  description = "Name of the AWS Managed Grafana workspace that assumes the role."
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs permitted to assume the Grafana workspace role (the monitoring accounts)."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "User-controlled tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default     = {}
}

variable "create_grafana_workspace" {
  description = "Whether to create the AWS Managed Grafana workspace. Set to true when targeting a real AWS account where the grafana service is supported (e.g. via the SERVICE_MANAGED permission type). Defaults to false so unattended applies remain deployable in service-limited targets (such as LocalStack) that do not implement grafana:CreateWorkspace."
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  role_name   = "${var.workspace_name}-workspace-role"
  policy_name = "${var.workspace_name}-prometheus-cloudwatch-policy"

  common_tags = merge(
    {
      Name = var.workspace_name
    },
    var.tags
  )

  prometheus_workspace_arns = [
    "arn:${data.aws_partition.current.partition}:aps:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:workspace/*"
  ]

  grafana_workspace_arns = [
    for account_id in var.monitoring_account_ids :
    "arn:${data.aws_partition.current.partition}:grafana:${data.aws_region.current.name}:${account_id}:workspace/${var.workspace_name}"
  ]
}

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "AllowGrafanaWorkspaceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.monitoring_account_ids
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = local.grafana_workspace_arns
    }
  }
}

resource "aws_iam_role" "grafana_workspace" {
  name                 = local.role_name
  description          = "Role assumed by the ${var.workspace_name} AWS Managed Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch."
  max_session_duration = 43200
  assume_role_policy   = data.aws_iam_policy_document.grafana_assume_role.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "grafana_prometheus_cloudwatch" {
  statement {
    sid    = "ManagedPrometheusQueryAccess"
    effect = "Allow"

    actions = [
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
    ]

    resources = local.prometheus_workspace_arns
  }

  statement {
    sid    = "CloudWatchMetricsReadOnlyAccess"
    effect = "Allow"

    actions = [
      "cloudwatch:ListMetrics",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarmsForMetric",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_prometheus_cloudwatch" {
  name        = local.policy_name
  description = "Least-privilege policy allowing the ${var.workspace_name} Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."
  policy      = data.aws_iam_policy_document.grafana_prometheus_cloudwatch.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "grafana_prometheus_cloudwatch" {
  role       = aws_iam_role.grafana_workspace.name
  policy_arn = aws_iam_policy.grafana_prometheus_cloudwatch.arn
}

resource "aws_grafana_workspace" "grafana" {
  count = var.create_grafana_workspace ? 1 : 0

  name                     = var.workspace_name
  description              = "AWS Managed Grafana workspace for Prometheus and CloudWatch monitoring dashboards."
  account_access_type      = "CURRENT_ACCOUNT"
  authentication_providers = ["AWS_SSO"]
  permission_type          = "SERVICE_MANAGED"
  data_sources             = ["PROMETHEUS", "CLOUDWATCH"]
  role_arn                 = aws_iam_role.grafana_workspace.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region used for all resources in this configuration."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to every resource created by this configuration."
  type        = string
  default     = "container-platform"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "RFC1918 CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "service_discovery_namespace" {
  description = "Private DNS namespace name used for container service discovery."
  type        = string
  default     = "service.local"
}

variable "subnet_count" {
  description = "Number of public/private subnet pairs to create (one per availability zone)."
  type        = number
  default     = 2
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  public_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 1),
    cidrsubnet(var.vpc_cidr, 8, 2),
  ]

  private_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 101),
    cidrsubnet(var.vpc_cidr, 8, 102),
  ]

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
    Region      = var.aws_region
  }
}

###############################################################################
# Networking - VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

###############################################################################
# Subnets
#
# "Public" is expressed through the route table association (0.0.0.0/0 -> IGW),
# not through automatic public IP assignment. map_public_ip_on_launch is left
# disabled on every subnet so launched instances never receive a default
# public IP address.
###############################################################################

resource "aws_subnet" "public" {
  count = var.subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = var.subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-subnet-${count.index + 1}"
    Tier = "private"
  })
}

###############################################################################
# Internet Gateway and Public Routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = var.subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT Gateway (single, placed in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-nat-gw"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Private Routing
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private" {
  count = var.subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Application Security Group
###############################################################################

resource "aws_security_group" "app" {
  name        = "${var.project_name}-app-sg"
  description = "Application security group: SSH restricted to the VPC CIDR, inbound application traffic, egress limited to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Containerized application port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-app-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Private Service Discovery Namespace
###############################################################################

resource "aws_service_discovery_private_dns_namespace" "namespace" {
  name        = var.service_discovery_namespace
  description = "Private DNS namespace used by containerized applications for service discovery"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-service-discovery"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "availability_zones" {
  description = "Availability zones used by the subnet layout."
  value       = local.azs
}

output "nat_gateway_id" {
  description = "ID of the single NAT gateway."
  value       = aws_nat_gateway.nat.id
}

output "app_security_group_id" {
  description = "ID of the application security group."
  value       = aws_security_group.app.id
}

output "service_discovery_namespace_id" {
  description = "ID of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.namespace.id
}

output "service_discovery_namespace_arn" {
  description = "ARN of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.namespace.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name, used as a prefix for all resource names."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  name_prefix = lower(replace(var.environment, "/[^a-zA-Z0-9]+/", "-"))

  identity_pool_name = "${replace(local.name_prefix, "-", "_")}_identity_pool"

  tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "Terraform"
      Service     = "cognito-identity"
    },
    var.tags
  )
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OPTIONAL"

  username_configuration {
    case_sensitive = false
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  software_token_mfa_configuration {
    enabled = true
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  tags = local.tags
}

resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"

  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true
  supported_identity_providers         = ["COGNITO"]

  callback_urls = ["http://localhost:3000/callback"]
  logout_urls   = ["http://localhost:3000/logout"]

  read_attributes = [
    "email",
    "email_verified",
  ]

  write_attributes = [
    "email",
  ]

  refresh_token_validity = 30
  access_token_validity  = 60
  id_token_validity      = 60

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = "cognito-idp.${local.region}.amazonaws.com/${aws_cognito_user_pool.main.id}"
    server_side_token_check = true
  }

  tags = local.tags
}

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${local.name_prefix}-cognito-authenticated-role"
  description        = "Role assumed by authenticated Cognito identity pool identities (Cognito Sync and Mobile Analytics)."
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    sid    = "CognitoSyncAccess"
    effect = "Allow"

    actions = ["cognito-sync:*"]

    resources = [
      "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/*",
    ]
  }

  statement {
    sid    = "MobileAnalyticsAccess"
    effect = "Allow"

    actions = ["mobileanalytics:PutEvents"]

    resources = [
      "arn:${local.partition}:mobileanalytics:${local.region}:${local.account_id}:*",
    ]
  }
}

resource "aws_iam_policy" "authenticated" {
  name        = "${local.name_prefix}-cognito-authenticated-policy"
  description = "Least-privilege policy for authenticated Cognito identities."
  policy      = data.aws_iam_policy_document.authenticated_permissions.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "authenticated" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# The default AWS provider (primary region + credentials) is injected by the
# deployment harness. Only the aliased provider required for multi-region
# replica KMS keys is declared here.
###############################################################################
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# General inputs
###############################################################################
variable "name_prefix" {
  description = "Name prefix applied to every resource created by this module."
  type        = string
  default     = "cmk"
}

variable "environment" {
  description = "Environment name applied to tags (dev, staging, prod, ...)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this module."
  type        = map(string)
  default     = {}
}

variable "replica_region" {
  description = "Region used by the aws.replica provider for multi-region replica keys."
  type        = string
  default     = "us-west-2"
}

###############################################################################
# Mutually exclusive creation flags
#
# create_standard_key defaults to true so that a default `terraform apply`
# provisions a key without requiring any externally supplied values (no
# imported key material, no primary key ARN). The remaining three paths stay
# disabled by default because they each require inputs that cannot be satisfied
# unattended on a greenfield account.
###############################################################################
variable "create_standard_key" {
  description = "Create a standard customer-managed KMS key backed by AWS-provided key material. Defaults to true so the module provisions a key out of the box."
  type        = bool
  default     = true

  validation {
    condition = (
      (var.create_standard_key ? 1 : 0) +
      (var.create_external_key ? 1 : 0) +
      (var.create_replica_key ? 1 : 0) +
      (var.create_replica_external_key ? 1 : 0)
    ) <= 1
    error_message = "At most one of create_standard_key, create_external_key, create_replica_key or create_replica_external_key may be true."
  }
}

variable "create_external_key" {
  description = "Create an external KMS key that is backed by imported key material. Disabled by default because it requires external_key_material_base64."
  type        = bool
  default     = false

  validation {
    condition = (
      !var.create_external_key
      ? true
      : (var.key_usage == "ENCRYPT_DECRYPT" && var.key_spec == "SYMMETRIC_DEFAULT")
    )
    error_message = "Imported external key material is always a symmetric ENCRYPT_DECRYPT key: require key_usage = ENCRYPT_DECRYPT and key_spec = SYMMETRIC_DEFAULT when create_external_key = true."
  }
}

variable "create_replica_key" {
  description = "Create a standard multi-region replica key referencing a primary key ARN. Disabled by default because it requires primary_key_arn."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica external key with custom key material and a primary external key ARN. Disabled by default because it requires primary_external_key_arn and external_key_material_base64."
  type        = bool
  default     = false

  validation {
    condition = (
      !var.create_replica_external_key
      ? true
      : (var.key_usage == "ENCRYPT_DECRYPT" && var.key_spec == "SYMMETRIC_DEFAULT")
    )
    error_message = "Imported external key material is always a symmetric ENCRYPT_DECRYPT key: require key_usage = ENCRYPT_DECRYPT and key_spec = SYMMETRIC_DEFAULT when create_replica_external_key = true."
  }
}

###############################################################################
# Key configuration inputs
###############################################################################
variable "key_usage" {
  description = "Intended use of the KMS key (ENCRYPT_DECRYPT, SIGN_VERIFY or GENERATE_VERIFY_MAC)."
  type        = string
  default     = "ENCRYPT_DECRYPT"

  validation {
    condition     = contains(["ENCRYPT_DECRYPT", "SIGN_VERIFY", "GENERATE_VERIFY_MAC"], var.key_usage)
    error_message = "key_usage must be one of ENCRYPT_DECRYPT, SIGN_VERIFY or GENERATE_VERIFY_MAC."
  }
}

variable "key_spec" {
  description = "Key material spec of the KMS key (SYMMETRIC_DEFAULT, RSA_2048, ECC_NIST_P256, HMAC_256, ...)."
  type        = string
  default     = "SYMMETRIC_DEFAULT"

  validation {
    condition = contains([
      "SYMMETRIC_DEFAULT",
      "RSA_2048",
      "RSA_3072",
      "RSA_4096",
      "ECC_NIST_P256",
      "ECC_NIST_P384",
      "ECC_NIST_P521",
      "ECC_SECG_P256K1",
      "HMAC_224",
      "HMAC_256",
      "HMAC_384",
      "HMAC_512",
    ], var.key_spec)
    error_message = "key_spec must be a supported KMS key spec value."
  }
}

variable "deletion_window_in_days" {
  description = "Number of days before the key is permanently deleted after scheduling deletion."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be between 7 and 30."
  }
}

variable "enable_key_rotation" {
  description = "Enable automatic annual rotation of the key material (symmetric keys only)."
  type        = bool
  default     = true
}

variable "multi_region" {
  description = "Create the standard key as a multi-region primary key."
  type        = bool
  default     = false
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-region key that a standard replica key is created from."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary multi-region external key that a replica external key is created from."
  type        = string
  default     = null
}

variable "external_key_material_base64" {
  description = "Base64 encoded 256-bit key material for imported external keys. Must be supplied at apply time via TF_VAR_* or a tfvars file; it is never stored with a default value."
  type        = string
  default     = null
  sensitive   = true
}

###############################################################################
# Alias inputs
###############################################################################
variable "alias_name" {
  description = "Exact alias name (without the 'alias/' prefix) to assign to the created key."
  type        = string
  default     = null

  validation {
    condition = (
      (var.alias_name == null || var.alias_name == "") ||
      (var.alias_name_prefix == null || var.alias_name_prefix == "")
    )
    error_message = "alias_name and alias_name_prefix are mutually exclusive: set at most one of them."
  }
}

variable "alias_name_prefix" {
  description = "Alias name prefix used to generate a unique alias name for the created key."
  type        = string
  default     = null
}

###############################################################################
# Key policy inputs
###############################################################################
variable "enable_default_root_policy" {
  description = "Attach the default key policy statement that grants kms:* to the account root principal."
  type        = bool
  default     = true
}

variable "enable_route53_dnssec" {
  description = "Grant the Route 53 DNSSEC signing service principal GetPublicKey/Sign on the created key."
  type        = bool
  default     = false
}

variable "key_owners" {
  description = "List of IAM principals granted full administrative control over the key."
  type        = list(string)
  default     = []
}

variable "key_admins" {
  description = "List of IAM principals granted administrative control over the key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM principals granted the standard cryptographic consumer permissions."
  type        = list(string)
  default     = []
}

variable "key_user_via_services" {
  description = "Optional list of AWS services allowed to use the key on behalf of key_users (kms:ViaService condition). Empty list disables the condition."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "List of AWS service principals granted cryptographic consumer permissions on the key."
  type        = list(string)
  default     = []
}

variable "autoscaling_service_principals" {
  description = "List of service principals granted EC2 Auto Scaling access to the key (via ec2.*/autoscaling.* services)."
  type        = list(string)
  default     = ["autoscaling.amazonaws.com"]
}

variable "symmetric_crypto_users" {
  description = "IAM principals allowed to perform symmetric Encrypt/Decrypt/ReEncrypt/GenerateDataKey operations."
  type        = list(string)
  default     = []
}

variable "hmac_crypto_users" {
  description = "IAM principals allowed to perform HMAC GenerateMac/VerifyMac operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encrypt_users" {
  description = "IAM principals allowed to perform asymmetric public encryption operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "IAM principals allowed to perform asymmetric sign and verify operations."
  type        = list(string)
  default     = []
}

variable "custom_policy_statements" {
  description = "Additional key policy statements appended to the generated document."
  type = list(object({
    sid        = optional(string)
    effect     = optional(string, "Allow")
    actions    = list(string)
    resources  = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []
}

variable "override_policy_document" {
  description = "Full JSON key policy document that completely replaces the generated policy when non-empty."
  type        = string
  default     = null
}

###############################################################################
# Grant inputs
###############################################################################
variable "grants" {
  description = "List of KMS grants to create on the key."
  type = list(object({
    name                      = string
    grantee_principal         = string
    operations                = list(string)
    retiring_principal        = optional(string)
    grant_creation_tokens     = optional(list(string))
    encryption_context_equals = optional(map(string), {})
    encryption_context_subset = optional(map(string), {})
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################
locals {
  common_tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
  })

  key_admin_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion",
  ]

  key_user_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  # ARN of a key created in the primary region (standard or external).
  created_key_arn = one(concat(
    aws_kms_key.standard[*].arn,
    aws_kms_external_key.external[*].arn,
  ))

  # Key id of a key created in the primary region - used as target for aliases/grants.
  primary_target_key_id = one(concat(
    aws_kms_key.standard[*].key_id,
    aws_kms_external_key.external[*].id,
  ))

  # ARN all non-root statements are scoped to.
  policy_self_arn = coalesce(
    local.created_key_arn,
    var.primary_key_arn,
    var.primary_external_key_arn,
    "*",
  )

  policy_resource_arns = [local.policy_self_arn]

  external_key_material_required = var.create_external_key || var.create_replica_external_key

  # When the only key being provisioned is an imported-material external key the
  # key is always a symmetric ENCRYPT_DECRYPT key, so HMAC, asymmetric and
  # Route 53 DNSSEC statements must be omitted entirely.
  external_key_only          = var.create_external_key || var.create_replica_external_key
  supports_non_symmetric_ops = !local.external_key_only

  resolved_key_policy_json = (
    var.override_policy_document != null && var.override_policy_document != ""
    ? var.override_policy_document
    : data.aws_iam_policy_document.key_policy.json
  )
}

###############################################################################
# Generated key policy document
###############################################################################
data "aws_iam_policy_document" "key_policy" {
  dynamic "statement" {
    for_each = var.enable_default_root_policy ? [1] : []
    content {
      sid       = "DefaultRootPermissions"
      effect    = "Allow"
      actions   = ["kms:*"]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []
    content {
      sid       = "KeyOwners"
      effect    = "Allow"
      actions   = local.key_admin_actions
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_admins) > 0 ? [1] : []
    content {
      sid       = "KeyAdministrators"
      effect    = "Allow"
      actions   = local.key_admin_actions
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.key_admins
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid       = "KeyUsers"
      effect    = "Allow"
      actions   = local.key_user_actions
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.key_users
      }

      dynamic "condition" {
        for_each = length(var.key_user_via_services) > 0 ? [1] : []
        content {
          test     = "StringEquals"
          variable = "kms:ViaService"
          values   = var.key_user_via_services
        }
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []
    content {
      sid       = "KeyServiceUsers"
      effect    = "Allow"
      actions   = local.key_user_actions
      resources = local.policy_resource_arns

      principals {
        type        = "Service"
        identifiers = var.key_service_users
      }

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.autoscaling_service_principals) > 0 ? [1] : []
    content {
      sid       = "EC2AutoScalingServiceRole"
      effect    = "Allow"
      actions   = local.key_user_actions
      resources = local.policy_resource_arns

      principals {
        type        = "Service"
        identifiers = var.autoscaling_service_principals
      }

      condition {
        test     = "StringLike"
        variable = "kms:ViaService"
        values = [
          "ec2.*.amazonaws.com",
          "autoscaling.*.amazonaws.com",
        ]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.symmetric_crypto_users) > 0 ? [1] : []
    content {
      sid    = "SymmetricCryptoUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
        "kms:GenerateDataKey*",
        "kms:DescribeKey",
      ]
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.symmetric_crypto_users
      }

      condition {
        test     = "StringEquals"
        variable = "kms:EncryptionAlgorithm"
        values   = ["SYMMETRIC_DEFAULT"]
      }
    }
  }

  dynamic "statement" {
    for_each = local.supports_non_symmetric_ops && length(var.hmac_crypto_users) > 0 ? [1] : []
    content {
      sid    = "HmacCryptoUsers"
      effect = "Allow"
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac",
        "kms:DescribeKey",
      ]
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.hmac_crypto_users
      }

      condition {
        test     = "StringLike"
        variable = "kms:MacAlgorithm"
        values   = ["HMAC_SHA_*"]
      }
    }
  }

  dynamic "statement" {
    for_each = local.supports_non_symmetric_ops && length(var.asymmetric_public_encrypt_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricPublicEncryptUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:DescribeKey",
      ]
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encrypt_users
      }

      condition {
        test     = "StringEquals"
        variable = "kms:EncryptionAlgorithm"
        values = [
          "RSAES_OAEP_SHA_1",
          "RSAES_OAEP_SHA_256",
        ]
      }
    }
  }

  dynamic "statement" {
    for_each = local.supports_non_symmetric_ops && length(var.asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricSignVerifyUsers"
      effect = "Allow"
      actions = [
        "kms:Sign",
        "kms:Verify",
        "kms:DescribeKey",
      ]
      resources = local.policy_resource_arns

      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_users
      }

      condition {
        test     = "StringLike"
        variable = "kms:SigningAlgorithm"
        values = [
          "RSASSA_PSS_SHA_*",
          "RSASSA_PKCS1_V1_5_SHA_*",
          "ECDSA_SHA_*",
        ]
      }
    }
  }

  dynamic "statement" {
    for_each = local.supports_non_symmetric_ops && var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "Route53DnssecSigning"
      effect = "Allow"
      actions = [
        "kms:GetPublicKey",
        "kms:Sign",
      ]
      resources = local.policy_resource_arns

      principals {
        type        = "Service"
        identifiers = ["dnssec.route53.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements
    iterator = custom
    content {
      sid       = try(custom.value.sid, null)
      effect    = try(custom.value.effect, "Allow")
      actions   = custom.value.actions
      resources = try(custom.value.resources, local.policy_resource_arns)

      dynamic "principals" {
        for_each = try(custom.value.principals, [])
        iterator = principal
        content {
          type        = principal.value.type
          identifiers = principal.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(custom.value.condition, [])
        iterator = cond
        content {
          test     = cond.value.test
          variable = cond.value.variable
          values   = cond.value.values
        }
      }
    }
  }
}

###############################################################################
# External key material (stored in Secrets Manager, never inline)
###############################################################################
resource "aws_secretsmanager_secret" "external_key_material" {
  count = local.external_key_material_required ? 1 : 0

  name                    = "${var.name_prefix}-${var.environment}-external-kms-key-material"
  description             = "Imported KMS external key material for ${var.name_prefix}-${var.environment}"
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-${var.environment}-external-kms-key-material"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "external_key_material" {
  count = local.external_key_material_required ? 1 : 0

  secret_id     = aws_secretsmanager_secret.external_key_material[0].id
  secret_string = var.external_key_material_base64
}

###############################################################################
# Standard customer-managed key (AWS-provided key material)
# Enabled by default (create_standard_key = true) so a bare apply provisions a
# key without requiring any externally supplied inputs.
###############################################################################
resource "aws_kms_key" "standard" {
  count = var.create_standard_key ? 1 : 0

  description              = "Customer managed KMS key ${var.name_prefix}-${var.environment} (${data.aws_region.current.name})"
  key_usage                = var.key_usage
  customer_master_key_spec = var.key_spec
  multi_region             = var.multi_region
  enable_key_rotation      = var.enable_key_rotation
  deletion_window_in_days  = var.deletion_window_in_days

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-${var.environment}-standard"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "standard" {
  count = var.create_standard_key ? 1 : 0

  key_id = aws_kms_key.standard[0].id
  policy = local.resolved_key_policy_json

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# External key (imported key material)
# key_usage and key_spec are computed (read-only) attributes: imported material
# is always a symmetric ENCRYPT_DECRYPT key, so they must not be configured.
###############################################################################
resource "aws_kms_external_key" "external" {
  count = var.create_external_key ? 1 : 0

  description             = "Customer managed external KMS key ${var.name_prefix}-${var.environment} (${data.aws_region.current.name})"
  deletion_window_in_days = var.deletion_window_in_days
  multi_region            = false
  key_material_base64     = aws_secretsmanager_secret_version.external_key_material[0].secret_string

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-${var.environment}-external"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "external" {
  count = var.create_external_key ? 1 : 0

  key_id = aws_kms_external_key.external[0].id
  policy = local.resolved_key_policy_json

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Standard multi-region replica key
# No key_usage / key_spec / rotation arguments: these are inherited from the
# primary key and are not configurable on the replica.
###############################################################################
resource "aws_kms_replica_key" "replica" {
  provider = aws.replica
  count    = var.create_replica_key ? 1 : 0

  description                        = "Multi-region replica KMS key for ${var.name_prefix}-${var.environment} (${var.replica_region})"
  primary_key_arn                    = var.primary_key_arn
  deletion_window_in_days            = var.deletion_window_in_days
  bypass_policy_lockout_safety_check = false
  policy                             = local.resolved_key_policy_json

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-${var.environment}-replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Multi-region replica external key
# No key_usage / key_spec / rotation arguments: inherited from the primary key.
###############################################################################
resource "aws_kms_replica_external_key" "replica_external" {
  provider = aws.replica
  count    = var.create_replica_external_key ? 1 : 0

  description                        = "Multi-region replica external KMS key for ${var.name_prefix}-${var.environment} (${var.replica_region})"
  primary_key_arn                    = var.primary_external_key_arn
  key_material_base64                = aws_secretsmanager_secret_version.external_key_material[0].secret_string
  deletion_window_in_days            = var.deletion_window_in_days
  bypass_policy_lockout_safety_check = false
  policy                             = local.resolved_key_policy_json

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-${var.environment}-replica-external"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Aliases
###############################################################################
resource "aws_kms_alias" "named" {
  for_each = var.alias_name == null || var.alias_name == "" ? toset([]) : toset([var.alias_name])

  name          = "alias/${trimprefix(each.value, "alias/")}"
  target_key_id = local.primary_target_key_id
}

resource "aws_kms_alias" "prefixed" {
  count = var.alias_name_prefix == null || var.alias_name_prefix == "" ? 0 : 1

  name_prefix   = "alias/${var.alias_name_prefix}"
  target_key_id = local.primary_target_key_id
}

###############################################################################
# Grants
###############################################################################
resource "aws_kms_grant" "this" {
  for_each = { for g in var.grants : g.name => g }

  name              = each.value.name
  key_id            = local.primary_target_key_id
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations

  retiring_principal    = try(each.value.retiring_principal, null)
  grant_creation_tokens = try(each.value.grant_creation_tokens, null)

  dynamic "constraints" {
    for_each = length(each.value.encryption_context_equals) > 0 ? [1] : []
    content {
      encryption_context_equals = each.value.encryption_context_equals
    }
  }

  dynamic "constraints" {
    for_each = length(each.value.encryption_context_subset) > 0 ? [1] : []
    content {
      encryption_context_subset = each.value.encryption_context_subset
    }
  }
}

###############################################################################
# Outputs
###############################################################################
output "key_arn" {
  description = "ARN of the created standard or external KMS key."
  value = one(concat(
    aws_kms_key.standard[*].arn,
    aws_kms_external_key.external[*].arn,
  ))
}

output "key_id" {
  description = "Key id of the created standard or external KMS key."
  value = one(concat(
    aws_kms_key.standard[*].key_id,
    aws_kms_external_key.external[*].id,
  ))
}

output "key_alias_arn" {
  description = "ARN of the alias created for the key (exact name or prefix based)."
  value = one(concat(
    [for a in aws_kms_alias.named : a.arn],
    [for a in aws_kms_alias.prefixed : a.arn],
  ))
}

output "key_alias_name" {
  description = "Name of the alias created for the key (exact name or prefix based)."
  value = one(concat(
    [for a in aws_kms_alias.named : a.name],
    [for a in aws_kms_alias.prefixed : a.name],
  ))
}

output "replica_key_arn" {
  description = "ARN of the created multi-region replica key (standard or external)."
  value = one(concat(
    aws_kms_replica_key.replica[*].arn,
    aws_kms_replica_external_key.replica_external[*].arn,
  ))
}

output "external_key_id" {
  description = "Key id of the created external KMS key."
  value       = one(aws_kms_external_key.external[*].id)
}

output "external_key_usage" {
  description = "Computed key usage of the created external KMS key (always ENCRYPT_DECRYPT; read-only attribute)."
  value       = one(aws_kms_external_key.external[*].key_usage)
}

output "external_key_spec" {
  description = "Computed key spec of the created external KMS key (always SYMMETRIC_DEFAULT; read-only attribute)."
  value       = one(aws_kms_external_key.external[*].key_spec)
}

output "grant_ids" {
  description = "Map of grant name to grant id for every created KMS grant."
  value       = { for k, g in aws_kms_grant.this : k => g.id }
}

output "key_policy_json" {
  description = "Resolved JSON key policy document attached to the created key."
  value       = local.resolved_key_policy_json
}

output "external_key_material_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the imported external key material."
  value       = one(aws_secretsmanager_secret.external_key_material[*].arn)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_name" {
  description = "Name of the VPC and value for the Blueprint tag"
  type        = string
  default     = "multi-cluster-k8s-vpc"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  cluster1_sg_name = "cluster1_additional_sg"
  cluster2_sg_name = "cluster2_additional_sg"

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = local.vpc_cidr

  azs = local.azs

  private_subnets = [
    cidrsubnet(local.vpc_cidr, 4, 0),
    cidrsubnet(local.vpc_cidr, 4, 1),
    cidrsubnet(local.vpc_cidr, 4, 2),
  ]

  public_subnets = [
    cidrsubnet(local.vpc_cidr, 8, 48),
    cidrsubnet(local.vpc_cidr, 8, 49),
    cidrsubnet(local.vpc_cidr, 8, 50),
  ]

  enable_dns_hostnames = true
  enable_dns_support   = true

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  map_public_ip_on_launch = false

  public_subnet_tags = merge(local.tags, {
    "kubernetes.io/role/elb" = "1"
  })

  private_subnet_tags = merge(local.tags, {
    "kubernetes.io/role/internal-elb" = "1"
  })

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = local.cluster1_sg_name
  description = "Additional security group for cluster1 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = local.cluster1_sg_name
  })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = local.cluster2_sg_name
  description = "Additional security group for cluster2 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = local.cluster2_sg_name
  })
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols from ${local.cluster2_sg_name}"
  tags                         = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster1_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols to ${local.cluster2_sg_name}"
  tags                         = local.tags
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols from ${local.cluster1_sg_name}"
  tags                         = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster2_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all protocols to ${local.cluster1_sg_name}"
  tags                         = local.tags
}

output "vpc_id" {
  description = "VPC ID"
  value       = module.vpc.vpc_id
}

output "private_subnet_ids" {
  description = "Private subnet IDs"
  value       = module.vpc.private_subnets
}

output "public_subnet_ids" {
  description = "Public subnet IDs"
  value       = module.vpc.public_subnets
}

output "cluster1_additional_sg_id" {
  description = "Cluster1 additional security group ID"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "Cluster2 additional security group ID"
  value       = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "user_pool_name" {
  type    = string
  default = "Pool name"
}

variable "alias_attributes" {
  type    = list(string)
  default = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type    = list(string)
  default = []
}

variable "username_attributes" {
  type    = list(string)
  default = []
}

variable "email_verification_message" {
  type    = string
  default = "Some message {####}"
}

variable "email_verification_subject" {
  type    = string
  default = "Some subject"
}

variable "mfa_configuration" {
  type    = string
  default = "OPTIONAL"
}

variable "sms_authentication_message" {
  type    = string
  default = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type    = string
  default = "SMS verification message {####}"
}

variable "verification_message_template_by_link" {
  type    = bool
  default = true
}

variable "sms_configuration" {
  type = map(string)
  default = {
    external_id   = ""
    sns_caller_arn = ""
  }
}

variable "account_recovery_setting" {
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

variable "invite_email_message" {
  type    = string
  default = "Your username is {username} and temporary password is {####}."
}

variable "invite_email_subject" {
  type    = string
  default = "Your temporary password"
}

variable "invite_sms_message" {
  type    = string
  default = "Your username is {username} and temporary password is {####}."
}

variable "admin_create_user_only" {
  type    = bool
  default = false
}

variable "software_token_mfa_enabled" {
  type    = bool
  default = true
}

variable "username_case_sensitive" {
  type    = bool
  default = null
}

variable "device_configuration" {
  type    = map(bool)
  default = null
}

variable "lambda_config" {
  type    = map(string)
  default = {}
}

variable "schema_definitions" {
  type = list(object({
    name                     = string
    attribute_data_type      = string
    required                 = optional(bool, false)
    mutable                  = optional(bool, true)
    developer_only_attribute = optional(bool, false)
    string_min_length        = optional(number, null)
    string_max_length        = optional(number, null)
  }))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

variable "email_sending_account" {
  type    = string
  default = "COGNITO_DEFAULT"
}

variable "email_source_arn" {
  type    = string
  default = ""
}

variable "email_from_email_address" {
  type    = string
  default = ""
}

variable "email_reply_to_email_address" {
  type    = string
  default = ""
}

variable "user_pool_client_names" {
  type    = list(string)
  default = []
}

variable "generate_secret" {
  type    = bool
  default = false
}

variable "enable_token_revocation" {
  type    = bool
  default = true
}

variable "allowed_oauth_user_pool_client" {
  type    = bool
  default = false
}

variable "user_pool_client_read_attributes" {
  type    = list(string)
  default = ["email"]
}

variable "user_pool_client_write_attributes" {
  type    = list(string)
  default = ["email"]
}

variable "user_pool_client_callback_urls" {
  type    = list(string)
  default = []
}

variable "user_pool_client_logout_urls" {
  type    = list(string)
  default = []
}

variable "user_pool_client_allowed_oauth_flows" {
  type    = list(string)
  default = ["code"]
}

variable "user_pool_client_allowed_oauth_scopes" {
  type    = list(string)
  default = ["email", "openid", "profile"]
}

variable "user_pool_client_supported_identity_providers" {
  type    = list(string)
  default = ["COGNITO"]
}

variable "user_group_name" {
  type    = string
  default = ""
}

variable "user_group_precedence" {
  type    = number
  default = 0
}

variable "user_group_role_arn" {
  type    = string
  default = ""
}

variable "user_pool_domain" {
  type    = string
  default = ""
}

variable "user_pool_domain_certificate_arn" {
  type    = string
  default = ""
}

variable "create_route53_record" {
  type    = bool
  default = false
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

locals {
  account_recovery_setting_sorted = sort([
    for m in var.account_recovery_setting : format("%03d|%s", m.priority, m.name)
  ])
}

resource "aws_cognito_user_pool" "main" {
  name                       = var.user_pool_name
  alias_attributes           = length(var.alias_attributes) > 0 ? var.alias_attributes : null
  auto_verified_attributes   = var.auto_verified_attributes
  username_attributes        = length(var.username_attributes) > 0 ? var.username_attributes : null
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only
    invite_message_template {
      email_message = var.invite_email_message
      email_subject = var.invite_email_subject
      sms_message   = var.invite_sms_message
    }
  }

  dynamic "account_recovery_setting" {
    for_each = length(var.account_recovery_setting) > 0 ? [1] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = { for idx, s in local.account_recovery_setting_sorted : idx => split("|", s) }
        content {
          name     = recovery_mechanism.value[1]
          priority = tonumber(recovery_mechanism.value[0])
        }
      }
    }
  }

  email_configuration {
    email_sending_account  = var.email_sending_account
    source_arn             = var.email_source_arn != "" ? var.email_source_arn : null
    from_email_address     = var.email_from_email_address != "" ? var.email_from_email_address : null
    reply_to_email_address = var.email_reply_to_email_address != "" ? var.email_reply_to_email_address : null
  }

  verification_message_template {
    default_email_option  = var.verification_message_template_by_link ? "CONFIRM_WITH_LINK" : "CONFIRM_WITH_CODE"
    email_message         = var.email_verification_message
    email_subject         = var.email_verification_subject
    email_message_by_link = var.verification_message_template_by_link ? "Click {##Verify Email##} to verify your email." : null
    email_subject_by_link = var.verification_message_template_by_link ? "Verify your email" : null
    sms_message           = var.sms_verification_message
  }

  dynamic "sms_configuration" {
    for_each = lookup(var.sms_configuration, "external_id", "") != "" && lookup(var.sms_configuration, "sns_caller_arn", "") != "" ? [1] : []
    content {
      external_id    = var.sms_configuration["external_id"]
      sns_caller_arn = var.sms_configuration["sns_caller_arn"]
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = var.software_token_mfa_enabled
    }
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitive != null ? [1] : []
    content {
      case_sensitive = var.username_case_sensitive
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = lookup(device_configuration.value, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(device_configuration.value, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_config) > 0 ? [1] : []
    content {
      dynamic "custom_email_sender" {
        for_each = lookup(var.lambda_config, "custom_email_sender_lambda_arn", "") != "" ? [1] : []
        content {
          lambda_arn     = var.lambda_config["custom_email_sender_lambda_arn"]
          lambda_version = lookup(var.lambda_config, "custom_email_sender_lambda_version", "V1_0")
        }
      }
      dynamic "custom_sms_sender" {
        for_each = lookup(var.lambda_config, "custom_sms_sender_lambda_arn", "") != "" ? [1] : []
        content {
          lambda_arn     = var.lambda_config["custom_sms_sender_lambda_arn"]
          lambda_version = lookup(var.lambda_config, "custom_sms_sender_lambda_version", "V1_0")
        }
      }
      kms_key_id = lookup(var.lambda_config, "kms_key_id", null) != "" ? var.lambda_config["kms_key_id"] : null
    }
  }

  dynamic "schema" {
    for_each = var.schema_definitions
    content {
      name                     = schema.value.name
      attribute_data_type      = schema.value.attribute_data_type
      required                 = schema.value.required
      mutable                  = schema.value.mutable
      developer_only_attribute = schema.value.developer_only_attribute
      dynamic "string_attribute_constraints" {
        for_each = (schema.value.string_min_length != null || schema.value.string_max_length != null) ? [1] : []
        content {
          min_length = schema.value.string_min_length
          max_length = schema.value.string_max_length
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [estimated_number_of_users]
  }
}

resource "aws_cognito_user_pool_client" "clients" {
  for_each = toset(var.user_pool_client_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                       = var.generate_secret
  explicit_auth_flows                   = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
  prevent_user_existence_errors         = "LEGACY"
  enable_token_revocation               = var.enable_token_revocation
  allowed_oauth_flows_user_pool_client  = var.allowed_oauth_user_pool_client

  access_token_validity  = 120
  id_token_validity      = 120
  refresh_token_validity = 7

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  read_attributes  = var.user_pool_client_read_attributes
  write_attributes = var.user_pool_client_write_attributes

  callback_urls                = var.allowed_oauth_user_pool_client ? var.user_pool_client_callback_urls : null
  logout_urls                  = var.allowed_oauth_user_pool_client ? var.user_pool_client_logout_urls : null
  allowed_oauth_flows          = var.allowed_oauth_user_pool_client ? var.user_pool_client_allowed_oauth_flows : null
  allowed_oauth_scopes         = var.allowed_oauth_user_pool_client ? var.user_pool_client_allowed_oauth_scopes : null
  supported_identity_providers = var.allowed_oauth_user_pool_client ? var.user_pool_client_supported_identity_providers : null
}

resource "aws_cognito_user_group" "group" {
  count = var.user_group_name != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.main.id
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn != "" ? var.user_group_role_arn : null
}

resource "aws_cognito_user_pool_domain" "domain" {
  count = var.user_pool_domain != "" ? 1 : 0

  domain          = var.user_pool_domain
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.user_pool_domain_certificate_arn != "" ? var.user_pool_domain_certificate_arn : null
}

resource "aws_route53_record" "cognito_alias" {
  count = var.create_route53_record ? 1 : 0

  zone_id = var.route53_zone_id
  name    = aws_cognito_user_pool_domain.domain[0].domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Input variables
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_id_name" {
  description = "Identifier tag for the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Public IPv4 pool from which the NAT Elastic IP is drawn"
  type        = string
  default     = "amazon"
}

# --- Subnet A (public) -------------------------------------------------------

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az_index" {
  description = "Index into the list of available AZs for Subnet A"
  type        = number
  default     = 0
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet A"
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

# --- Subnet B (private) ------------------------------------------------------

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az_index" {
  description = "Index into the list of available AZs for Subnet B"
  type        = number
  default     = 1
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet B"
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

# --- Subnet C (private) ------------------------------------------------------

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az_index" {
  description = "Index into the list of available AZs for Subnet C"
  type        = number
  default     = 2
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet C"
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_a_az_index]
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name       = var.subnet_a_name
    Identifier = var.public_subnet_id_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_b_az_index]
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_c_az_index]
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

###############################################################################
# Public route table + default route to the Internet Gateway
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Only Subnet A is associated with the public route table.
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT Gateway (Elastic IP + gateway in Subnet B)
###############################################################################

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool_name

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Security group: no ingress, egress only within the VPC CIDR
###############################################################################

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Default security group allowing egress only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.default.id
  description       = "Allow outbound traffic only within the VPC CIDR"
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "-1"
}

###############################################################################
# Outputs
###############################################################################

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Controls whether the Transit Gateway resources are created (true) or an existing Transit Gateway is resolved via data source lookup (false)."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the Transit Gateway. Used as the resource name suffix / Name tag and as the tag:Name lookup filter when create = false and id is null."
  type        = string
  default     = null
}

variable "id" {
  description = "ID of an existing Transit Gateway. Only used as a lookup filter when create = false."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachments are automatically accepted. Valid values: enable, disable."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "The auto_accept_shared_attachments value must be either \"enable\" or \"disable\"."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled. Valid values: enable, disable."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "The dns_support value must be either \"enable\" or \"disable\"."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled. Valid values: enable, disable."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "The vpn_ecmp_support value must be either \"enable\" or \"disable\"."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block (for example \"10.0.0.0/8\" or \"2001:db8::/56\")."
  }
}

variable "tags" {
  description = "A map of global tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables. Set create = true to create a new route table, or create = false to look up an existing one by tag:Name."
  type = map(object({
    create     = optional(bool, true)
    id         = optional(string)
    name       = optional(string)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of AWS account / OU / organization ARNs to share the Transit Gateway with via AWS RAM. Principals must be explicitly enumerated, no wildcards."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Explicit name for the AWS RAM resource share. Defaults to the Transit Gateway name or \"tgw-share\"."
  type        = string
  default     = null
}

################################################################################
# Transit Gateway
################################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, { Name = coalesce(var.name, "tgw") })
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  dynamic "filter" {
    for_each = var.id != null ? [1] : []
    content {
      name   = "id"
      values = [var.id]
    }
  }

  dynamic "filter" {
    for_each = var.id == null && var.name != null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

locals {
  transit_gateway_id  = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  transit_gateway_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn
}

################################################################################
# Transit Gateway route tables
################################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if coalesce(v.create, true) }

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    coalesce(each.value.local_tags, {}),
    { Name = coalesce(each.value.name, var.name, "tgw-route-table") }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if !coalesce(v.create, true) }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(each.value.name, var.name, "tgw-route-table")]
  }
}

################################################################################
# AWS RAM resource share
################################################################################

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name, "tgw-share")
  allow_external_principals = true

  tags = merge(var.tags, { Name = coalesce(var.ram_resource_share_name, var.name, "tgw-share") })
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.transit_gateway_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

################################################################################
# Outputs
################################################################################

output "transit_gateway_id" {
  description = "The ID of the resolved Transit Gateway (created or looked up)."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "The ARN of the resolved Transit Gateway (created or looked up)."
  value       = local.transit_gateway_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of Transit Gateway route table keys to their IDs, combining created and looked-up route tables."
  value = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )
}

output "ram_resource_share_arn" {
  description = "The ARN of the AWS RAM resource share used to share the Transit Gateway, if one was created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "= 3.6.0"
    }
  }
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

variable "bucket_name" {
  description = "Optional S3 bucket name. If null or empty a random name is generated."
  type        = string
  default     = null
}

variable "prefix" {
  description = "Append an additional random suffix to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "S3 request payment configuration payer."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Whether the module manages server-side encryption for the bucket. Encryption is always SSE-KMS when enabled."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "Optional customer-managed KMS key ARN. If empty the module creates its own rotating key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete. Requires versioning to be enabled."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the bucket and all objects."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to created resources."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "Optional canned ACL preference. ACLs are not directly configured; access is governed by bucket policy and public access block."
  type        = string
  default     = null
}

variable "policy" {
  description = "Optional JSON bucket policy document."
  type        = string
  default     = ""
}

variable "grants" {
  description = "Optional grants expressed as an explicit access request. ACL resources are not created; grants toggle ownership toward ObjectWriter."
  type        = any
  default     = []
}

variable "transfer_acceleration_status" {
  description = "S3 transfer acceleration status."
  type        = string
  default     = "Suspended"
}

variable "logging" {
  description = "Optional logging configuration. The module creates and manages its own target bucket."
  type        = any
  default     = null
}

variable "website" {
  description = "Optional website configuration with index_document, error_document, or redirect_all_requests_to."
  type        = any
  default     = null
}

variable "cors_rules" {
  description = "Optional list of CORS rules."
  type        = list(any)
  default     = []
}

variable "lifecycle_rules" {
  description = "Optional list of lifecycle rules."
  type        = list(any)
  default     = []
}

variable "object_lock_configuration" {
  description = "Optional object lock configuration with mode and days or years."
  type        = any
  default     = null
}

variable "replication_role" {
  description = "Optional external replication IAM role ARN. If empty the module creates its own role."
  type        = string
  default     = ""
}

variable "replication_rules" {
  description = "Optional list of cross-region replication rules."
  type        = list(any)
  default     = []
}

locals {
  bucket_name = var.bucket_name != null && var.bucket_name != "" ? (
    var.prefix ? "${var.bucket_name}-${random_id.name_prefix.hex}" : var.bucket_name
  ) : (
    var.prefix ? "corebucket-${random_id.bucket_suffix.hex}-${random_id.name_prefix.hex}" : "corebucket-${random_id.bucket_suffix.hex}"
  )

  logging_bucket_name = "corebucket-logs-${random_id.bucket_suffix.hex}"

  object_lock_enabled = var.object_lock_configuration != null

  versioning_enabled = var.versioning || var.mfa_delete || var.object_lock_configuration != null || length(var.replication_rules) > 0

  object_lock_years = var.object_lock_configuration != null ? try(var.object_lock_configuration.years, null) : null

  object_lock_days = var.object_lock_configuration != null ? (
    try(var.object_lock_configuration.days, null) != null ? try(var.object_lock_configuration.days, null) : (
      local.object_lock_years == null ? 1 : null
    )
  ) : null

  create_kms_key = var.kms_key == null || var.kms_key == "" ? 1 : 0

  kms_key_arn = var.kms_key != null && var.kms_key != "" ? var.kms_key : join("", aws_kms_key.this[*].arn)

  manage_encryption = var.encryption ? 1 : 0

  create_replication_role = (var.replication_role == null || var.replication_role == "") && length(var.replication_rules) > 0 ? 1 : 0

  replication_role_arn = var.replication_role != null && var.replication_role != "" ? var.replication_role : join("", aws_iam_role.replication[*].arn)

  replication_role_name = length("CoreS3ReplicationRole_${local.bucket_name}") > 64 ? substr("CoreS3ReplicationRole_${local.bucket_name}", 0, 64) : "CoreS3ReplicationRole_${local.bucket_name}"

  replication_policy_name = length("CoreS3ReplicationPolicy_${local.bucket_name}") > 128 ? substr("CoreS3ReplicationPolicy_${local.bucket_name}", 0, 128) : "CoreS3ReplicationPolicy_${local.bucket_name}"

  destination_bucket_arns = [
    for r in var.replication_rules : try(r.destination.bucket, "")
    if try(r.destination.bucket, null) != null && try(r.destination.bucket, "") != ""
  ]

  replication_resources = concat(
    [aws_s3_bucket.this.arn, "${aws_s3_bucket.this.arn}/*"],
    local.destination_bucket_arns,
    [for arn in local.destination_bucket_arns : "${arn}/*"]
  )

  access_requested = (var.acl != null && var.acl != "") || length(coalesce(try(var.grants, []), [])) > 0

  object_ownership = local.access_requested ? "ObjectWriter" : "BucketOwnerEnforced"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "name_prefix" {
  byte_length = 4
}

resource "aws_kms_key" "this" {
  count = local.create_kms_key

  description             = "Customer managed key for ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:DisableKeyRotation",
          "kms:EnableKeyRotation",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:RetireGrant",
          "kms:RevokeGrant",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateKeyDescription"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.this.arn
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key

  name          = "alias/corebucket-${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled

  tags = merge(var.tags, { Name = local.bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.manage_encryption

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null && var.policy != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy

  depends_on = [
    aws_s3_bucket_public_access_block.this
  ]
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration_status
}

resource "aws_s3_bucket" "logging" {
  count = var.logging != null ? 1 : 0

  bucket        = local.logging_bucket_name
  force_destroy = var.force_destroy

  tags = merge(var.tags, { Name = local.logging_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logging[0].arn}/${try(var.logging.target_prefix, "logs/")}*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.this.arn
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.logging
  ]
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = try(var.logging.target_prefix, "logs/")

  depends_on = [
    aws_s3_bucket_policy.logging
  ]
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []
    content {
      suffix = try(index_document.value.suffix, index_document.value)
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = try(error_document.value.key, error_document.value)
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = try(redirect_all_requests_to.value.host_name, redirect_all_requests_to.value)
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = [1]
        content {
          prefix = try(rule.value.prefix, try(rule.value.filter.prefix, ""))

          dynamic "tag" {
            for_each = coalesce(try(rule.value.filter.tags, []), [])
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }

      dynamic "transition" {
        for_each = coalesce(try(rule.value.transitions, []), [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = coalesce(try(rule.value.noncurrent_version_transitions, []), [])
        content {
          noncurrent_days = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = upper(try(var.object_lock_configuration.mode, "GOVERNANCE"))
      days  = local.object_lock_days
      years = local.object_lock_years
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this
  ]
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = [1]
        content {
          prefix = try(rule.value.prefix, try(rule.value.filter.prefix, ""))
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account, null)
      }

      delete_marker_replication {
        status = try(rule.value.delete_marker_replication_status, "Enabled")
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy.replication
  ]
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role

  name = local.replication_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.this.arn
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = local.replication_role_name })
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role

  name = local.replication_policy_name
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetObjectVersionForReplication",
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = local.replication_resources
      }
    ]
  })
}

output "bucket_id" {
  description = "The resolved S3 bucket ID."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The resolved S3 bucket ARN."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The S3 bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "website_endpoint" {
  description = "The S3 website endpoint when website configuration is enabled."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "kms_key_arn" {
  description = "The KMS key ARN used for bucket encryption."
  value       = local.kms_key_arn
}

output "replication_role_arn" {
  description = "The IAM role ARN used for replication."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion
}

variable "awsRegion" {
  description = "AWS region into which the entire network stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix applied to every resource name."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner of the resources, applied as a tag."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix applied to every resource name."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets auto-assign public IP addresses on launch."
  type        = bool
  default     = false
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "awsAz1" {
  description = "Optional caller-supplied availability zone for the A subnets."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional caller-supplied availability zone for the B subnets."
  type        = string
  default     = null
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in availability zone A."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in availability zone B."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in availability zone A."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in availability zone B."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in availability zone A."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in availability zone B."
  type        = string
  default     = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])

  az2 = var.awsAz2 != null ? var.awsAz2 : (
    var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
  )

  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Project     = var.projectPrefix
    Owner       = var.resourceOwner
    BuildSuffix = var.buildSuffix
    ManagedBy   = "Terraform"
  }

  az1_letter = substr(local.az1, -1, 1)
  az2_letter = substr(local.az2, -1, 1)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-${local.az1_letter}-${var.buildSuffix}"
    Role = "public"
    AZ   = local.az1
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-${local.az2_letter}-${var.buildSuffix}"
    Role = "public"
    AZ   = local.az2
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-${local.az1_letter}-${var.buildSuffix}"
    Role = "mgmt"
    AZ   = local.az1
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-${local.az2_letter}-${var.buildSuffix}"
    Role = "mgmt"
    AZ   = local.az2
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-${local.az1_letter}-${var.buildSuffix}"
    Role = "private"
    AZ   = local.az1
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-${local.az2_letter}-${var.buildSuffix}"
    Role = "private"
    AZ   = local.az2
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rtb-main-${var.buildSuffix}"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the created internet gateway."
  value       = aws_internet_gateway.main.id
}

output "route_table_id" {
  description = "ID of the main route table."
  value       = aws_route_table.main.id
}

output "availability_zones" {
  description = "Resolved availability zones used by the subnets."
  value = {
    az1 = local.az1
    az2 = local.az2
  }
}

output "subnet_ids" {
  description = "IDs of the six created subnets."
  value = {
    public_a  = aws_subnet.public_a.id
    public_b  = aws_subnet.public_b.id
    mgmt_a    = aws_subnet.mgmt_a.id
    mgmt_b    = aws_subnet.mgmt_b.id
    private_a = aws_subnet.private_a.id
    private_b = aws_subnet.private_b.id
  }
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.92.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region in which the resources are created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name applied to every resource created by this configuration."
  type        = string
  default     = "benchmark"
}

variable "rule_count" {
  description = "Number of path based listener rules to create. Rule index N matches /static-N/*."
  type        = number
  default     = 1
}

locals {
  vpc_cidr = "10.0.0.0/16"

  common_tags = {
    Name   = var.name
    Region = var.region
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "benchmark" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "benchmark_a" {
  vpc_id                  = aws_vpc.benchmark.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, 0)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name}-subnet-a"
  })
}

resource "aws_subnet" "benchmark_b" {
  vpc_id                  = aws_vpc.benchmark.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name}-subnet-b"
  })
}

resource "aws_security_group" "alb" {
  name        = "${var.name}-alb"
  description = "Internal ALB traffic restricted to the VPC CIDR"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "All protocols and ports from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  egress {
    description = "All protocols and ports to within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-alb-sg"
  })
}

resource "aws_lb" "benchmark" {
  name                       = "${var.name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.benchmark_a.id, aws_subnet.benchmark_b.id]

  tags = merge(local.common_tags, {
    Name = "${var.name}-alb"
  })
}

resource "aws_lb_target_group" "benchmark" {
  name        = "${var.name}-tg"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.benchmark.id
  target_type = "instance"

  health_check {
    enabled             = true
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-tg"
  })
}

resource "tls_private_key" "benchmark" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "benchmark" {
  private_key_pem = tls_private_key.benchmark.private_key_pem

  subject {
    common_name  = var.name
    organization = "Benchmark"
  }

  validity_period_hours = 8760
  early_renewal_hours   = 720

  dns_names = ["${var.name}.internal"]

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "benchmark" {
  certificate_body = tls_self_signed_cert.benchmark.cert_pem
  private_key      = tls_private_key.benchmark.private_key_pem

  tags = merge(local.common_tags, {
    Name = "${var.name}-cert"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.benchmark.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.benchmark.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-https-listener"
  })
}

resource "aws_lb_listener_rule" "path_based" {
  count = var.rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-rule-${count.index}"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  region = var.region

  # One private subnet definition per CIDR provided, keyed by 1-based index.
  # AZs come from the provider AZ metadata (names[0], names[1], ...).
  private_subnets = {
    for idx, cidr in var.private_subnets :
    tostring(idx + 1) => {
      cidr_block        = cidr
      availability_zone = data.aws_availability_zones.available.names[idx]
      name              = "${var.name_prefix}-private-subnet-${idx + 1}"
    }
  }

  private_route_table_names = {
    for key, subnet in local.private_subnets :
    key => "${var.name_prefix}-private-rt-${key}"
  }

  inbound_acl_rules  = { for idx, rule in var.public_inbound_acl_rules : tostring(idx) => rule }
  outbound_acl_rules = { for idx, rule in var.public_outbound_acl_rules : tostring(idx) => rule }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = each.value.name
  }
}

resource "aws_route_table" "private" {
  for_each = local.private_route_table_names

  vpc_id = aws_vpc.main.id

  tags = {
    Name = each.value
  }
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private : rt.id]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3AccessFromVpc"
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = aws_vpc.main.id
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

# Stateless NACL ingress: the wide ephemeral port range is required so that
# return traffic for outbound connections established on 443 is permitted.
resource "aws_network_acl_rule" "inbound" {
  for_each = local.inbound_acl_rules

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = false
  protocol       = each.value.protocol
  rule_action    = each.value.action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

# Stateless NACL egress: outbound traffic restricted to HTTPS only.
resource "aws_network_acl_rule" "outbound" {
  for_each = local.outbound_acl_rules

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = true
  protocol       = each.value.protocol
  rule_action    = each.value.action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

resource "aws_network_acl_association" "private" {
  for_each = aws_subnet.private

  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[each.key].id
}

variable "region" {
  description = "AWS region where the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to the Name tag of every resource."
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated", "host"], var.instance_tenancy)
    error_message = "instance_tenancy must be one of: default, dedicated, host."
  }
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported within the VPC."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for the private subnets, one per subnet, placed in successive AZs."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]

  validation {
    condition     = length(var.private_subnets) >= 2
    error_message = "At least two private subnet CIDR blocks must be provided."
  }
}

variable "public_inbound_acl_rules" {
  description = "Inbound rules applied to the shared private network ACL."
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound rules applied to the shared private network ACL."
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

output "vpc_id" {
  description = "ID of the private VPC."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = [for subnet in aws_subnet.private : subnet.id]
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = [for route_table in aws_route_table.private : route_table.id]
}

output "network_acl_id" {
  description = "ID of the shared private network ACL."
  value       = aws_network_acl.private.id
}

output "s3_gateway_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create" {
  description = "Controls whether resources should be created"
  type        = bool
  default     = true
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean enabling SQS-managed server-side encryption"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Controls whether to create a queue policy"
  type        = bool
  default     = false
}

variable "create_dlq" {
  description = "Controls whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether to create a redrive allow policy for the dead-letter queue"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue"
  type        = string
  default     = "my-queue"
}

variable "name_prefix" {
  description = "Name prefix of the queue"
  type        = string
  default     = null
}

variable "source_policy_document" {
  description = "Source policy document in JSON format"
  type        = string
  default     = null
}

variable "override_policy_document" {
  description = "Override policy document in JSON format"
  type        = string
  default     = null
}

variable "policy_statements" {
  description = "List of custom policy statements"
  type        = list(any)
  default     = []
}

locals {
  create_dlq = var.create && var.create_dlq

  main_queue_name        = var.fifo_queue ? "${var.name}.fifo" : (var.name_prefix == null ? var.name : null)
  main_queue_name_prefix = var.fifo_queue ? null : var.name_prefix

  dlq_name        = var.fifo_queue ? "${var.name}-dlq.fifo" : (var.name_prefix == null ? "${var.name}-dlq" : null)
  dlq_name_prefix = var.fifo_queue ? null : (var.name_prefix == null ? null : "${var.name_prefix}-dlq-")
}

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name                    = local.main_queue_name
  name_prefix             = local.main_queue_name_prefix
  fifo_queue              = var.fifo_queue
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id       = var.kms_master_key_id
  redrive_policy = local.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = 5
  }) : null

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = local.create_dlq ? 1 : 0

  name                    = local.dlq_name
  name_prefix             = local.dlq_name_prefix
  fifo_queue              = var.fifo_queue
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id       = var.kms_master_key_id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = local.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

data "aws_iam_policy_document" "queue" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_document != null ? [var.source_policy_document] : []
  override_policy_documents = var.override_policy_document != null ? [var.override_policy_document] : []

  dynamic "statement" {
    for_each = var.policy_statements
    content {
      sid         = try(statement.value.sid, null)
      effect      = try(statement.value.effect, "Allow")
      actions     = try(statement.value.actions, null)
      not_actions = try(statement.value.not_actions, null)
      resources = coalesce(
        try(statement.value.resources, null),
        try([statement.value.resource], null),
        [aws_sqs_queue.main[0].arn]
      )
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = try(principals.value.type, null)
          identifiers = try(principals.value.identifiers, null)
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])
        content {
          type        = try(not_principals.value.type, null)
          identifiers = try(not_principals.value.identifiers, null)
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, try(statement.value.condition, []))
        content {
          test     = try(condition.value.test, null)
          variable = try(condition.value.variable, null)
          values   = try(condition.value.values, null)
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].url
  policy    = data.aws_iam_policy_document.queue[0].json
}

terraform {
  required_version = ">= 1.3.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure is queried)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "backup_name" {
  description = "Base name used for the backup vault, IAM role, backup plan and selections."
  type        = string

  validation {
    condition     = length(trimspace(var.backup_name)) > 0
    error_message = "backup_name must be a non-empty string (whitespace only is not allowed)."
  }
}

variable "account_type" {
  description = "Deployment account type. Valid values are \"workload\" or \"backup\"."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer managed KMS key ARN used to encrypt the backup vault. When null a KMS key is created."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON IAM policy document to attach to the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention, in days, for recovery points in the vault lock. When set a vault lock is created."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention, in days, for recovery points in the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional number of days before the vault lock can be changed."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to route backup vault events to the SNS topic created by this configuration."
  type        = bool
  default     = false
}

variable "backup_vault_events" {
  description = "List of backup vault events that should trigger SNS notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "backup_rule_schedule" {
  description = "Cron or rate expression for the backup plan rule schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "copy_destinations" {
  description = "List of cross-region/cross-account copy targets. A destination vault is created in this configuration for each entry."
  type = list(object({
    cold_storage_after = number
    delete_after       = number
  }))
  default = []
}

variable "selection_resources" {
  description = "Optional list of resource ARNs to include in an explicit resource-based backup selection."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all resources created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      BackupName  = var.backup_name
      AccountType = var.account_type
    }
  )

  managed_backup_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

###############################################################################
# KMS key + alias (used when no external key ARN is supplied)
###############################################################################

resource "aws_kms_key" "backup" {
  description             = "Customer managed key for AWS Backup vault ${var.backup_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.backup_name}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

###############################################################################
# Backup vault (stateful)
###############################################################################

resource "aws_backup_vault" "main" {
  name        = var.backup_name
  kms_key_arn = coalesce(var.kms_key_arn, aws_kms_key.backup.arn)
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "main" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "main" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

###############################################################################
# SNS topic for vault notifications (created in this configuration)
###############################################################################

resource "aws_sns_topic" "backup_notifications" {
  name = "${var.backup_name}-backup-notifications"
  tags = local.common_tags
}

resource "aws_sns_topic_policy" "backup_notifications" {
  arn = aws_sns_topic.backup_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAwsBackupPublish"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.backup_notifications.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_backup_vault_notifications" "main" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = aws_sns_topic.backup_notifications.arn
  backup_vault_events = var.backup_vault_events
}

###############################################################################
# Destination vaults for copy actions (declared in-file, referenced by address)
###############################################################################

resource "aws_backup_vault" "destination" {
  count = length(var.copy_destinations)

  name        = "${var.backup_name}-destination-${count.index}"
  kms_key_arn = coalesce(var.kms_key_arn, aws_kms_key.backup.arn)
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role + managed policy attachment (workload accounts only)
###############################################################################

resource "aws_iam_role" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  name_prefix = "aws-backup-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAwsBackupAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = local.managed_backup_policy_arn
}

###############################################################################
# Backup plan + rule (workload accounts only)
###############################################################################

resource "aws_backup_plan" "workload" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"
  tags = local.common_tags

  rule {
    rule_name         = "${var.backup_name}-backup-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.backup_rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = merge(
      local.common_tags,
      {
        BackupPlan = "plan-${var.backup_name}-backup"
        Rule       = "${var.backup_name}-backup-rule"
      }
    )

    dynamic "copy_action" {
      for_each = var.copy_destinations

      content {
        destination_vault_arn = aws_backup_vault.destination[copy_action.key].arn

        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after
          delete_after       = copy_action.value.delete_after
        }
      }
    }
  }
}

###############################################################################
# Backup selections (workload accounts only)
###############################################################################

resource "aws_backup_selection" "tags" {
  count = var.account_type == "workload" ? 1 : 0

  name         = "${var.backup_name}-tags-selection"
  plan_id      = aws_backup_plan.workload[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = var.account_type == "workload" && length(var.selection_resources) > 0 ? 1 : 0

  name         = "${var.backup_name}-resources-selection"
  plan_id      = aws_backup_plan.workload[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

###############################################################################
# Inputs
###############################################################################

variable "name" {
  description = "Base name used for the AWS Config stack. Falls back to a generated petname when null or empty."
  type        = string
  default     = "config"
}

variable "environment" {
  description = "Environment tag applied to every taggable resource."
  type        = string
  default     = "prod"
}

###############################################################################
# Provider metadata (static / local lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# Naming convention: variable value, or petname fallback when null/empty
###############################################################################

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  config_name = coalesce(var.name, "config-${random_pet.this.id}")

  # aws_config_configuration_recorder exports no arn attribute, so the recorder
  # ARN is assembled from non-hardcoded region/account metadata.
  config_recorder_arn = "arn:aws:config:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:config-recorder/${local.config_name}"

  tags = {
    Name        = local.config_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# KMS key for SNS / Config encryption
###############################################################################

data "aws_iam_policy_document" "kms_config" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowConfigServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowConfigRoleUse"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsServiceUseViaService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "config" {
  description             = "Customer managed key used to encrypt the AWS Config SNS topic and delivered records."
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_config.json

  tags = local.tags
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.config_name}-config"
  target_key_id = aws_kms_key.config.key_id
}

###############################################################################
# AWS Config snapshot storage bucket
###############################################################################

resource "aws_s3_bucket" "config_snapshot" {
  # Force destroy is explicitly required so stack teardown always succeeds.
  bucket        = "${local.config_name}-config-snapshot-${data.aws_caller_identity.current.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_snapshot_bucket" {
  statement {
    sid    = "AllowConfigServiceGetBucketAcl"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config_snapshot.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.config_recorder_arn]
    }
  }

  statement {
    sid    = "AllowConfigServicePutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config_snapshot.arn}/awsconfig/records/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.config_recorder_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  policy = data.aws_iam_policy_document.config_snapshot_bucket.json
}

###############################################################################
# SNS topic for AWS Config notifications
###############################################################################

resource "aws_sns_topic" "config" {
  name              = local.config_name
  kms_master_key_id = aws_kms_key.config.arn

  tags = local.tags
}

data "aws_iam_policy_document" "sns_config" {
  statement {
    sid    = "AllowConfigServicePublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.config_recorder_arn]
    }
  }
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.sns_config.json
}

###############################################################################
# IAM role assumed by AWS Config
###############################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid    = "AllowConfigServiceAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "config" {
  name               = local.config_name
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_inline" {
  statement {
    sid    = "SnapshotBucketAclRead"
    effect = "Allow"

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config_snapshot.arn]
  }

  statement {
    sid    = "SnapshotBucketObjectWrite"
    effect = "Allow"

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config_snapshot.arn}/*"]
  }

  statement {
    sid    = "ConfigTopicPublish"
    effect = "Allow"

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_iam_role_policy" "config_inline" {
  name   = "${local.config_name}-inline"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_inline.json
}

###############################################################################
# AWS Config recorder, delivery channel and status
###############################################################################

resource "aws_config_configuration_recorder" "config" {
  name     = local.config_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "config" {
  name           = local.config_name
  s3_bucket_name = aws_s3_bucket.config_snapshot.id
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config.arn

  depends_on = [
    aws_s3_bucket_policy.config_snapshot,
    aws_iam_role_policy_attachment.config_managed,
    aws_iam_role_policy.config_inline,
    aws_sns_topic_policy.config,
  ]
}

resource "aws_config_configuration_recorder_status" "config" {
  name       = aws_config_configuration_recorder.config.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.config]
}

###############################################################################
# Managed AWS Config rules
###############################################################################

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name = "cloudtrail-enabled"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  tags = local.tags
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name = "iam-pw-policy"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  tags = local.tags
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name = "root-mfa-enabled"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name = "acm-expiration-check"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  tags = local.tags
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  tags = local.tags
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["S3::Bucket"]
  }

  tags = local.tags
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "dev"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    Project     = "elastic-disaster-recovery"
    Environment = var.environment
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "drs_agent_assume_role" {
  statement {
    sid     = "AllowDRSAgentServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:drs:*:${local.account_id}:source-servers/*"]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }
  }
}

data "aws_iam_policy_document" "drs_failback_assume_role" {
  statement {
    sid     = "AllowDRSFailbackServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:drs:*:${local.account_id}:recovery-instances/*"]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "initializer_assume_role" {
  statement {
    sid     = "AllowCallingIdentityAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"
      identifiers = [
        data.aws_caller_identity.current.arn,
        "arn:${local.partition}:iam::${local.account_id}:root"
      ]
    }
  }
}

resource "aws_iam_role" "drs_agent_role" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_agent_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "drs_failback_role" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_failback_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "drs_conversion_server_role" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "drs_recovery_instance_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "drs_replication_server_role" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "drs_recovery_instance_launch_actions_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy" "drs_agent_policy" {
  name        = "AWSElasticDisasterRecoveryAgentPolicy"
  path_prefix = "/service-role/"
}

data "aws_iam_policy" "drs_failback_policy" {
  name        = "AWSElasticDisasterRecoveryFailbackPolicy"
  path_prefix = "/service-role/"
}

data "aws_iam_policy" "drs_conversion_server_policy" {
  name        = "AWSElasticDisasterRecoveryConversionServerPolicy"
  path_prefix = "/service-role/"
}

data "aws_iam_policy" "drs_recovery_instance_policy" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
  path_prefix = "/service-role/"
}

data "aws_iam_policy" "drs_replication_server_policy" {
  name        = "AWSElasticDisasterRecoveryReplicationServerPolicy"
  path_prefix = "/service-role/"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name        = "AmazonSSMManagedInstanceCore"
  path_prefix = "/"
}

resource "aws_iam_role_policy_attachment" "drs_agent_policy_attachment" {
  role       = aws_iam_role.drs_agent_role.name
  policy_arn = data.aws_iam_policy.drs_agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_failback_policy_attachment" {
  role       = aws_iam_role.drs_failback_role.name
  policy_arn = data.aws_iam_policy.drs_failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server_policy_attachment" {
  role       = aws_iam_role.drs_conversion_server_role.name
  policy_arn = data.aws_iam_policy.drs_conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_role.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_replication_server_policy_attachment" {
  role       = aws_iam_role.drs_replication_server_role.name
  policy_arn = data.aws_iam_policy.drs_replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_launch_actions_recovery_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions_role.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_launch_actions_ssm_core_attachment" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions_role.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

resource "aws_iam_instance_profile" "drs_recovery_instance_launch_actions_profile" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsProfile"
  path = "/service-role/"
  role = aws_iam_role.drs_recovery_instance_launch_actions_role.name
  tags = local.common_tags
}

resource "aws_iam_instance_profile" "drs_recovery_instance_profile" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceProfile"
  path = "/service-role/"
  role = aws_iam_role.drs_recovery_instance_role.name
  tags = local.common_tags
}

resource "aws_iam_role" "drs_initializer_role" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.initializer_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "initialize_policy" {
  statement {
    sid       = "AllowDRSInitializeService"
    effect    = "Allow"
    actions   = ["drs:InitializeService"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowCreateDRSServiceLinkedRole"
    effect    = "Allow"
    actions   = ["iam:CreateServiceLinkedRole"]
    resources = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"]

    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  statement {
    sid     = "AllowDRSInstanceProfileManagement"
    effect  = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:DeleteInstanceProfile"
    ]
    resources = [
      aws_iam_instance_profile.drs_recovery_instance_profile.arn,
      aws_iam_instance_profile.drs_recovery_instance_launch_actions_profile.arn
    ]
  }

  statement {
    sid     = "AllowPassDRSServiceRoles"
    effect  = "Allow"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.drs_agent_role.arn,
      aws_iam_role.drs_failback_role.arn,
      aws_iam_role.drs_conversion_server_role.arn,
      aws_iam_role.drs_recovery_instance_role.arn,
      aws_iam_role.drs_replication_server_role.arn,
      aws_iam_role.drs_recovery_instance_launch_actions_role.arn
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ec2.amazonaws.com", "drs.amazonaws.com"]
    }
  }

  statement {
    sid       = "AllowEC2FullAccessForDRSInitialization"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  statement {
    sid     = "AllowAttachDRSManagedPolicies"
    effect  = "Allow"
    actions = ["iam:AttachRolePolicy"]
    resources = [
      aws_iam_role.drs_agent_role.arn,
      aws_iam_role.drs_failback_role.arn,
      aws_iam_role.drs_conversion_server_role.arn,
      aws_iam_role.drs_recovery_instance_role.arn,
      aws_iam_role.drs_replication_server_role.arn,
      aws_iam_role.drs_recovery_instance_launch_actions_role.arn
    ]

    condition {
      test     = "StringLike"
      variable = "iam:PolicyARN"
      values = [
        data.aws_iam_policy.drs_agent_policy.arn,
        data.aws_iam_policy.drs_failback_policy.arn,
        data.aws_iam_policy.drs_conversion_server_policy.arn,
        data.aws_iam_policy.drs_recovery_instance_policy.arn,
        data.aws_iam_policy.drs_replication_server_policy.arn
      ]
    }
  }
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Policy for initializing AWS Elastic Disaster Recovery."
  policy      = data.aws_iam_policy_document.initialize_policy.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "drs_initializer_policy_attachment" {
  role       = aws_iam_role.drs_initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "environment" {
  description = "Environment name applied to every resource tag."
  type        = string
  default     = "prod"
}

locals {
  # First four availability zones in the region, discovered dynamically.
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 4)

  external_vpc_cidr = "10.41.0.0/16"
  internal_vpc_cidr = "10.40.0.0/16"

  external_subnet_cidrs = ["10.41.0.0/24", "10.41.1.0/24", "10.41.2.0/24", "10.41.3.0/24"]
  internal_subnet_cidrs = ["10.40.0.0/24", "10.40.1.0/24", "10.40.2.0/24", "10.40.3.0/24"]

  subnet_names = ["Subnet0-1a", "Subnet1-1b", "Subnet2-1c", "Subnet3-1d"]

  common_tags = {
    environment = var.environment
  }
}

# --------------------------------------------------------------------------
# External (internet-facing) VPC
# --------------------------------------------------------------------------

resource "aws_vpc" "external" {
  cidr_block           = local.external_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = var.environment
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  # No ingress or egress rules: the default security group denies all traffic.
  tags = merge(local.common_tags, {
    Name = "Production External Default SG"
  })
}

resource "aws_subnet" "external" {
  count = length(local.external_subnet_cidrs)

  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(local.common_tags, {
    Name = local.subnet_names[count.index]
  })
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = merge(local.common_tags, {
    Name = "External GW"
  })
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = merge(local.common_tags, {
    Name = "External Route Table"
  })
}

resource "aws_route_table_association" "external" {
  count = length(local.external_subnet_cidrs)

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "Production External Default NACL"
  })
}

# --------------------------------------------------------------------------
# Internal (isolated) VPC
# --------------------------------------------------------------------------

resource "aws_vpc" "internal" {
  cidr_block       = local.internal_vpc_cidr
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = var.environment
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  # No ingress or egress rules: the default security group denies all traffic.
  tags = merge(local.common_tags, {
    Name = "Production Internal Default SG"
  })
}

resource "aws_subnet" "internal" {
  count = length(local.internal_subnet_cidrs)

  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(local.common_tags, {
    Name = local.subnet_names[count.index]
  })
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "Production Internal Default NACL"
  })
}

# The internal subnets are automatically associated with the internal VPC's
# default network ACL (managed above). No internet gateway, NAT gateway, or
# public route table is attached to the internal VPC, keeping it isolated.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.95.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "= 4.0.5"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "resource_prefix" {
  description = "Prefix applied to all resource names created by this stack."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional existing ACM certificate ARN for the HTTPS listener. When null a self-signed certificate is generated and imported."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public URL override used for the n8n WEBHOOK_URL."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of n8n tasks in the ECS service."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image used for the n8n task."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"
}

###############################################################################
# Provider metadata and static lookups
###############################################################################

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  name = var.resource_prefix

  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn

  endpoint = coalesce(var.url, "https://${aws_lb.main.dns_name}")

  common_tags = {
    Project   = var.resource_prefix
    ManagedBy = "terraform"
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-${count.index}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security Groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${local.name}-alb-sg"
  description = "Allow HTTP/HTTPS ingress to the ${local.name} internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-alb-sg"
  })
}

resource "aws_security_group" "ecs_tasks" {
  name        = "${local.name}-ecs-sg"
  description = "Allow n8n container traffic only from the ${local.name} ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n container port from the ALB"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-ecs-sg"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name}-efs-sg"
  description = "Allow NFS traffic to the ${local.name} EFS file system from the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from the VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-efs-sg"
  })
}

###############################################################################
# Load Balancer
###############################################################################

resource "aws_lb" "main" {
  name                       = "${local.name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-alb"
  })
}

resource "aws_lb_target_group" "n8n" {
  name                 = "${local.name}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-tg"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-https-listener"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-http-listener"
  })
}

###############################################################################
# Self-signed certificate (only when no certificate_arn is supplied)
###############################################################################

resource "tls_private_key" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = aws_lb.main.dns_name
    organization = "n8n-self-signed"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]

  dns_names = [aws_lb.main.dns_name]
}

resource "aws_acm_certificate" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  certificate_body  = tls_self_signed_cert.self_signed[0].cert_pem
  private_key       = tls_private_key.self_signed[0].private_key_pem
  certificate_chain = tls_self_signed_cert.self_signed[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-self-signed-cert"
  })
}

###############################################################################
# EFS
###############################################################################

resource "aws_efs_file_system" "n8n" {
  creation_token = "${local.name}-efs"
  encrypted      = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-efs-ap"
  })
}

resource "aws_efs_mount_target" "n8n" {
  count = 3

  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# ECS Cluster and Logging
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "${local.name}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster"
  })
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-logs"
  })
}

###############################################################################
# IAM
###############################################################################

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "AllowEcsTasksToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.name}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-task-role"
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.name}-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      },
      {
        Sid    = "AllowEfsClientAccess"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
        ]
        Resource = aws_efs_file_system.n8n.arn
      },
    ]
  })
}

resource "aws_iam_role" "ecs_execution" {
  name               = "${local.name}-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-execution-role"
  })
}

resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.name}-execution-policy"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

###############################################################################
# ECS Task Definition
###############################################################################

resource "aws_ecs_task_definition" "n8n" {
  family                   = "${var.resource_prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.endpoint
        },
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "n8n"
        }
      }
    }
  ])

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-task"
  })
}

###############################################################################
# ECS Service
###############################################################################

resource "aws_ecs_service" "n8n" {
  name            = "${local.name}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_efs_mount_target.n8n,
    aws_route_table_association.public,
    aws_iam_role_policy.ecs_task,
    aws_iam_role_policy.ecs_execution,
    aws_iam_role_policy_attachment.ecs_execution,
  ]

  lifecycle {
    ignore_changes = [desired_count]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-service"
  })
}

###############################################################################
# Outputs
###############################################################################

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "n8n_endpoint" {
  description = "Resolved HTTPS endpoint for the n8n instance."
  value       = local.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.255.0.0/16"

  common_tags = {
    Application = "doSomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_db_subnet_group" "rds" {
  name        = "quasar-rds-subnet-group"
  description = "Subnet group for the Quasar multi-AZ RDS deployment"
  subnet_ids  = [aws_subnet.rds_a.id, aws_subnet.rds_b.id]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS Subnet Group"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host SSH access for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the approved administrative range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA proxy load balancer edge for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the public edge"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the public edge"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "CI/CD automation host for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI from the HA proxy security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from the Jenkins security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database access for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from the ETL security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  ingress {
    description = "PostgreSQL from any source (explicit user-requested exception)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.95.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "= 3.2.1"
    }
    local = {
      source  = "hashicorp/local"
      version = "= 2.4.0"
    }
  }
}

###############################################################################
# Global creation controls
###############################################################################

variable "create" {
  description = "Master switch that gates every resource in this module."
  type        = bool
  default     = true
}

variable "create_app" {
  description = "Create the CodeDeploy application (Lambda compute platform)."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Use an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "create_deployment_group" {
  description = "Create the CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Use an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "create_codedeploy_role" {
  description = "Create the IAM service role used by CodeDeploy."
  type        = bool
  default     = true
}

variable "attach_hooks_policy" {
  description = "Attach the inline lambda:InvokeFunction policy for lifecycle hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Attach the inline sns:Publish policy for deployment triggers."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Render the AppSpec revision and the deployment shell script."
  type        = bool
  default     = false
}

variable "save_deploy_script" {
  description = "Persist the generated deployment script to disk."
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Execute the generated deployment script via a null_resource provisioner."
  type        = bool
  default     = false
}

variable "monitor_deployment" {
  description = "Poll aws deploy get-deployment until the deployment finishes."
  type        = bool
  default     = true
}

###############################################################################
# Module inputs
###############################################################################

variable "app_name" {
  description = "Name of the CodeDeploy application."
  type        = string
  default     = "lambda-blue-green-app"
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  type        = string
  default     = "lambda-blue-green-dg"
}

variable "function_name" {
  description = "Name of the Lambda function deployed with blue/green."
  type        = string
  default     = "lambda-blue-green-fn"
}

variable "alias_name" {
  description = "Lambda alias that CodeDeploy shifts traffic between."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Lambda version currently serving traffic."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Lambda version that traffic is shifted to."
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked before traffic is allowed."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked after traffic is allowed."
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration name."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "aws_cli_command" {
  description = "AWS CLI executable used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds slept between aws deploy get-deployment polls."
  type        = number
  default     = 5
}

variable "service_principals" {
  description = "Service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "triggers" {
  description = "Notification triggers attached to the deployment group."
  type = list(object({
    trigger_name       = string
    trigger_target_arn = optional(string, "")
    trigger_events     = optional(list(string), ["DeploymentSuccess", "DeploymentFailure"])
  }))
  default = []
}

variable "alarms" {
  description = "CloudWatch alarm names monitored by the deployment group."
  type        = list(string)
  default     = []
}

variable "ignore_poll_alarm_failure" {
  description = "Continue the deployment when alarm polling fails."
  type        = bool
  default     = true
}

variable "cloudwatch_alarms" {
  description = "Optional CloudWatch metric alarms created for deployment monitoring."
  type = map(object({
    namespace           = string
    metric_name         = string
    comparison_operator = string
    threshold           = number
    evaluation_periods  = number
    period              = number
    statistic           = string
    alarm_description   = string
  }))
  default = {}
}

variable "existing_app_name" {
  description = "Name of an existing CodeDeploy application (when use_existing_app is true)."
  type        = string
  default     = ""
}

variable "existing_deployment_group_name" {
  description = "Name of an existing deployment group (when use_existing_deployment_group is true)."
  type        = string
  default     = ""
}

variable "existing_codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy service role (when create_codedeploy_role is false)."
  type        = string
  default     = ""
}

variable "deploy_script_dir" {
  description = "Directory that receives the generated AppSpec and deployment script."
  type        = string
  default     = ""
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period before the deployment CMK is deleted."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = var.app_name

  tags = merge(
    {
      Environment = "dev"
      ManagedBy   = "terraform"
      Project     = var.app_name
      Component   = "lambda-blue-green-deployment"
    },
    var.tags,
  )

  # Every cardinality guard below is derived exclusively from input variables
  # so that count/for_each are fully decidable at plan time.
  create_app              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_role             = var.create && var.create_codedeploy_role
  create_deployment       = var.create && var.create_deployment
  write_deploy_script     = local.create_deployment && (var.save_deploy_script || var.run_deployment)
  run_deploy              = local.create_deployment && var.run_deployment
  monitor_deployment      = var.monitor_deployment ? "true" : "false"

  attach_hooks    = var.create && var.create_codedeploy_role && var.attach_hooks_policy
  attach_triggers = var.create && var.create_codedeploy_role && var.attach_triggers_policy

  effective_app_name = local.create_app ? aws_codedeploy_app.this[0].name : (var.use_existing_app ? var.existing_app_name : var.app_name)

  effective_deployment_group_name = local.create_deployment_group ? (
    aws_codedeploy_deployment_group.this[0].deployment_group_name
  ) : (var.use_existing_deployment_group ? var.existing_deployment_group_name : var.deployment_group_name)

  effective_role_arn = local.create_role ? aws_iam_role.codedeploy[0].arn : var.existing_codedeploy_role_arn

  deployment_notifications_topic_name = "${local.name_prefix}-deployment-notifications"

  # Constructed rather than referenced from the topic resource so the KMS key
  # policy can scope aws:SourceArn without creating a dependency cycle with the
  # topic's depends_on the key policy.
  deployment_notifications_topic_arn = "arn:${data.aws_partition.current.partition}:sns:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.deployment_notifications_topic_name}"

  # Absolute paths keep the packaging command immune to the harness working
  # directory (path.module may evaluate to ".") and allow zip to be invoked
  # without any cd that would reinterpret relative output paths.
  lambda_build_dir   = abspath("${path.module}/build")
  lambda_src_dir     = abspath("${path.module}/build/lambda_src")
  lambda_source_file = abspath("${path.module}/build/lambda_src/index.py")
  lambda_zip_path    = abspath("${path.module}/build/lambda.zip")

  lambda_handler_source = <<-PY
def handler(event, context):
    return {
        "statusCode": 200,
        "body": "blue/green deployment target",
    }
PY

  output_dir         = var.deploy_script_dir != "" ? var.deploy_script_dir : "${path.module}/generated"
  appspec_path       = "${local.output_dir}/appspec.json"
  deploy_script_path = "${local.output_dir}/deploy.sh"

  # Used only as an attribute VALUE (never as a count/for_each input) so that
  # unknown-at-plan ARNs are resolved during apply.
  hook_resources = compact(concat(
    [try(aws_lambda_function.app[0].arn, "")],
    [try(aws_lambda_alias.live[0].arn, "")],
    var.before_allow_traffic_hook_arn != "" ? [var.before_allow_traffic_hook_arn] : [],
    var.after_allow_traffic_hook_arn != "" ? [var.after_allow_traffic_hook_arn] : [],
  ))

  appspec = {
    version = "0.0"
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = [
      merge(
        var.before_allow_traffic_hook_arn != "" ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
        var.after_allow_traffic_hook_arn != "" ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {},
      )
    ]
  }

  appspec_json = jsonencode(local.appspec)

  appspec_revision = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_json
    }
  })

  deploy_script = <<-EOT
#!/usr/bin/env bash
set -euo pipefail

APPLICATION_NAME="${local.effective_app_name}"
DEPLOYMENT_GROUP_NAME="${local.effective_deployment_group_name}"
REVISION='${local.appspec_revision}'

echo "Requesting CodeDeploy blue/green deployment for $APPLICATION_NAME / $DEPLOYMENT_GROUP_NAME"

DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name "$APPLICATION_NAME" \
  --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
  --deployment-config-name "${var.deployment_config_name}" \
  --description "Blue/green deployment for $APPLICATION_NAME" \
  --revision "$REVISION" \
  --query 'deploymentId' \
  --output text)

echo "Created deployment $DEPLOYMENT_ID"

if [ "${local.monitor_deployment}" = "true" ]; then
  while true; do
    STATUS=$(${var.aws_cli_command} deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)
    echo "Deployment $DEPLOYMENT_ID status: $STATUS"
    if [ "$STATUS" = "Succeeded" ]; then
      echo "Deployment $DEPLOYMENT_ID completed successfully."
      break
    fi
    if [ "$STATUS" = "Failed" ] || [ "$STATUS" = "Stopped" ]; then
      echo "Deployment $DEPLOYMENT_ID finished with status $STATUS." >&2
      exit 1
    fi
    sleep ${var.get_deployment_sleep_timer}
  done
fi
EOT
}

###############################################################################
# Lambda compute being deployed (greenfield)
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda" {
  count = var.create ? 1 : 0

  name               = "${local.name_prefix}-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy" "lambda_basic_execution" {
  name = "AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count = var.create ? 1 : 0

  role       = aws_iam_role.lambda[0].name
  policy_arn = data.aws_iam_policy.lambda_basic_execution.arn
}

# Single packaging mechanism: write the handler and produce the zip with the
# tooling already present in the execution image (no archive provider needed).
# All paths are absolute and no `cd` is used, so the archive output always
# resolves against an existing directory.
resource "null_resource" "lambda_package" {
  count = var.create ? 1 : 0

  triggers = {
    handler_hash = md5(local.lambda_handler_source)
    zip_path     = local.lambda_zip_path
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = "mkdir -p '${local.lambda_build_dir}' '${local.lambda_src_dir}' && printf '%s' '${base64encode(local.lambda_handler_source)}' | base64 -d > '${local.lambda_source_file}' && rm -f '${local.lambda_zip_path}' && zip -j '${local.lambda_zip_path}' '${local.lambda_source_file}'"
  }
}

resource "aws_lambda_function" "app" {
  count = var.create ? 1 : 0

  function_name    = var.function_name
  role             = aws_iam_role.lambda[0].arn
  handler          = "index.handler"
  runtime          = "python3.11"
  filename         = local.lambda_zip_path
  source_code_hash = try(filebase64sha256(local.lambda_zip_path), "")
  publish          = true

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    null_resource.lambda_package,
  ]
}

resource "aws_lambda_alias" "live" {
  count = var.create ? 1 : 0

  name             = var.alias_name
  description      = "Live alias managed by Terraform"
  function_name    = aws_lambda_function.app[0].function_name
  function_version = aws_lambda_function.app[0].version
}

###############################################################################
# KMS key protecting the deployment notifications topic
###############################################################################

resource "aws_kms_key" "deployment" {
  count = var.create ? 1 : 0

  description             = "CMK for CodeDeploy blue/green deployment notifications"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = local.tags
}

data "aws_iam_policy_document" "deployment_kms" {
  count = var.create ? 1 : 0

  statement {
    sid    = "EnableAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = [aws_kms_key.deployment[0].arn]
  }

  statement {
    sid    = "AllowServicesToUseKey"
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = [
        "sns.amazonaws.com",
        "codedeploy.amazonaws.com",
        "cloudwatch.amazonaws.com",
      ]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.deployment[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.deployment_notifications_topic_arn]
    }
  }
}

resource "aws_kms_key_policy" "deployment" {
  count = var.create ? 1 : 0

  key_id = aws_kms_key.deployment[0].key_id
  policy = data.aws_iam_policy_document.deployment_kms[0].json
}

resource "aws_kms_alias" "deployment" {
  count = var.create ? 1 : 0

  name          = "alias/${local.deployment_notifications_topic_name}"
  target_key_id = aws_kms_key.deployment[0].key_id
}

###############################################################################
# CodeDeploy application, roles and deployment group
###############################################################################

resource "aws_codedeploy_app" "this" {
  count = local.create_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"

  tags = local.tags
}

data "aws_iam_policy" "codedeploy_lambda" {
  name = "AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    sid     = "CodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = local.create_role ? 1 : 0

  name               = "${local.name_prefix}-codedeploy-role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = local.create_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = data.aws_iam_policy.codedeploy_lambda.arn
}

data "aws_iam_policy_document" "codedeploy_hooks" {
  count = local.attach_hooks ? 1 : 0

  statement {
    sid       = "InvokeLambdaLifecycleHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_resources
  }
}

resource "aws_iam_role_policy" "codedeploy_hooks" {
  count = local.attach_hooks ? 1 : 0

  name   = "${local.name_prefix}-codedeploy-hooks"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.codedeploy_hooks[0].json
}

resource "aws_sns_topic" "deployment_notifications" {
  count = var.create ? 1 : 0

  name              = local.deployment_notifications_topic_name
  kms_master_key_id = aws_kms_key.deployment[0].arn

  tags = local.tags

  depends_on = [aws_kms_key_policy.deployment]
}

data "aws_iam_policy_document" "codedeploy_triggers" {
  count = local.attach_triggers ? 1 : 0

  statement {
    sid       = "PublishDeploymentNotifications"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.deployment_notifications[0].arn]
  }
}

resource "aws_iam_role_policy" "codedeploy_triggers" {
  count = local.attach_triggers ? 1 : 0

  name   = "${local.name_prefix}-codedeploy-triggers"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.codedeploy_triggers[0].json
}

resource "aws_cloudwatch_metric_alarm" "deployment" {
  for_each = var.create ? var.cloudwatch_alarms : {}

  alarm_name          = each.key
  namespace           = each.value.namespace
  metric_name         = each.value.metric_name
  comparison_operator = each.value.comparison_operator
  threshold           = each.value.threshold
  evaluation_periods  = each.value.evaluation_periods
  period              = each.value.period
  statistic           = each.value.statistic
  alarm_description   = each.value.alarm_description
  treat_missing_data  = "notBreaching"

  tags = local.tags
}

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group ? 1 : 0

  app_name               = local.effective_app_name
  deployment_group_name  = var.deployment_group_name
  deployment_config_name = var.deployment_config_name
  service_role_arn       = local.effective_role_arn

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarms) > 0 ? [1] : []

    content {
      enabled                   = true
      alarms                    = var.alarms
      ignore_poll_alarm_failure = var.ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.triggers

    content {
      trigger_name = trigger_configuration.value.trigger_name
      trigger_target_arn = (
        trigger_configuration.value.trigger_target_arn != ""
        ? trigger_configuration.value.trigger_target_arn
        : aws_sns_topic.deployment_notifications[0].arn
      )
      trigger_events = trigger_configuration.value.trigger_events
    }
  }

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.codedeploy_lambda,
    aws_iam_role_policy.codedeploy_hooks,
    aws_iam_role_policy.codedeploy_triggers,
  ]
}

###############################################################################
# AppSpec + deployment script rendering
###############################################################################

resource "local_file" "appspec" {
  count = local.create_deployment ? 1 : 0

  filename        = local.appspec_path
  file_permission = "0644"
  content         = local.appspec_json
}

resource "local_file" "deploy_script" {
  count = local.write_deploy_script ? 1 : 0

  filename        = local.deploy_script_path
  file_permission = "0755"
  content         = local.deploy_script
}

resource "null_resource" "deploy" {
  count = local.run_deploy ? 1 : 0

  triggers = {
    force_deploy    = uuid()
    app             = local.effective_app_name
    group           = local.effective_deployment_group_name
    current_version = var.current_version
    target_version  = var.target_version
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local_file.deploy_script[0].filename
  }

  depends_on = [
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
    aws_iam_role.codedeploy,
    aws_iam_role_policy_attachment.codedeploy_lambda,
    aws_iam_role_policy.codedeploy_hooks,
    aws_iam_role_policy.codedeploy_triggers,
    aws_lambda_function.app,
    aws_lambda_alias.live,
    local_file.appspec,
    local_file.deploy_script,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "code_deploy_app_name" {
  description = "Name of the CodeDeploy application backing the pipeline."
  value       = local.effective_app_name
}

output "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  value       = local.effective_deployment_group_name
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy service role."
  value       = local.effective_role_arn
}

output "appspec_path" {
  description = "Path of the rendered AppSpec JSON revision."
  value       = try(local_file.appspec[0].filename, "")
}

output "deploy_script_path" {
  description = "Path of the generated deployment shell script."
  value       = try(local_file.deploy_script[0].filename, "")
}

output "deployment_trigger_id" {
  description = "Identifier of the null_resource that triggers deployments."
  value       = try(null_resource.deploy[0].id, "")
}

output "lambda_function_name" {
  description = "Name of the Lambda function targeted by blue/green deployments."
  value       = try(aws_lambda_function.app[0].function_name, var.function_name)
}

output "lambda_alias_arn" {
  description = "Qualified ARN of the Lambda alias receiving traffic."
  value       = try(aws_lambda_alias.live[0].arn, "")
}

output "lambda_zip_path" {
  description = "Absolute path of the packaged Lambda deployment archive."
  value       = local.lambda_zip_path
}

output "deployment_notifications_topic_arn" {
  description = "ARN of the SNS topic used for deployment notifications."
  value       = try(aws_sns_topic.deployment_notifications[0].arn, "")
}

output "deployment_kms_key_arn" {
  description = "ARN of the CMK encrypting the deployment notifications topic."
  value       = try(aws_kms_key.deployment[0].arn, "")
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "internal_domain_name" {
  description = "Internal DNS domain name resolved by the private Route 53 hosted zone and DHCP option set."
  type        = string
  default     = "internal"
}

variable "admin_cidrs" {
  description = "List of administrator CIDR blocks allowed to SSH into instances."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "extra_tags" {
  description = "Additional tags merged into the common tag set."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Environment = var.environment
      Project     = "multi-tier-network"
      ManagedBy   = "terraform"
    },
    var.extra_tags
  )

  azs = data.aws_availability_zones.available.names
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "main" })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "ig" })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = [cidrhost(aws_vpc.main.cidr_block, 2), "8.8.8.8"]

  tags = merge(local.common_tags, { Name = "${var.internal_domain_name}-dhcp-options" })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, { Name = var.internal_domain_name })
}

# -------------------------
# Subnets
# -------------------------

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "reserved" })
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = local.azs[1]
