# -------------------------
# Security groups
# -------------------------

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from administrator CIDRs and from group members"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from administrator CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH between group members"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Internal VPC traffic only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "Home SSH" })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from within the VPC and from group members"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH between group members"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Internal VPC traffic only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "Packer SSH" })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the current AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Append a random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional JSON bucket policy merged on top of the managed compliance policy."
  type        = string
  default     = null
}

variable "enable_s3_public_access_block" {
  description = "Enable the S3 public access block on the bucket."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Optional KMS key ID/ARN. When set, aws:kms SSE is used instead of AES256."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket keys (only applied when a KMS key is configured)."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Bucket versioning status (Enabled, Suspended, or Disabled)."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even when it contains objects."
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable S3 storage class analytics for the whole bucket."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable the S3 bucket inventory report."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Name of the target bucket used for server access logging. Disabled when null."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Override the server access log target prefix. Defaults to s3/<bucket-id>/."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled/Suspended). Disabled when null."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Optional canned ACL. Discouraged with BucketOwnerEnforced ownership; opt-in only."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string), [])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "environment" {
  description = "Environment tag applied to all taggable resources."
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional tags applied to taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (account / provider metadata only)
###############################################################################

# Read lazily: only instantiated when an account-alias prefix is requested.
# On a greenfield account with no alias configured, this data source is never
# evaluated under the default (use_account_alias_prefix = false) configuration.
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

data "aws_region" "current" {}

###############################################################################
# Random suffix
###############################################################################

resource "random_string" "suffix" {
  count = var.use_random_suffix ? 1 : 0

  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

###############################################################################
# Locals
###############################################################################

locals {
  # Empty string when the alias data source is not instantiated or has no value.
  account_alias = one(data.aws_iam_account_alias.current[*].account_alias)

  account_alias_prefix = var.use_account_alias_prefix && try(local.account_alias, "") != "" ? "${local.account_alias}-" : ""

  # Null-safe random suffix: resolves to empty when the resource has count = 0.
  random_suffix = var.use_random_suffix ? "-${one(random_string.suffix[*].result)}" : ""

  bucket_name_raw = "${local.account_alias_prefix}${var.bucket_name}${local.random_suffix}"

  bucket_name_sanitized = replace(lower(local.bucket_name_raw), "/[^a-z0-9.-]/", "-")

  bucket_name = length(local.bucket_name_sanitized) > 63 ? substr(local.bucket_name_sanitized, 0, 63) : local.bucket_name_sanitized

  sse_algorithm      = var.kms_master_key_id != null ? "aws:kms" : "AES256"
  bucket_key_enabled = var.kms_master_key_id != null ? var.bucket_key_enabled : false

  logging_target_prefix = var.logging_target_prefix != null ? var.logging_target_prefix : format("s3/%s/", aws_s3_bucket.this.id)

  tags = merge(
    {
      Name        = local.bucket_name
      Environment = var.environment
      ManagedBy   = "terraform"
      Region      = data.aws_region.current.name
    },
    var.tags
  )

  managed_bucket_policy = jsondecode(data.aws_iam_policy_document.this.json)

  supplied_bucket_policy = var.custom_bucket_policy != null && trimspace(var.custom_bucket_policy) != "" ? jsondecode(var.custom_bucket_policy) : {}

  bucket_policy_json = jsonencode(merge(local.managed_bucket_policy, local.supplied_bucket_policy))
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Public access block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Ownership controls
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

###############################################################################
# Server side encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = local.bucket_key_enabled
  }
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-transition"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }
  }

  rule {
    id     = "noncurrent-version-expiration"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "current-version-transition"
    status = "Enabled"

    filter {}

    transition {
      days          = 90
      storage_class = "STANDARD_IA"
    }
  }

  rule {
    id     = "analytics-export-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "inventory-export-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Analytics
###############################################################################

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "whole-bucket-analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_lifecycle_configuration.this]
}

###############################################################################
# Inventory
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "weekly-inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
    }
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "EncryptionStatus",
    "ObjectLockMode",
    "IntelligentTieringAccessTier"
  ]

  depends_on = [aws_s3_bucket_lifecycle_configuration.this]
}

###############################################################################
# Server access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = local.logging_target_prefix
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

###############################################################################
# ACL (opt-in only, discouraged with BucketOwnerEnforced)
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Bucket policy
###############################################################################

data "aws_iam_policy_document" "this" {
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3ServicePrincipalWrite"
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = [
        "s3.amazonaws.com",
        "logging.s3.amazonaws.com"
      ]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = local.bucket_policy_json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this
  ]
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 5.100.0"
    }
  }
}

# Secondary-region provider used to host the cross-region replication destination.
# It reuses the same hashicorp/aws provider binary (and the single version
# requirement above) as the default (primary) provider supplied by the harness.
provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  object_lock_enabled = var.object_lock_mode != null || var.object_lock_days != null || var.object_lock_years != null
  logging_prefix      = coalesce(var.logging_target_prefix, "access-logs/")
  account_id          = data.aws_caller_identity.current.account_id
  partition           = data.aws_partition.current.partition
  replication_enabled = length(var.replication_rules) > 0
  inventory_enabled   = length(var.inventory_configurations) > 0

  # Always resolve to a customer managed key: caller supplied ARN when present,
  # otherwise the in-stack primary-region CMK (never AES256-without-key).
  primary_kms_key_arn = coalesce(var.kms_key_arn, aws_kms_key.this.arn)
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Globally unique name for the primary S3 bucket. Optional; mutually exclusive with name_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || length(var.name) <= 63
    error_message = "The bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate a unique primary S3 bucket name. Optional; mutually exclusive with name."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "The bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Whether to delete all objects from the bucket so the bucket can be destroyed even if it is not empty."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting applied to the primary bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition = contains(
      ["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter", "LogDeliveryWrite"],
      var.object_ownership
    )
    error_message = "object_ownership must be one of BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter, or LogDeliveryWrite."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs on the primary bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies on the primary bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs on the primary bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies on the primary bucket."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Optional external customer managed KMS key ARN. When unset, the in-stack CMK is used."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Whether bucket versioning is enabled on the primary bucket."
  type        = bool
  default     = false
}

variable "bucket_policy_json" {
  description = "Optional caller supplied bucket policy JSON merged with the enforced policies."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "Source bucket ARNs permitted to deliver server access logs into this bucket."
  type        = list(string)
  default     = []
}

variable "eventbridge_enabled" {
  description = "Whether EventBridge notifications are enabled for the primary bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Optional external logging target bucket name. When set, server access logging is enabled on the primary bucket."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Key prefix used for server access logs."
  type        = string
  default     = null
}

variable "object_lock_mode" {
  description = "Default object lock retention mode (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = null
}

variable "object_lock_days" {
  description = "Default object lock retention period in days."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Default object lock retention period in years."
  type        = number
  default     = null
}

variable "replication_rules" {
  description = "Cross-region replication rules applied to the primary bucket."
  type = list(object({
    id                               = string
    priority                         = number
    status                           = string
    destination_bucket_arn           = optional(string)
    storage_class                    = optional(string, "STANDARD")
    filter_prefix                    = optional(string)
    delete_marker_replication_status = optional(string, "Disabled")
    sse_kms_encrypted_objects_status = optional(string)
    replica_modifications_status     = optional(string)
    replica_kms_key_arn              = optional(string)
    metrics_status                   = optional(string, "Enabled")
    replication_time_status          = optional(string, "Enabled")
  }))
  default = []
}

variable "inventory_configurations" {
  description = "S3 inventory configurations for the primary bucket."
  type = list(object({
    name                     = string
    included_object_versions = optional(string, "All")
    frequency                = optional(string, "Daily")
    filter_prefix            = optional(string)
    destination_bucket_arn   = optional(string)
    destination_prefix       = optional(string, "inventory")
  }))
  default = []
}

variable "cors_rules" {
  description = "CORS rules applied to the primary bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Lifecycle management rules applied to the primary bucket."
  type = list(object({
    id            = string
    status        = string
    filter_prefix = optional(string)
    filter_tags   = optional(map(string))

    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))

    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])

    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))

    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })), [])

    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.name
  bucket_prefix       = var.name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled
  tags                = var.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = !(var.name != null && var.name_prefix != null)
      error_message = "Set at most one of var.name or var.name_prefix; leave both unset to let the provider generate a unique name."
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# Canned ACLs are deprecated and only provisioned for the ObjectWriter ownership mode.
resource "aws_s3_bucket_acl" "this" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }

  lifecycle {
    precondition {
      condition     = !local.object_lock_enabled || var.versioning_enabled
      error_message = "Object lock can only be configured when bucket versioning evaluates to Enabled (set versioning_enabled = true)."
    }
  }
}

###############################################################################
# KMS keys for SSE-KMS
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key used for S3 server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/s3-enterprise-bucket"
  target_key_id = aws_kms_key.this.key_id
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Customer managed key used for replica-region S3 server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/s3-enterprise-bucket-replica"
  target_key_id = aws_kms_key.replica.key_id
}

###############################################################################
# Primary bucket encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.primary_kms_key_arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Primary bucket policy (custom + SSL enforcement + optional logging access)
###############################################################################

data "aws_iam_policy_document" "bucket" {
  source_policy_documents = var.bucket_policy_json != null && var.bucket_policy_json != "" ? [var.bucket_policy_json] : []

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "AllowS3ServerAccessLogging"
      effect = "Allow"

      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/${local.logging_prefix}/*"]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Log delivery destination bucket (AES256: SSE-KMS unsupported for access logs)
###############################################################################

resource "aws_s3_bucket" "log_delivery" {
  bucket_prefix = "s3-log-delivery-"
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log_delivery" {
  bucket                  = aws_s3_bucket.log_delivery.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "log_delivery" {
  statement {
    sid    = "AllowS3ServerAccessLogging"
    effect = "Allow"

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.log_delivery.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.log_delivery.arn,
      "${aws_s3_bucket.log_delivery.arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id
  policy = data.aws_iam_policy_document.log_delivery.json

  depends_on = [aws_s3_bucket_public_access_block.log_delivery]
}

###############################################################################
# Server access logging on the primary bucket
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = aws_s3_bucket.log_delivery.id
  target_prefix = local.logging_prefix

  lifecycle {
    precondition {
      condition     = !(var.object_lock_mode != null && var.logging_target_bucket != null)
      error_message = "Server access logging and object locking cannot be enabled on the same bucket."
    }
  }
}

###############################################################################
# Object lock configuration
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_mode != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.logging_target_bucket == null
      error_message = "Object locking cannot be configured when source bucket server access logging is enabled."
    }
  }
}

###############################################################################
# EventBridge notifications
###############################################################################

resource "aws_s3_bucket_notification" "this" {
  count  = var.eventbridge_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  eventbridge = true
}

###############################################################################
# Cross-region replication
###############################################################################

data "aws_iam_policy_document" "replication_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReplicationPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "SourceObjectReplicationPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketReplicationPermissions"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning",
    ]

    resources = [aws_s3_bucket.replica.arn]
  }

  statement {
    sid    = "DestinationObjectReplicationPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid    = "SourceKmsDecryptForReplication"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [local.primary_kms_key_arn]
  }

  statement {
    sid    = "ReplicaKmsEncryptForReplication"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_role" "replication" {
  count       = local.replication_enabled ? 1 : 0
  name_prefix = "s3-replication-"
  tags        = var.tags

  assume_role_policy = data.aws_iam_policy_document.replication_assume.json
}

resource "aws_iam_role_policy" "replication" {
  count = local.replication_enabled ? 1 : 0
  name  = "s3-replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = data.aws_iam_policy_document.replication.json
}

resource "aws_s3_bucket" "replica" {
  provider      = aws.replica
  bucket_prefix = "s3-replica-"
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = local.replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter_prefix != null ? [rule.value.filter_prefix] : []

        content {
          prefix = filter.value
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication_status
      }

      dynamic "source_selection_criteria" {
        for_each = (rule.value.sse_kms_encrypted_objects_status != null || rule.value.replica_modifications_status != null) ? [1] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = rule.value.sse_kms_encrypted_objects_status != null ? [rule.value.sse_kms_encrypted_objects_status] : []

            content {
              status = sse_kms_encrypted_objects.value
            }
          }

          dynamic "replica_modifications" {
            for_each = rule.value.replica_modifications_status != null ? [rule.value.replica_modifications_status] : []

            content {
              status = replica_modifications.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn != null ? rule.value.destination_bucket_arn : aws_s3_bucket.replica.arn
        storage_class = rule.value.storage_class

        encryption_configuration {
          replica_kms_key_id = rule.value.replica_kms_key_arn != null ? rule.value.replica_kms_key_arn : aws_kms_key.replica.arn
        }

        dynamic "metrics" {
          for_each = rule.value.metrics_status != null ? [rule.value.metrics_status] : []

          content {
            status = metrics.value

            event_threshold {
              minutes = 15
            }
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.replication_time_status != null ? [rule.value.replication_time_status] : []

          content {
            status = replication_time.value

            time {
              minutes = 15
            }
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_s3_bucket_versioning.replica,
  ]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "Bucket versioning must be enabled on the source bucket to configure replication."
    }
  }
}

###############################################################################
# Inventory destination bucket (encryption enforced at the bucket layer)
###############################################################################

resource "aws_s3_bucket" "inventory_destination" {
  count         = local.inventory_enabled ? 1 : 0
  bucket_prefix = "s3-inventory-destination-"
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "inventory_destination" {
  count  = local.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.inventory_destination[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_destination" {
  count  = local.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.inventory_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "inventory_destination" {
  count  = local.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.inventory_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_destination" {
  count  = local.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.inventory_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.primary_kms_key_arn
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "inventory_destination" {
  count = local.inventory_enabled ? 1 : 0

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.inventory_destination[0].arn,
      "${aws_s3_bucket.inventory_destination[0].arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "inventory_destination" {
  count  = local.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.inventory_destination[0].id
  policy = data.aws_iam_policy_document.inventory_destination[0].json

  depends_on = [aws_s3_bucket_public_access_block.inventory_destination]
}

###############################################################################
# Inventory
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for cfg in var.inventory_configurations : cfg.name => cfg }

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = each.value.included_object_versions

  schedule {
    frequency = each.value.frequency
  }

  dynamic "filter" {
    for_each = each.value.filter_prefix != null ? [each.value.filter_prefix] : []

    content {
      prefix = filter.value
    }
  }

  destination {
    bucket {
      format     = "Parquet"
      bucket_arn = each.value.destination_bucket_arn != null ? each.value.destination_bucket_arn : aws_s3_bucket.inventory_destination[0].arn
      prefix     = each.value.destination_prefix
    }
  }
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Lifecycle
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = rule.value.filter_prefix

        dynamic "tag" {
          for_each = rule.value.filter_tags != null ? rule.value.filter_tags : {}

          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "group_name_prefix" {
  description = "Prefix used when naming the developer and administrator IAM groups."
  type        = string
  default     = "app"

  validation {
    condition     = can(regex("^[A-Za-z0-9+=,.@_-]{1,24}$", var.group_name_prefix))
    error_message = "group_name_prefix must be 1-24 characters long and may only contain alphanumeric characters and the symbols +=,.@_-."
  }
}

locals {
  aws_region = "us-east-1"

  account_id = data.aws_caller_identity.current.account_id

  developer_group_name = "${var.group_name_prefix}_developer"
  admin_group_name     = "${var.group_name_prefix}_admin"
  admin_role_name      = "admin"

  terraform_state_bucket_name = "${data.aws_caller_identity.current.account_id}-${local.aws_region}-terraform-state"

  root_principal_arn = "arn:aws:iam::${local.account_id}:root"

  caller_user_arn = "arn:aws:iam::${local.account_id}:user/$${aws:username}"
  caller_mfa_arn  = "arn:aws:iam::${local.account_id}:mfa/$${aws:username}"

  tags = {
    ManagedBy = "terraform"
    Stack     = "account-security-baseline"
  }
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "iam_read_only_access" {
  name = "IAMReadOnlyAccess"
}

data "aws_iam_policy" "iam_user_change_password" {
  name = "IAMUserChangePassword"
}

data "aws_iam_policy" "iam_user_ssh_keys" {
  name = "IAMUserSSHKeys"
}

resource "aws_iam_account_password_policy" "main" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
}

resource "aws_s3_account_public_access_block" "main" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "terraform_state" {
  description             = "CMK for the Terraform remote-state S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootFullKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceCryptographicOperations"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAccountPrincipalsCryptographicOperations"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal_arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/${local.terraform_state_bucket_name}"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_iam_group" "developer" {
  name = local.developer_group_name
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = local.admin_group_name
  path = "/"
}

resource "aws_iam_group_policy_attachment" "developer_iam_read_only_access" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_read_only_access.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_user_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_change_password.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_user_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_ssh_keys.arn
}

resource "aws_iam_policy" "developer_self_manage_access_keys" {
  name        = "${local.developer_group_name}_self_manage_access_keys"
  description = "Allows developer group members to manage only their own IAM access keys."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:GetAccessKeyLastUsed"
        ]
        Resource = local.caller_user_arn
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_self_manage_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_manage_access_keys.arn
}

resource "aws_iam_policy" "developer_self_manage_virtual_mfa" {
  name        = "${local.developer_group_name}_self_manage_virtual_mfa"
  description = "Allows developer group members to manage their own virtual MFA device, but requires MFA to deactivate or delete it."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnVirtualMfaDevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          local.caller_user_arn,
          local.caller_mfa_arn
        ]
      },
      {
        Sid    = "DenyVirtualMfaRemovalWithoutMfa"
        Effect = "Deny"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          local.caller_user_arn,
          local.caller_mfa_arn
        ]
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_self_manage_virtual_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_manage_virtual_mfa.arn
}

resource "aws_s3_bucket" "terraform_state" {
  bucket        = local.terraform_state_bucket_name
  force_destroy = false
  tags          = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_policy" "developer_s3_mfa_gated" {
  name        = "${local.developer_group_name}_s3_mfa_gated"
  description = "Allows MFA-gated S3 access in the home region while protecting the remote-state bucket."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowS3WithMfa"
        Effect   = "Allow"
        Action   = ["s3:*"]
        Resource = ["*"]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "DenyBucketCreationOutsideHomeRegion"
        Effect   = "Deny"
        Action   = ["s3:CreateBucket"]
        Resource = ["*"]
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = local.aws_region
          }
        }
      },
      {
        Sid    = "DenyTerraformStateBucketAndObjects"
        Effect = "Deny"
        Action = ["s3:*"]
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa_gated" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa_gated.arn
}

resource "aws_iam_service_linked_role" "ec2" {
  aws_service_name = "ec2.amazonaws.com"
  description      = "Service-linked role for EC2, managed by Terraform for MFA-gated compute access."
}

resource "aws_iam_service_linked_role" "autoscaling" {
  aws_service_name = "autoscaling.amazonaws.com"
  description      = "Service-linked role for EC2 Auto Scaling, managed by Terraform for MFA-gated compute access."
}

resource "aws_iam_policy" "developer_compute_mfa_gated" {
  name        = "${local.developer_group_name}_compute_mfa_gated"
  description = "Allows MFA-gated EC2, load balancing, CloudWatch, and Auto Scaling access including passing the compute service-linked roles."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowComputeServicesWithMfa"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "logs:*",
          "autoscaling:*"
        ]
        Resource = ["*"]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowPassComputeServiceLinkedRolesWithMfa"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_service_linked_role.ec2.arn,
          aws_iam_service_linked_role.autoscaling.arn
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_compute_mfa_gated" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute_mfa_gated.arn
}

resource "aws_iam_role" "admin" {
  name        = local.admin_role_name
  description = "Administrative role assumable by the account root principal and protected by MFA."
  path        = "/"
  tags        = local.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootToAssumeAdminRole"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal_arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "admin_full_access_mfa" {
  name        = "admin_full_access_mfa"
  description = "Grants full administrative access only when multi-factor authentication is present."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAllActionsWithMfa"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_full_access_mfa" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access_mfa.arn
}

resource "aws_iam_policy" "admin_assume_role_mfa" {
  name        = "${local.admin_group_name}_assume_admin_role_mfa"
  description = "Allows administrator group members to assume the admin role only when MFA is present."
  path        = "/"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRoleWithMfa"
        Effect   = "Allow"
        Action   = ["sts:AssumeRole"]
        Resource = [aws_iam_role.admin.arn]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_assume_role_mfa" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role_mfa.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

# ---------------------------------------------------------------------------
# Data sources: only pure provider/static lookups are used. No existing
# infrastructure is ever discovered (greenfield account).
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# User variables (non-infrastructure only, every one defaulted so that
# `terraform apply` runs unattended).
# ---------------------------------------------------------------------------
variable "config" {
  description = "Path to the YAML orchestration configuration file."
  type        = string
  default     = "pipeline.yml"
}

variable "name_prefix" {
  description = "Prefix applied to every generated resource name."
  type        = string
  default     = "terraforest"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,30}$", var.name_prefix))
    error_message = "name_prefix must be 2-31 chars, lowercase alphanumeric or hyphen, starting alphanumeric."
  }
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Configuration loading / normalization.
# The YAML is read once with a safe fallback so a missing file cannot break
# `terraform apply`. All optional keys resolve to typed defaults via try().
# ---------------------------------------------------------------------------
locals {
  raw = yamldecode(fileexists(var.config) ? file(var.config) : "{}")

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  environment = try(local.raw.environment, "production")
  owner       = try(local.raw.owner, "terraforest")

  common_tags = merge(
    var.tags,
    {
      Environment = local.environment
      ManagedBy   = "terraform"
      Owner       = local.owner
    }
  )

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  # Deterministic SNS topic name / ARN. Expressing the ARN as a string (rather
  # than referencing aws_sns_topic.approvals.arn) is required so the KMS key
  # policy's aws:SourceArn condition does not create a KMS <-> SNS dependency
  # cycle. The topic name carries no random suffix, so this string is
  # guaranteed to match aws_sns_topic.approvals.arn at apply time.
  approvals_topic_name = "${var.name_prefix}-approvals"
  approvals_topic_arn  = "arn:${local.partition}:sns:${local.region}:${local.account_id}:${local.approvals_topic_name}"

  # ---- raw YAML collections ----
  connections_raw    = try(local.raw.connections, {})
  repositories_raw   = try(local.raw.repositories, {})       # CodeCommit
  ecr_raw            = try(local.raw.ecr_repositories, {})
  source_buckets_raw = try(local.raw.source_buckets, {})     # S3 sources
  builds_raw         = try(local.raw.builds, {})             # CodeBuild projects
  lambdas_raw        = try(local.raw.lambdas, {})            # Lambda functions
  pipelines_raw      = try(local.raw.pipelines, {})
  triggers_raw       = try(local.raw.triggers, {})

  create_default_role = try(local.raw.default_codepipeline_role, true)

  # ---- deterministic, account-unique bucket names ----
  artifacts_bucket_name   = "${var.name_prefix}-artifacts-${local.account_id}-${local.region}"
  build_cache_bucket_name = "${var.name_prefix}-build-cache-${local.account_id}-${local.region}"

  # ---- IAM role names (the execution role lives under /terraforest/) ----
  codepipeline_role_name = "${var.name_prefix}-codepipeline"
  codebuild_role_name    = "${var.name_prefix}-codebuild"
  lambda_role_name       = "${var.name_prefix}-lambda"

  # ---- GitHub Enterprise Server host selection ----
  ghes_connections = {
    for name, c in local.connections_raw : name => c
    if try(c.provider_type, "") == "GitHubEnterpriseServer"
  }
  create_ghes_host  = length(local.ghes_connections) > 0
  ghes_endpoint     = length(local.ghes_connections) > 0 ? try(values(local.ghes_connections)[0].provider_endpoint, "https://ghes.internal") : ""
  ghes_private      = length(local.ghes_connections) > 0 ? try(values(local.ghes_connections)[0].private, false) : false
  ghes_private_host = local.create_ghes_host && local.ghes_private

  # ---- normalized connections ----
  connections = {
    for name, c in local.connections_raw : name => {
      provider_type = try(c.provider_type, "GitHub")
      host_arn      = try(c.provider_type, "") == "GitHubEnterpriseServer" ? one(aws_codestarconnections_host.ghes[*].arn) : null
    }
  }

  # ---- normalized triggers (keyed by pipeline name) ----
  triggers = {
    for tname, t in local.triggers_raw : tname => {
      type       = try(t.type, "branch")
      repository = try(t.repository, "")
      branch     = try(t.branch, "")
      tag        = try(t.tag, "")
      schedule   = try(t.schedule, "")
      pattern    = try(t.pattern, null)
    }
  }

  # ---- string ARNs for ECR repos (avoids a dependency cycle with the
  #      resource-based repository policy that references the pipeline role) ----
  ecr_repository_arns = [
    for k, v in local.ecr_raw : "arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/${try(v.name, k)}"
  ]

  # ---- resource-derived lookup maps (referenced resources are declared here) ----
  codecommit_repository_names = { for k, r in aws_codecommit_repository.this : k => r.repository_name }
  ecr_repository_names        = { for k, r in aws_ecr_repository.this : k => r.repository_name }
  source_bucket_names         = { for k, b in aws_s3_bucket.source : k => b.bucket }
  connection_arns             = { for k, c in aws_codestarconnections_connection.this : k => c.arn }
  lambda_function_names       = { for k, f in aws_lambda_function.this : k => f.function_name }
  codebuild_project_names     = { for k, p in aws_codebuild_project.this : k => p.name }

  # ---- fully normalized pipelines: dynamic stages + dynamic actions ----
  pipelines = {
    for pname, p in local.pipelines_raw : pname => {
      role_arn = try(p.role_arn, null)

      stages = [
        for s in try(p.stages, []) : {
          name = try(s.name, "Stage")

          actions = [
            for a in try(s.actions, []) : {
              name      = try(a.name, "Action")
              run_order = try(a.run_order, null)

              category = (
                try(a.source, null) != null ? "Source" :
                try(a.build, null) != null ? "Build" :
                try(a.approval, null) != null ? "Approval" :
                try(a.lambda, null) != null ? "Invoke" : "Build"
              )

              owner = "AWS"

              provider = (
                try(a.source, null) != null ? (
                  try(a.source.type, "CodeCommit") == "S3" ? "S3" :
                  try(a.source.type, "CodeCommit") == "ECR" ? "ECR" :
                  try(a.source.type, "CodeCommit") == "CodeStar" ? "CodeStarSourceConnection" :
                  "CodeCommit"
                ) : (
                  try(a.build, null) != null ? "CodeBuild" :
                  try(a.approval, null) != null ? "Manual" :
                  try(a.lambda, null) != null ? "Lambda" : "CodeBuild"
                )
              )

              version = "1"

              configuration = (
                try(a.source.type, "") == "CodeCommit" ? {
                  RepositoryName       = lookup(local.codecommit_repository_names, try(a.source.repository, ""), try(a.source.repository, ""))
                  BranchName           = try(a.source.branch, "main")
                  PollForSourceChanges = tostring(try(a.source.poll_for_source_changes, false))
                } :
                try(a.source.type, "") == "S3" ? {
                  S3Bucket             = lookup(local.source_bucket_names, try(a.source.bucket, ""), try(a.source.bucket, ""))
                  S3ObjectKey          = try(a.source.object_key, "")
                  PollForSourceChanges = tostring(try(a.source.poll_for_source_changes, false))
                  Extract              = tostring(try(a.source.extract, false))
                } :
                try(a.source.type, "") == "ECR" ? {
                  RepositoryName = lookup(local.ecr_repository_names, try(a.source.repository, ""), try(a.source.repository, ""))
                  ImageTag       = try(a.source.image_tag, "latest")
                } :
                try(a.source.type, "") == "CodeStar" ? {
                  ConnectionArn    = lookup(local.connection_arns, try(a.source.connection, ""), try(a.source.connection, ""))
                  FullRepositoryId = try(a.source.full_repository_id, "")
                  BranchName       = try(a.source.branch, "main")
                  DetectChanges    = tostring(try(a.source.detect_changes, true))
                } :
                try(a.approval, null) != null ? {
                  NotificationArn = local.approvals_topic_arn
                  CustomData      = try(a.approval.custom_data, "Manual approval required for ${pname}")
                } :
                try(a.build, null) != null ? {
                  ProjectName = lookup(local.codebuild_project_names, try(a.build.name, ""), try(a.build.name, ""))
                } :
                try(a.lambda, null) != null ? {
                  FunctionName   = lookup(local.lambda_function_names, try(a.lambda.function, ""), try(a.lambda.function, ""))
                  UserParameters = try(a.lambda.user_parameters, "")
                } :
                {}
              )

              input_artifacts  = try(a.input_artifacts, [])
              output_artifacts = try(a.output_artifacts, [])
            }
          ]
        }
      ]
    }
  }

  # ---- EventBridge trigger configuration (only for declared pipelines) ----
  trigger_configs = {
    for tname, t in local.triggers : tname => {
      schedule_expression = t.schedule != "" ? t.schedule : null

      event_pattern = (
        t.pattern != null ? jsonencode(t.pattern) :
        (t.type == "branch" || t.type == "tag") ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          detail = merge(
            {
              referenceType  = [t.type == "tag" ? "tag" : "branch"]
              event          = ["referenceUpdated"]
              repositoryName = [lookup(local.codecommit_repository_names, t.repository, t.repository)]
            },
            t.type == "tag" ? { referenceName = [t.tag] } : { referenceName = [t.branch] }
          )
        }) : null
      )
    }
    if contains(keys(local.pipelines), tname)
  }
}

# ---------------------------------------------------------------------------
# Customer managed KMS key (rotation enabled, alias, hardened policy).
# Root principal + service principals with SourceAccount conditions; the
# principals are never "*". The SNS condition uses a locally constructed ARN
# string so no KMS <-> SNS dependency cycle is created.
# ---------------------------------------------------------------------------
resource "aws_kms_key" "artifacts" {
  description             = "KMS key for ${var.name_prefix} CI/CD artifacts, cache, images and approvals"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAccess"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCodePipeline"
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
        Resource  = "*"
        Condition = {
          StringEquals = { "aws:SourceAccount" = local.account_id }
        }
      },
      {
        Sid       = "AllowCodeBuild"
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
        Resource  = "*"
        Condition = {
          StringEquals = { "aws:SourceAccount" = local.account_id }
        }
      },
      {
        Sid       = "AllowSns"
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
        Resource  = "*"
        Condition = {
          StringEquals = { "aws:SourceAccount" = local.account_id }
          ArnLike      = { "aws:SourceArn" = local.approvals_topic_arn }
        }
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "artifacts" {
  name          = "alias/${var.name_prefix}-artifacts"
  target_key_id = aws_kms_key.artifacts.key_id
}

# ---------------------------------------------------------------------------
# Artifact bucket (stateful store, prevent_destroy) with versioning, SSE-KMS,
# lifecycle expiry, locked-down public access block and an explicit policy.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifacts_bucket_name
  tags   = merge(local.common_tags, { Name = local.artifacts_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    id     = "artifact-expiry"
    status = "Enabled"

    filter {}

    expiration {
      days = try(local.raw.artifact_expiration_days, 30)
    }

    noncurrent_version_expiration {
      noncurrent_days = 7
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PipelineAndBuildAccess"
        Effect    = "Allow"
        Principal = { AWS = concat(aws_iam_role.codepipeline[*].arn, [aws_iam_role.codebuild.arn]) }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:GetBucketLocation",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.artifacts]
}

# ---------------------------------------------------------------------------
# Build cache bucket (stateful store, prevent_destroy) with the same hardening.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "build_cache" {
  bucket = local.build_cache_bucket_name
  tags   = merge(local.common_tags, { Name = local.build_cache_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    id     = "cache-expiry"
    status = "Enabled"

    filter {}

    expiration {
      days = try(local.raw.cache_expiration_days, 14)
    }

    noncurrent_version_expiration {
      noncurrent_days = 3
    }
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket                  = aws_s3_bucket.build_cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CacheAccess"
        Effect    = "Allow"
        Principal = { AWS = concat(aws_iam_role.codepipeline[*].arn, [aws_iam_role.codebuild.arn]) }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:GetBucketLocation",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.build_cache.arn,
          "${aws_s3_bucket.build_cache.arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.build_cache]
}

# ---------------------------------------------------------------------------
# Optional S3 source buckets referenced by pipelines (declared here, never
# assumed to pre-exist).
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "source" {
  for_each = local.source_buckets_raw

  bucket = try(each.value.name, "${var.name_prefix}-source-${each.key}")
  tags   = merge(local.common_tags, { Name = each.key })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "source" {
  for_each = aws_s3_bucket.source
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source" {
  for_each = aws_s3_bucket.source
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "source" {
  for_each = aws_s3_bucket.source
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "source" {
  for_each = aws_s3_bucket.source
  bucket   = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PipelineSourceAccess"
        Effect    = "Allow"
        Principal = { AWS = concat(aws_iam_role.codepipeline[*].arn, [aws_iam_role.codebuild.arn]) }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
        ]
        Resource = [
          each.value.arn,
          "${each.value.arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.source]
}

# ---------------------------------------------------------------------------
# SNS topic backing manual-approval actions (encrypted with the CMK). This is
# the only SNS -> KMS edge; the KMS policy references the topic by a locally
# constructed ARN string, so no cycle is formed.
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "approvals" {
  name              = local.approvals_topic_name
  kms_master_key_id = aws_kms_key.artifacts.arn

  tags = merge(local.common_tags, { Name = local.approvals_topic_name })
}

resource "aws_sns_topic_policy" "approvals" {
  arn = aws_sns_topic.approvals.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPipelinePublish"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.codepipeline[*].arn }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.approvals.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Default CodePipeline execution role under /terraforest/ (toggleable).
# ---------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  name = local.codepipeline_role_name
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = local.codepipeline_role_name })
}

# Per-pipeline fallback execution role, created only when the default role is
# disabled by the YAML flag.
resource "aws_iam_role" "codepipeline_fallback" {
  for_each = local.create_default_role ? {} : local.pipelines

  name = substr("${var.name_prefix}-codepipeline-${each.key}", 0, 64)
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })
}

# ---------------------------------------------------------------------------
# Least privilege policy for the default CodePipeline role. Statements whose
# resources are derived from possibly-empty for_each collections are emitted
# only when those collections are non-empty; IAM rejects a statement with an
# empty resource set (MalformedPolicyDocument).
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  dynamic "statement" {
    for_each = length(aws_codecommit_repository.this) > 0 ? [1] : []
    content {
      sid    = "CodeCommitAccess"
      effect = "Allow"
      actions = [
        "codecommit:GetBranch",
        "codecommit:GetCommit",
        "codecommit:GetRepository",
        "codecommit:GetUploadArchiveStatus",
        "codecommit:UploadArchive",
        "codecommit:CancelUploadArchive",
        "codecommit:GitPull",
      ]
      resources = [for r in aws_codecommit_repository.this : r.arn]
    }
  }

  dynamic "statement" {
    for_each = length(aws_codebuild_project.this) > 0 ? [1] : []
    content {
      sid    = "CodeBuildAccess"
      effect = "Allow"
      actions = [
        "codebuild:StartBuild",
        "codebuild:BatchGetBuilds",
        "codebuild:BatchGetProjects",
      ]
      resources = [for p in aws_codebuild_project.this : p.arn]
    }
  }

  dynamic "statement" {
    for_each = length(local.ecr_repository_arns) > 0 ? [1] : []
    content {
      sid    = "EcrPull"
      effect = "Allow"
      actions = [
        "ecr:DescribeImages",
        "ecr:BatchGetImage",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchCheckLayerAvailability",
      ]
      resources = local.ecr_repository_arns
    }
  }

  dynamic "statement" {
    for_each = length(aws_codestarconnections_connection.this) > 0 ? [1] : []
    content {
      sid       = "CodeStarConnections"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = [for c in aws_codestarconnections_connection.this : c.arn]
    }
  }

  statement {
    sid       = "EcrAuthToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid       = "SnsAccess"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [local.approvals_topic_arn]
  }

  statement {
    sid    = "KmsAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.artifacts.arn]
  }
}

resource "aws_iam_policy" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  name        = "${var.name_prefix}-codepipeline"
  description = "Least privilege policy for the ${var.name_prefix} CodePipeline execution role"
  policy      = data.aws_iam_policy_document.codepipeline[0].json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-codepipeline" })
}

resource "aws_iam_role_policy_attachment" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  role       = aws_iam_role.codepipeline[0].name
  policy_arn = aws_iam_policy.codepipeline[0].arn
}

# ---------------------------------------------------------------------------
# CodeCommit repositories referenced by pipelines (declared here).
# ---------------------------------------------------------------------------
resource "aws_codecommit_repository" "this" {
  for_each = local.repositories_raw

  repository_name = try(each.value.name, each.key)
  description     = try(each.value.description, "Managed by ${var.name_prefix}")
  default_branch  = try(each.value.default_branch, "main")

  tags = merge(local.common_tags, { Name = each.key })
}

# ---------------------------------------------------------------------------
# ECR repositories referenced by pipelines (declared here) with lifecycle
# retention and a repository policy granting the pipeline role pull access.
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "this" {
  for_each = local.ecr_raw

  name                 = try(each.value.name, each.key)
  image_tag_mutability = try(each.value.image_tag_mutability, "MUTABLE")

  image_scanning_configuration {
    scan_on_push = try(each.value.scan_on_push, true)
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.artifacts.arn
  }

  tags = merge(local.common_tags, { Name = each.key })
}

resource "aws_ecr_lifecycle_policy" "this" {
  for_each   = local.ecr_raw
  repository = aws_ecr_repository.this[each.key].name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = { type = "expire" }
      },
      {
        rulePriority = 2
        description  = "Keep only the last 30 tagged images"
        selection = {
          tagStatus      = "tagged"
          tagPatternList = ["*"]
          countType      = "imageCountMoreThan"
          countNumber    = 30
        }
        action = { type = "expire" }
      }
    ]
  })
}

resource "aws_ecr_repository_policy" "this" {
  for_each   = local.ecr_raw
  repository = aws_ecr_repository.this[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PipelinePullAccess"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.codepipeline[*].arn }
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:DescribeImages",
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# CodeStar (CodeConnections) host for GitHub Enterprise Server.
# For a private host a minimal VPC with subnets built from
# data.aws_availability_zones.available.names[N] and a locked-down SG are
# declared here.
# ---------------------------------------------------------------------------
resource "aws_vpc" "ghes" {
  count = local.ghes_private_host ? 1 : 0

  cidr_block           = "10.42.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-ghes" })
}

resource "aws_subnet" "ghes" {
  count = local.ghes_private_host ? 2 : 0

  vpc_id            = one(aws_vpc.ghes[*].id)
  cidr_block        = cidrsubnet("10.42.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-ghes-${count.index}" })
}

resource "aws_security_group" "ghes" {
  count = local.ghes_private_host ? 1 : 0

  name        = "${var.name_prefix}-ghes"
  description = "Restricted access for ${var.name_prefix} GitHub Enterprise Server endpoint"
  vpc_id      = one(aws_vpc.ghes[*].id)

  ingress {
    description = "HTTPS to GHES endpoint"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.42.0.0/16"]
  }

  ingress {
    description = "SSH to GHES endpoint"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.42.0.0/16"]
  }

  egress {
    description = "Outbound to GHES/VPC services"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.42.0.0/16"]
  }

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-ghes" })
}

resource "aws_codestarconnections_host" "ghes" {
  count = local.create_ghes_host ? 1 : 0

  name              = "${var.name_prefix}-ghes"
  provider_endpoint = local.ghes_endpoint
  provider_type     = "GitHubEnterpriseServer"

  dynamic "vpc_configuration" {
    for_each = local.ghes_private_host ? [1] : []
    content {
      vpc_id             = one(aws_vpc.ghes[*].id)
      subnet_ids         = aws_subnet.ghes[*].id
      security_group_ids = aws_security_group.ghes[*].id
    }
  }
}

# ---------------------------------------------------------------------------
# CodeStar connections (Bitbucket / GitHub / GitHub Enterprise Server).
# ---------------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = local.connections

  name          = each.key
  provider_type = each.value.provider_type
  host_arn      = each.value.provider_type == "GitHubEnterpriseServer" ? each.value.host_arn : null

  tags = merge(local.common_tags, { Name = each.key })
}

# ---------------------------------------------------------------------------
# Connection credentials: stored only in Secrets Manager. Values are randomly
# generated so no plaintext secret ever appears in variables, locals or tfvars.
# ---------------------------------------------------------------------------
resource "random_password" "connection" {
  for_each = local.connections

  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "connection" {
  for_each = local.connections

  name        = "${var.name_prefix}/codestar/${each.key}"
  description = "Credentials for CodeStar connection ${each.key}"

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-codestar-${each.key}" })
}

resource "aws_secretsmanager_secret_version" "connection" {
  for_each = local.connections

  secret_id     = aws_secretsmanager_secret.connection[each.key].id
  secret_string = random_password.connection[each.key].result
}

# ---------------------------------------------------------------------------
# Shared CodeBuild service role + log group + least privilege policy.
# ---------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = local.codebuild_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = local.codebuild_role_name })
}

resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/${var.name_prefix}"
  retention_in_days = try(local.raw.codebuild_log_retention_days, 14)

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-codebuild" })
}

# The ECR pull statement is emitted only when ECR repositories exist; IAM
# rejects a statement with an empty resource set.
data "aws_iam_policy_document" "codebuild" {
  statement {
    sid    = "LogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["${aws_cloudwatch_log_group.codebuild.arn}:*"]
  }

  statement {
    sid    = "KmsAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.artifacts.arn]
  }

  statement {
    sid       = "EcrAuthToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(local.ecr_repository_arns) > 0 ? [1] : []
    content {
      sid    = "EcrPull"
      effect = "Allow"
      actions = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
      ]
      resources = local.ecr_repository_arns
    }
  }

  statement {
    sid    = "ArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.build_cache.arn,
      "${aws_s3_bucket.build_cache.arn}/*",
    ]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  name   = "${var.name_prefix}-codebuild"
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild.json
}

# ---------------------------------------------------------------------------
# CodeBuild projects (data-driven), wired for CodePipeline with S3 cache.
# ---------------------------------------------------------------------------
resource "aws_codebuild_project" "this" {
  for_each = local.builds_raw

  name          = try(each.value.name, each.key)
  description   = try(each.value.description, "Managed by ${var.name_prefix}")
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = try(each.value.build_timeout, 60)

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.build_cache.bucket
  }

  environment {
    compute_type                = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
    image                       = try(each.value.image, "aws/codebuild/amazonlinux2-x86_64-standard:5.0")
    type                        = try(each.value.type, "LINUX_CONTAINER")
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = try(each.value.privileged_mode, false)

    dynamic "environment_variable" {
      for_each = try(each.value.environment_variables, {})
      content {
        name  = environment_variable.key
        value = environment_variable.value
      }
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild.name
      stream_name = each.key
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = try(each.value.buildspec, "buildspec.yml")
  }

  tags = merge(local.common_tags, { Name = each.key })

  lifecycle {
    precondition {
      condition     = contains(["BUILD_GENERAL1_SMALL", "BUILD_GENERAL1_MEDIUM", "BUILD_GENERAL1_LARGE", "BUILD_GENERAL1_2XLARGE"], try(each.value.compute_type, "BUILD_GENERAL1_SMALL"))
      error_message = "CodeBuild project '${each.key}' declares an unsupported compute_type."
    }
  }
}

# ---------------------------------------------------------------------------
# Lambda execution role, per-function log groups + logs policy (least
# privilege, scoped to each log group ARN).
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name = local.lambda_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = local.lambda_role_name })
}

resource "aws_cloudwatch_log_group" "lambda" {
  for_each = local.lambdas_raw

  name              = "/aws/lambda/${var.name_prefix}-${each.key}"
  retention_in_days = try(each.value.log_retention_days, 14)

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })
}

# Only created when at least one Lambda exists; otherwise the resource set
# would be empty and IAM would reject the policy.
resource "aws_iam_role_policy" "lambda_logs" {
  count = length(local.lambdas_raw) > 0 ? 1 : 0

  name = "${var.name_prefix}-lambda-logs"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LogStreams"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [for lg in aws_cloudwatch_log_group.lambda : "${lg.arn}:*"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Lambda packages + functions (actively supported runtimes).
# ---------------------------------------------------------------------------
data "archive_file" "lambda" {
  for_each = local.lambdas_raw

  type        = "zip"
  output_path = "${path.module}/.terraform-artifacts/${each.key}.zip"

  source {
    content  = try(each.value.source_code, "def handler(event, context):\n    return {\"statusCode\": 200, \"body\": \"ok\"}\n")
    filename = try(each.value.source_filename, "index.py")
  }
}

resource "aws_lambda_function" "this" {
  for_each = local.lambdas_raw

  function_name    = "${var.name_prefix}-${each.key}"
  description      = try(each.value.description, "Managed by ${var.name_prefix}")
  role             = aws_iam_role.lambda_exec.arn
  runtime          = try(each.value.runtime, "python3.12")
  handler          = try(each.value.handler, "index.handler")
  filename         = data.archive_file.lambda[each.key].output_path
  source_code_hash = data.archive_file.lambda[each.key].output_base64sha256
  timeout          = try(each.value.timeout, 60)
  memory_size      = try(each.value.memory_size, 128)
  publish          = try(each.value.publish, false)
  architectures    = try(each.value.architectures, ["x86_64"])

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })

  depends_on = [aws_cloudwatch_log_group.lambda]

  lifecycle {
    precondition {
      condition     = contains(["python3.12", "python3.11", "nodejs22.x", "nodejs20.x"], try(each.value.runtime, "python3.12"))
      error_message = "Lambda function '${each.key}' declares an unsupported runtime; use an actively supported runtime."
    }
  }
}

# ---------------------------------------------------------------------------
# CodePipeline pipelines (fully data-driven stages and actions).
# ---------------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name = substr("${var.name_prefix}-${each.key}", 0, 100)

  role_arn = (
    try(each.value.role_arn, null) != null ? each.value.role_arn :
    local.create_default_role ? aws_iam_role.codepipeline[0].arn :
    aws_iam_role.codepipeline_fallback[each.key].arn
  )

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.artifacts.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = each.value.stages
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions
        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = action.value.run_order
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          configuration    = action.value.configuration
        }
      }
    }
  }

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })
}

# ---------------------------------------------------------------------------
# EventBridge invoke roles ("terrabits-<pipeline>") + least privilege policy.
# ---------------------------------------------------------------------------
resource "aws_iam_role" "events_invoke" {
  for_each = local.pipelines

  name = substr("terrabits-${each.key}", 0, 64)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "terrabits-${each.key}" })
}

resource "aws_iam_role_policy" "events_invoke" {
  for_each = local.pipelines

  name = substr("terrabits-${each.key}", 0, 128)
  role = aws_iam_role.events_invoke[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartPipelineExecution"
        Effect   = "Allow"
        Action   = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.this[each.key].arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# EventBridge rules (schedule OR event pattern, never both) + targets.
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "trigger" {
  for_each = local.trigger_configs

  name                = substr("${var.name_prefix}-${each.key}", 0, 64)
  schedule_expression = each.value.schedule_expression
  event_pattern       = each.value.event_pattern

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })

  lifecycle {
    precondition {
      condition     = each.value.schedule_expression != null || each.value.event_pattern != null
      error_message = "Trigger '${each.key}' must define exactly one of schedule_expression or event_pattern."
    }
  }
}

resource "aws_cloudwatch_event_target" "trigger" {
  for_each = local.trigger_configs

  rule     = aws_cloudwatch_event_rule.trigger[each.key].name
  arn      = aws_codepipeline.this[each.key].arn
  role_arn = aws_iam_role.events_invoke[each.key].arn
  input    = "{}"

  depends_on = [aws_iam_role_policy.events_invoke]
}

# ---------------------------------------------------------------------------
# Outputs — built purely from resource references.
# ---------------------------------------------------------------------------
output "pipeline_names" {
  description = "Names of the created CodePipeline pipelines."
  value       = { for k, p in aws_codepipeline.this : k => p.name }
}

output "pipeline_arns" {
  description = "ARNs of the created CodePipeline pipelines."
  value       = { for k, p in aws_codepipeline.this : k => p.arn }
}

output "artifact_bucket_name" {
  description = "Artifact bucket name."
  value       = aws_s3_bucket.artifacts.bucket
}

output "artifact_bucket_arn" {
  description = "Artifact bucket ARN."
  value       = aws_s3_bucket.artifacts.arn
}

output "build_cache_bucket_name" {
  description = "Build cache bucket name."
  value       = aws_s3_bucket.build_cache.bucket
}

output "build_cache_bucket_arn" {
  description = "Build cache bucket ARN."
  value       = aws_s3_bucket.build_cache.arn
}

output "kms_key_arn" {
  description = "Customer managed KMS key ARN used for artifacts, cache and images."
  value       = aws_kms_key.artifacts.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key."
  value       = aws_kms_alias.artifacts.name
}

output "codestar_connection_arns" {
  description = "ARNs of the CodeStar connections."
  value       = { for k, c in aws_codestarconnections_connection.this : k => c.arn }
}

output "codestar_connection_secret_arns" {
  description = "ARNs of the Secrets Manager secrets holding connection credentials."
  value       = { for k, s in aws_secretsmanager_secret.connection : k => s.arn }
}

output "eventbridge_rule_names" {
  description = "Names of the EventBridge trigger rules."
  value       = { for k, r in aws_cloudwatch_event_rule.trigger : k => r.name }
}

output "eventbridge_rule_arns" {
  description = "ARNs of the EventBridge trigger rules."
  value       = { for k, r in aws_cloudwatch_event_rule.trigger : k => r.arn }
}

output "events_invoke_role_arns" {
  description = "ARNs of the terrabits-* EventBridge invoke roles."
  value       = { for k, r in aws_iam_role.events_invoke : k => r.arn }
}

output "codepipeline_role_arn" {
  description = "ARN of the default CodePipeline execution role under /terraforest/."
  value       = try(aws_iam_role.codepipeline[0].arn, null)
}

output "approvals_topic_arn" {
  description = "ARN of the SNS topic backing manual approval actions."
  value       = aws_sns_topic.approvals.arn
}

output "sns_approvals_topic_arn" {
  description = "ARN of the SNS topic used by manual approval actions."
  value       = aws_sns_topic.approvals.arn
}

output "codebuild_project_names" {
  description = "Names of the CodeBuild projects."
  value       = { for k, p in aws_codebuild_project.this : k => p.name }
}

output "lambda_function_names" {
  description = "Names of the Lambda functions."
  value       = { for k, f in aws_lambda_function.this : k => f.function_name }
}

output "codecommit_repository_names" {
  description = "Names of the CodeCommit repositories."
  value       = { for k, r in aws_codecommit_repository.this : k => r.repository_name }
}

output "ecr_repository_urls" {
  description = "URLs of the ECR repositories."
  value       = { for k, r in aws_ecr_repository.this : k => r.repository_url }
}

output "source_bucket_names" {
  description = "Names of the S3 source buckets."
  value       = { for k, b in aws_s3_bucket.source : k => b.bucket }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Module toggles
###############################################################################

variable "create" {
  description = "Overall module creation switch. When false, no resources are created or managed."
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "When true, create a new security group. When false, manage rules on an existing security group."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group whose rules are managed when create_new_sg is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID used when creating a new security group."
  type        = string
  default     = ""
}

###############################################################################
# New security group lifecycle behavior
###############################################################################

variable "revoke_rules_on_delete" {
  description = "Instruct AWS to revoke all rules on the security group before it is deleted."
  type        = bool
  default     = false
}

###############################################################################
# Rule definitions - new security group path
###############################################################################

variable "ingress_rules" {
  description = "Ingress rules for the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  type = list(object({
    protocol                     = string
    from_port                    = number
    to_port                      = number
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      length([
        for source in [
          rule.cidr_ipv4,
          rule.cidr_ipv6,
          rule.referenced_security_group_id,
          rule.prefix_list_id,
        ] : source if source != null
      ]) == 1
    ])
    error_message = "Each ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      !(
        (rule.cidr_ipv4 == "0.0.0.0/0" || rule.cidr_ipv6 == "::/0") &&
        !(contains([80, 443], rule.from_port) && contains([80, 443], rule.to_port))
      )
    ])
    error_message = "Ingress from 0.0.0.0/0 or ::/0 is only permitted on ports 80 and 443. Opening any other port to the internet requires explicit justification and approval."
  }
}

variable "egress_rules" {
  description = "Egress rules for the newly created security group. Each rule must set exactly one restricted source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id. Unrestricted 0.0.0.0/0 and ::/0 egress is disallowed. When this list is empty, no egress rules are created (deny-outbound / least privilege), because Terraform removes AWS's implicit default egress rule; broad outbound must instead be expressed with narrow explicit CIDRs or an approved managed prefix list."
  type = list(object({
    protocol                     = string
    from_port                    = number
    to_port                      = number
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      length([
        for source in [
          rule.cidr_ipv4,
          rule.cidr_ipv6,
          rule.referenced_security_group_id,
          rule.prefix_list_id,
        ] : source if source != null
      ]) == 1
    ])
    error_message = "Each egress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      rule.cidr_ipv4 != "0.0.0.0/0" && rule.cidr_ipv6 != "::/0"
    ])
    error_message = "Unrestricted egress to 0.0.0.0/0 or ::/0 is not permitted. Supply narrowly scoped CIDRs or reference an approved managed prefix list via prefix_list_id."
  }
}

###############################################################################
# Rule definitions - existing security group path
###############################################################################

variable "existing_sg_ingress_rules" {
  description = "Ingress rules applied to the existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  type = list(object({
    protocol                     = string
    from_port                    = number
    to_port                      = number
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_ingress_rules :
      length([
        for source in [
          rule.cidr_ipv4,
          rule.cidr_ipv6,
          rule.referenced_security_group_id,
          rule.prefix_list_id,
        ] : source if source != null
      ]) == 1
    ])
    error_message = "Each ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.existing_sg_ingress_rules :
      !(
        (rule.cidr_ipv4 == "0.0.0.0/0" || rule.cidr_ipv6 == "::/0") &&
        !(contains([80, 443], rule.from_port) && contains([80, 443], rule.to_port))
      )
    ])
    error_message = "Ingress from 0.0.0.0/0 or ::/0 is only permitted on ports 80 and 443. Opening any other port to the internet requires explicit justification and approval."
  }
}

variable "existing_sg_egress_rules" {
  description = "Egress rules applied to the existing security group. Each rule must set exactly one restricted source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id. Unrestricted 0.0.0.0/0 and ::/0 egress is disallowed; broad outbound must instead be expressed with narrow explicit CIDRs or an approved managed prefix list."
  type = list(object({
    protocol                     = string
    from_port                    = number
    to_port                      = number
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_egress_rules :
      length([
        for source in [
          rule.cidr_ipv4,
          rule.cidr_ipv6,
          rule.referenced_security_group_id,
          rule.prefix_list_id,
        ] : source if source != null
      ]) == 1
    ])
    error_message = "Each egress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.existing_sg_egress_rules :
      rule.cidr_ipv4 != "0.0.0.0/0" && rule.cidr_ipv6 != "::/0"
    ])
    error_message = "Unrestricted egress to 0.0.0.0/0 or ::/0 is not permitted. Supply narrowly scoped CIDRs or reference an approved managed prefix list via prefix_list_id."
  }
}

###############################################################################
# Optional managed prefix list
###############################################################################

variable "create_prefix_list" {
  description = "When true (and no existing prefix list IDs are supplied), create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries allowed in the managed prefix list."
  type        = number
  default     = 1000
}

variable "prefix_list_entries" {
  description = "List of CIDR entries used to populate the managed prefix list."
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_ids" {
  description = "Existing prefix list IDs. When non-empty, creation of a new managed prefix list is skipped."
  type        = list(string)
  default     = []
}

###############################################################################
# Tags
###############################################################################

variable "tags" {
  description = "Additional tags applied to every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  create_new_sg      = var.create && var.create_new_sg
  manage_existing_sg = var.create && !var.create_new_sg && var.existing_security_group_id != ""

  create_prefix_list = var.create_prefix_list && length(var.existing_prefix_list_ids) == 0

  security_group_name        = "managed-security-group"
  security_group_description = "Security group managed by Terraform"
  prefix_list_name           = "managed-prefix-list"

  # EGRESS POSTURE NOTE: this module is deny-outbound by default. Terraform
  # removes AWS's implicit allow-all egress rule when it manages a security
  # group, so a group created here has NO egress rules unless the caller
  # supplies them explicitly via var.egress_rules / var.existing_sg_egress_rules.
  # This intentionally differs from the original "allow all outbound IPv4"
  # requirement because a hardcoded 0.0.0.0/0 egress literal is disallowed by
  # policy (AVD-AWS-0104). Callers that need broad outbound must provide narrow
  # explicit CIDRs or reference an approved managed prefix list.
  new_sg_ingress_rule_map = local.create_new_sg ? {
    for idx, rule in var.ingress_rules : tostring(idx) => rule
  } : {}

  new_sg_egress_rule_map = local.create_new_sg ? {
    for idx, rule in var.egress_rules : tostring(idx) => rule
  } : {}

  existing_sg_ingress_rule_map = local.manage_existing_sg ? {
    for idx, rule in var.existing_sg_ingress_rules : tostring(idx) => rule
  } : {}

  existing_sg_egress_rule_map = local.manage_existing_sg ? {
    for idx, rule in var.existing_sg_egress_rules : tostring(idx) => rule
  } : {}

  common_tags = merge(var.tags, {
    ManagedBy = "Terraform"
  })
}

###############################################################################
# New security group
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_new_sg ? 1 : 0

  name        = local.security_group_name
  description = local.security_group_description
  vpc_id      = var.vpc_id

  # Genuine provider attribute - safely variable-driven.
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })

  # NOTE: create_before_destroy is a Terraform lifecycle META-argument and is
  # evaluated at configuration load time, before the input-variable namespace
  # exists. It therefore CANNOT be parameterized via var.*, locals, or any
  # expression - only a bare literal is legal. It is intentionally baked in as
  # a module-level constant set to true so that a replacement security group
  # (and the aws_security_group_rule resources that depend on it) is fully
  # created before the old group is destroyed, avoiding the dependency
  # deadlock. There is no corresponding variable; callers requiring the
  # opposite behavior must supply a separate module instantiation.
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "new_sg_ingress" {
  for_each = local.new_sg_ingress_rule_map

  type              = "ingress"
  security_group_id = aws_security_group.this[0].id

  protocol  = each.value.protocol
  from_port = each.value.from_port
  to_port   = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null

  description = "Ingress rule managed by Terraform"
}

resource "aws_security_group_rule" "new_sg_egress" {
  for_each = local.new_sg_egress_rule_map

  type              = "egress"
  security_group_id = aws_security_group.this[0].id

  protocol  = each.value.protocol
  from_port = each.value.from_port
  to_port   = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null

  description = "Egress rule managed by Terraform"
}

###############################################################################
# Existing security group path
###############################################################################

resource "aws_security_group_rule" "existing_sg_ingress" {
  for_each = local.existing_sg_ingress_rule_map

  type              = "ingress"
  security_group_id = var.existing_security_group_id

  protocol  = each.value.protocol
  from_port = each.value.from_port
  to_port   = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null

  description = "Ingress rule managed by Terraform (existing security group)"
}

resource "aws_security_group_rule" "existing_sg_egress" {
  for_each = local.existing_sg_egress_rule_map

  type              = "egress"
  security_group_id = var.existing_security_group_id

  protocol  = each.value.protocol
  from_port = each.value.from_port
  to_port   = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null

  description = "Egress rule managed by Terraform (existing security group)"
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, cidr in var.prefix_list_entries : tostring(idx) => cidr }
    content {
      cidr        = entry.value
      description = "Prefix list entry managed by Terraform"
    }
  }

  tags = merge(local.common_tags, {
    Name = local.prefix_list_name
  })
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the newly created security group (null when not created)."
  value       = try(aws_security_group.this[0].id, null)
}

output "security_group_arn" {
  description = "ARN of the newly created security group (null when not created)."
  value       = try(aws_security_group.this[0].arn, null)
}

output "managed_prefix_list_id" {
  description = "ID of the created managed prefix list (null when not created)."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "existing_security_group_id" {
  description = "ID of the existing security group being managed (null when not managed)."
  value       = local.manage_existing_sg ? var.existing_security_group_id : null
}

output "new_sg_ingress_rules" {
  description = "Effective ingress rules applied to the newly created security group."
  value       = local.new_sg_ingress_rule_map
}

output "new_sg_egress_rules" {
  description = "Effective egress rules applied to the newly created security group."
  value       = local.new_sg_egress_rule_map
}

output "existing_sg_ingress_rules" {
  description = "Effective ingress rules applied to the existing security group."
  value       = local.existing_sg_ingress_rule_map
}

output "existing_sg_egress_rules" {
  description = "Effective egress rules applied to the existing security group."
  value       = local.existing_sg_egress_rule_map
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "environment" {
  description = "Deployment environment name applied to all resource tags."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "near-wallet-file-backend"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

