terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Explicit identifier for the Transfer Family server. When empty a two word hyphenated pet name is generated."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Transfer server endpoint type."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of PUBLIC, VPC or VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled on the Transfer server."
  type        = list(string)
  default     = ["SFTP"]
}

variable "identity_provider_type" {
  description = "Identity provider used by the Transfer server."
  type        = string
  default     = "SERVICE_MANAGED"
}

variable "domain" {
  description = "Storage backend domain for the Transfer server."
  type        = string
  default     = "S3"
}

variable "security_policy_name" {
  description = "Transfer Family security policy name."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "logging_role_arn" {
  description = "Existing IAM role ARN used for Transfer logging. When empty a dedicated role with AWSTransferLoggingAccess is created."
  type        = string
  default     = ""
}

variable "hosted_zone_name" {
  description = "Route 53 hosted zone name to create and use for DNS records. When empty no DNS resources are created."
  type        = string
  default     = ""
}

variable "subdomain" {
  description = "Sub-domain used for the SFTP CNAME record."
  type        = string
  default     = "sftp"
}

variable "certificate_arn" {
  description = "Existing ACM certificate ARN for FTPS. When empty and create_acm_certificate is true a certificate is issued."
  type        = string
  default     = ""
}

variable "create_acm_certificate" {
  description = "Whether to issue a new DNS validated ACM certificate (requires hosted_zone_name)."
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC created for VPC hosted endpoints."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_count" {
  description = "Number of public subnets (and Elastic IPs) created in the dedicated VPC."
  type        = number
  default     = 2
}

variable "as2_transports" {
  description = "AS2 transports exposed through protocol_details."
  type        = list(string)
  default     = []
}

variable "passive_ip" {
  description = "Passive IP address exposed through protocol_details."
  type        = string
  default     = ""
}

variable "set_stat_option" {
  description = "SETSTAT option exposed through protocol_details."
  type        = string
  default     = ""
}

variable "tls_session_resumption_mode" {
  description = "TLS session resumption mode exposed through protocol_details."
  type        = string
  default     = ""
}

variable "users" {
  description = "Map of SFTP users to provision keyed by user name."
  type = map(object({
    home_directory      = string
    home_directory_type = optional(string, "PATH")
    policy              = optional(string, null)
  }))
  default = {}
}

variable "users_ssh_keys" {
  description = "Map of user name to the list of SSH public keys authorised for that user."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  server_name = var.name != "" ? var.name : random_pet.server_name.id

  common_tags = merge(
    var.tags,
    {
      Name   = local.server_name
      Module = "transfer-family-sftp"
    }
  )

  create_vpc          = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)
  create_vpc_endpoint = var.endpoint_type == "VPC_ENDPOINT"
  create_route53      = var.hosted_zone_name != ""
  create_certificate  = var.create_acm_certificate && var.hosted_zone_name != ""

  selected_azs = slice(
    data.aws_availability_zones.available.names,
    0,
    min(var.subnet_count, length(data.aws_availability_zones.available.names))
  )

  logging_role_arn = var.logging_role_arn != "" ? var.logging_role_arn : one(aws_iam_role.transfer_logging[*].arn)

  server_certificate_arn = (
    var.certificate_arn != ""
    ? var.certificate_arn
    : (local.create_certificate ? one(aws_acm_certificate_validation.cert[*].certificate_arn) : null)
  )

  create_protocol_details = (
    length(var.as2_transports) > 0 ||
    var.passive_ip != "" ||
    var.set_stat_option != "" ||
    var.tls_session_resumption_mode != ""
  )

  user_home_parts = {
    for k, v in var.users : k => compact(split("/", trimprefix(v.home_directory, "/")))
  }

  user_home_bucket = {
    for k, v in var.users : k => local.user_home_parts[k][0]
  }

  user_home_prefix = {
    for k, v in var.users : k => (
      length(local.user_home_parts[k]) > 1
      ? join("/", slice(local.user_home_parts[k], 1, length(local.user_home_parts[k])))
      : ""
    )
  }
}

###############################################################################
# Server name generation
###############################################################################

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

###############################################################################
# Shared assume role policies
###############################################################################

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "TransferAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "api_gateway_assume_role" {
  statement {
    sid     = "ApiGatewayAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

###############################################################################
# Logging role (default AWSTransferLoggingAccess)
###############################################################################

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  description        = "Logging role for the ${local.server_name} AWS Transfer Family server"

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# Structured logging destination
###############################################################################

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = 90

  tags = local.common_tags
}

###############################################################################
# Host key (generated, stored in Secrets Manager)
###############################################################################

resource "tls_private_key" "host_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_secretsmanager_secret" "transfer_host_key" {
  name                    = "${local.server_name}-transfer-host-key"
  description             = "SFTP host key for the ${local.server_name} AWS Transfer Family server"
  recovery_window_in_days = 7

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "transfer_host_key" {
  secret_id     = aws_secretsmanager_secret.transfer_host_key.id
  secret_string = tls_private_key.host_key.private_key_pem
}

###############################################################################
# Customer managed KMS key for the SFTP home directory bucket
###############################################################################

data "aws_iam_policy_document" "transfer_home_kms" {
  statement {
    sid     = "EnableRootAccountKeyAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "transfer_home" {
  description             = "Customer managed key encrypting the ${local.server_name} AWS Transfer Family SFTP home directory bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.transfer_home_kms.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "transfer_home" {
  name          = "alias/${local.server_name}-transfer-home"
  target_key_id = aws_kms_key.transfer_home.key_id
}

###############################################################################
# SFTP home directory storage
###############################################################################

resource "aws_s3_bucket" "transfer_home" {
  bucket        = "${lower(local.server_name)}-transfer-home-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "transfer_home" {
  bucket = aws_s3_bucket.transfer_home.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer_home" {
  bucket = aws_s3_bucket.transfer_home.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.transfer_home.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "transfer_home" {
  bucket = aws_s3_bucket.transfer_home.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "transfer_home" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.transfer_home.arn,
      "${aws_s3_bucket.transfer_home.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "transfer_home" {
  bucket = aws_s3_bucket.transfer_home.id
  policy = data.aws_iam_policy_document.transfer_home.json

  depends_on = [aws_s3_bucket_public_access_block.transfer_home]
}

###############################################################################
# Dedicated network for VPC / VPC_ENDPOINT hosted servers
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.server_name}-vpc" })
}

resource "aws_subnet" "public" {
  count = local.create_vpc ? length(local.selected_azs) : 0

  vpc_id                  = one(aws_vpc.main[*].id)
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.server_name}-public-${count.index}", Tier = "public" })
}

resource "aws_internet_gateway" "main" {
  count = local.create_vpc ? 1 : 0

  vpc_id = one(aws_vpc.main[*].id)

  tags = merge(local.common_tags, { Name = "${local.server_name}-igw" })
}

resource "aws_route_table" "public" {
  count = local.create_vpc ? 1 : 0

  vpc_id = one(aws_vpc.main[*].id)

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = one(aws_internet_gateway.main[*].id)
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = local.create_vpc ? length(local.selected_azs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = one(aws_route_table.public[*].id)
}

###############################################################################
# Security group for the Transfer endpoint
###############################################################################

resource "aws_security_group" "transfer" {
  count = local.create_vpc ? 1 : 0

  name        = "${local.server_name}-transfer-sg"
  description = "Controls access to the ${local.server_name} AWS Transfer Family endpoint"
  vpc_id      = one(aws_vpc.main[*].id)

  ingress {
    description = "SFTP/FTPS clients connect from arbitrary internet addresses, so TCP 22 must be reachable from the public internet"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound connectivity required by the Transfer endpoint"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-transfer-sg" })
}

###############################################################################
# Elastic IPs for VPC hosted endpoints
###############################################################################

resource "aws_eip" "transfer" {
  count = local.create_vpc ? length(local.selected_azs) : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.server_name}-transfer-eip-${count.index}" })
}

###############################################################################
# VPC endpoint for VPC_ENDPOINT hosted servers
###############################################################################

resource "aws_vpc_endpoint" "transfer" {
  count = local.create_vpc_endpoint ? 1 : 0

  vpc_id              = one(aws_vpc.main[*].id)
  service_name        = "com.amazonaws.${data.aws_region.current.name}.transfer"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = aws_security_group.transfer[*].id
  private_dns_enabled = false

  tags = merge(local.common_tags, { Name = "${local.server_name}-transfer-vpce" })
}

###############################################################################
# API Gateway identity provider (only when identity_provider_type = API_GATEWAY)
###############################################################################

resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name               = "${local.server_name}-apigw-cloudwatch"
  assume_role_policy = data.aws_iam_policy_document.api_gateway_assume_role.json
  description        = "API Gateway CloudWatch logging role for ${local.server_name}"

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "api_gateway_cloudwatch" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  role       = one(aws_iam_role.api_gateway_cloudwatch[*].name)
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "transfer" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  cloudwatch_role_arn = one(aws_iam_role.api_gateway_cloudwatch[*].arn)

  depends_on = [aws_iam_role_policy_attachment.api_gateway_cloudwatch]
}

resource "aws_api_gateway_rest_api" "transfer" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name        = "${local.server_name}-transfer-auth"
  description = "Identity provider endpoint for the ${local.server_name} AWS Transfer Family server"

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.transfer[*].id)
  parent_id   = one(aws_api_gateway_rest_api.transfer[*].root_resource_id)
  path_part   = "auth"
}

resource "aws_api_gateway_method" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id   = one(aws_api_gateway_rest_api.transfer[*].id)
  resource_id   = one(aws_api_gateway_resource.auth[*].id)
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.transfer[*].id)
  resource_id = one(aws_api_gateway_resource.auth[*].id)
  http_method = one(aws_api_gateway_method.auth[*].http_method)
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_api_gateway_method_response" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.transfer[*].id)
  resource_id = one(aws_api_gateway_resource.auth[*].id)
  http_method = one(aws_api_gateway_method.auth[*].http_method)
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.transfer[*].id)
  resource_id = one(aws_api_gateway_resource.auth[*].id)
  http_method = one(aws_api_gateway_method.auth[*].http_method)
  status_code = one(aws_api_gateway_method_response.auth[*].status_code)

  depends_on = [aws_api_gateway_integration.auth]
}

resource "aws_api_gateway_deployment" "transfer" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.transfer[*].id)

  triggers = {
    redeployment = sha1(jsonencode([
      one(aws_api_gateway_resource.auth[*].id),
      one(aws_api_gateway_method.auth[*].id),
      one(aws_api_gateway_integration.auth[*].id),
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_api_gateway_integration.auth]
}

resource "aws_api_gateway_stage" "transfer" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  deployment_id = one(aws_api_gateway_deployment.transfer[*].id)
  rest_api_id   = one(aws_api_gateway_rest_api.transfer[*].id)
  stage_name    = "transfer"

  tags = local.common_tags
}

resource "aws_iam_role" "transfer_invocation" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name               = "${local.server_name}-transfer-invocation"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  description        = "Invocation role allowing the ${local.server_name} Transfer server to call its identity provider"

  tags = local.common_tags
}

resource "aws_iam_role_policy" "transfer_invocation" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "${local.server_name}-transfer-invocation"
  role = one(aws_iam_role.transfer_invocation[*].id)

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InvokeIdentityProviderApi"
        Effect   = "Allow"
        Action   = "execute-api:Invoke"
        Resource = ["${one(aws_api_gateway_rest_api.transfer[*].execution_arn)}/*"]
      },
    ]
  })
}

###############################################################################
# Transfer Family server
###############################################################################

resource "aws_transfer_server" "transfer" {
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  domain                 = var.domain
  identity_provider_type = var.identity_provider_type
  security_policy_name   = var.security_policy_name
  certificate            = contains(var.protocols, "FTPS") ? local.server_certificate_arn : null
  logging_role           = local.logging_role_arn
  host_key               = contains(var.protocols, "SFTP") ? tls_private_key.host_key.private_key_pem : null
  url                    = var.identity_provider_type == "API_GATEWAY" ? one(aws_api_gateway_stage.transfer[*].invoke_url) : null
  invocation_role        = var.identity_provider_type == "API_GATEWAY" ? one(aws_iam_role.transfer_invocation[*].arn) : null

  structured_log_destinations = [aws_cloudwatch_log_group.transfer.arn]

  dynamic "endpoint_details" {
    for_each = local.create_vpc ? [1] : []
    content {
      vpc_id                 = var.endpoint_type == "VPC" ? one(aws_vpc.main[*].id) : null
      subnet_ids             = var.endpoint_type == "VPC" ? aws_subnet.public[*].id : null
      security_group_ids     = var.endpoint_type == "VPC" ? aws_security_group.transfer[*].id : null
      address_allocation_ids = var.endpoint_type == "VPC" ? aws_eip.transfer[*].id : null
      vpc_endpoint_id        = local.create_vpc_endpoint ? one(aws_vpc_endpoint.transfer[*].id) : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.create_protocol_details ? [1] : []
    content {
      as2_transports              = length(var.as2_transports) > 0 ? var.as2_transports : null
      passive_ip                  = var.passive_ip != "" ? var.passive_ip : null
      set_stat_option             = var.set_stat_option != "" ? var.set_stat_option : null
      tls_session_resumption_mode = var.tls_session_resumption_mode != "" ? var.tls_session_resumption_mode : null
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.transfer_logging,
    aws_iam_role_policy_attachment.transfer_user_s3,
    aws_cloudwatch_log_group.transfer,
  ]
}

###############################################################################
# Route 53 hosted zone and SFTP CNAME record
###############################################################################

resource "aws_route53_zone" "transfer" {
  count = local.create_route53 ? 1 : 0

  name = var.hosted_zone_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "sftp" {
  count = local.create_route53 ? 1 : 0

  zone_id = one(aws_route53_zone.transfer[*].zone_id)
  name    = "${var.subdomain}.${var.hosted_zone_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.transfer.endpoint]
}

###############################################################################
# Optional ACM certificate for FTPS
###############################################################################

resource "aws_acm_certificate" "transfer" {
  count = local.create_certificate ? 1 : 0

  domain_name       = "${var.subdomain}.${var.hosted_zone_name}"
  validation_method = "DNS"

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = local.create_certificate ? {
    for dvo in aws_acm_certificate.transfer[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  zone_id         = one(aws_route53_zone.transfer[*].zone_id)
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "cert" {
  count = local.create_certificate ? 1 : 0

  certificate_arn         = one(aws_acm_certificate.transfer[*].arn)
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

###############################################################################
# Per user IAM roles, policies, Transfer users and SSH keys
###############################################################################

data "aws_iam_policy_document" "transfer_user_assume_role" {
  for_each = var.users

  statement {
    sid     = "TransferUserAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:transfer:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:server/*"]
    }
  }
}

resource "aws_iam_role" "transfer_user" {
  for_each = var.users

  name               = "${local.server_name}-${each.key}-transfer-user"
  assume_role_policy = data.aws_iam_policy_document.transfer_user_assume_role[each.key].json
  description        = "Transfer Family access role for user ${each.key}"

  tags = merge(local.common_tags, { User = each.key })
}

data "aws_iam_policy_document" "transfer_user_s3" {
  for_each = var.users

  statement {
    sid       = "ListHomeDirectory"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::${local.user_home_bucket[each.key]}"]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        local.user_home_prefix[each.key],
        "${local.user_home_prefix[each.key]}/*",
      ]
    }
  }

  statement {
    sid     = "HomeDirectoryObjectAccess"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.user_home_bucket[each.key]}/${local.user_home_prefix[each.key]}/*",
    ]
  }

  statement {
    sid    = "HomeDirectoryKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.transfer_home.arn]
  }
}

resource "aws_iam_policy" "transfer_user_s3" {
  for_each = var.users

  name        = "${local.server_name}-${each.key}-s3"
  description = "Least privilege S3 access for the ${each.key} Transfer Family user"
  policy      = data.aws_iam_policy_document.transfer_user_s3[each.key].json

  tags = merge(local.common_tags, { User = each.key })
}

resource "aws_iam_role_policy_attachment" "transfer_user_s3" {
  for_each = var.users

  role       = aws_iam_role.transfer_user[each.key].name
  policy_arn = aws_iam_policy.transfer_user_s3[each.key].arn
}

resource "aws_transfer_user" "sftp" {
  for_each = var.users

  server_id           = aws_transfer_server.transfer.id
  user_name           = each.key
  role                = aws_iam_role.transfer_user[each.key].arn
  home_directory      = each.value.home_directory
  home_directory_type = each.value.home_directory_type
  policy              = each.value.policy

  tags = merge(local.common_tags, { User = each.key })
}

resource "aws_transfer_ssh_key" "transfer_user" {
  for_each = {
    for pair in flatten([
      for user, keys in var.users_ssh_keys : [
        for idx, key in keys : {
          user = user
          idx  = idx
          key  = key
        }
      ]
    ]) : "${pair.user}-${pair.idx}" => pair
    if contains(keys(var.users), pair.user)
  }

  server_id = aws_transfer_server.transfer.id
  user_name = aws_transfer_user.sftp[each.value.user].user_name
  body      = each.value.key
}

###############################################################################
# Outputs
###############################################################################

output "transfer_server_id" {
  description = "Identifier of the AWS Transfer Family server."
  value       = aws_transfer_server.transfer.id
}

output "transfer_server_endpoint" {
  description = "Endpoint hostname of the AWS Transfer Family server."
  value       = aws_transfer_server.transfer.endpoint
}

output "transfer_server_arn" {
  description = "ARN of the AWS Transfer Family server."
  value       = aws_transfer_server.transfer.arn
}

output "sftp_dns_name" {
  description = "Fully qualified Route 53 CNAME for the SFTP endpoint."
  value       = one(aws_route53_record.sftp[*].fqdn)
}

output "api_gateway_rest_api_id" {
  description = "API Gateway REST API identifier used as the identity provider."
  value       = one(aws_api_gateway_rest_api.transfer[*].id)
}

output "api_gateway_invoke_url" {
  description = "API Gateway stage invoke URL used as the identity provider."
  value       = one(aws_api_gateway_stage.transfer[*].invoke_url)
}

output "api_gateway_invocation_role_arn" {
  description = "IAM role ARN assumed by the Transfer server to invoke the identity provider API Gateway."
  value       = one(aws_iam_role.transfer_invocation[*].arn)
}

output "vpc_endpoint_id" {
  description = "VPC endpoint identifier used for VPC_ENDPOINT hosted servers."
  value       = one(aws_vpc_endpoint.transfer[*].id)
}

output "elastic_ip_allocation_ids" {
  description = "Elastic IP allocation identifiers backing VPC hosted endpoints."
  value       = aws_eip.transfer[*].id
}

output "transfer_endpoint_security_group_id" {
  description = "Security group attached to VPC hosted Transfer endpoints."
  value       = one(aws_security_group.transfer[*].id)
}

output "s3_home_bucket" {
  description = "S3 bucket used as the default SFTP home directory storage."
  value       = aws_s3_bucket.transfer_home.bucket
}

output "s3_home_bucket_kms_key_arn" {
  description = "Customer managed KMS key ARN encrypting the SFTP home directory bucket."
  value       = aws_kms_key.transfer_home.arn
}

output "host_key_secret_arn" {
  description = "Secrets Manager secret ARN holding the generated SFTP host key."
  value       = aws_secretsmanager_secret.transfer_host_key.arn
}

output "transfer_logging_role_arn" {
  description = "IAM role ARN used for Transfer Family logging."
  value       = local.logging_role_arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which the network stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC and prefix for every child resource Name tag."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/18"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block (for example 10.0.0.0/18)."
  }
}

variable "az_count" {
  description = "Number of availability zones to use. null means use every AZ returned by the region."
  type        = number
  default     = null

  validation {
    condition     = var.az_count == null || try(var.az_count > 0, false)
    error_message = "az_count must be null or a positive whole number."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets. Public subnets provide internet ROUTING via the internet gateway and public route table; they do not auto-assign public IP addresses on launch."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets (and private routing)."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress (requires public subnets)."
  type        = bool
  default     = true
}

variable "environment" {
  description = "Environment name applied to all resources as a tag."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = data.aws_availability_zones.available.names

  az_count_effective = (
    var.az_count == null
    ? length(local.az_names)
    : min(var.az_count, length(local.az_names))
  )

  azs = slice(local.az_names, 0, local.az_count_effective)

  public_subnet_count  = var.create_public_subnets ? length(local.azs) : 0
  private_subnet_count = var.create_private_subnets ? length(local.azs) : 0

  nat_gateway_enabled = var.create_nat_gateway && var.create_public_subnets

  public_subnet_cidrs = [
    for i in range(local.public_subnet_count) :
    cidrsubnet(var.vpc_cidr, 6, i)
  ]

  private_subnet_cidrs = [
    for i in range(local.private_subnet_count) :
    cidrsubnet(var.vpc_cidr, 6, local.public_subnet_count + i)
  ]

  common_tags = {
    Project     = var.vpc_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

resource "aws_eip" "nat" {
  count = local.nat_gateway_enabled ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_enabled ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = local.nat_gateway_enabled ? [1] : []

    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 120
    action     = "allow"
    protocol   = "tcp"
    from_port  = 1024
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
    Tier = "public"
  })
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = var.vpc_cidr
  }

  ingress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 1024
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
    Tier = "private"
  })
}

resource "aws_network_acl_association" "public" {
  count = local.public_subnet_count

  network_acl_id = aws_network_acl.public[0].id
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl_association" "private" {
  count = local.private_subnet_count

  network_acl_id = aws_network_acl.private[0].id
  subnet_id      = aws_subnet.private[count.index].id
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the network stack."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = one(aws_route_table.public[*].id)
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = aws_route_table.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = one(aws_internet_gateway.main[*].id)
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway."
  value       = one(aws_nat_gateway.main[*].id)
}

output "nat_gateway_public_ip" {
  description = "Elastic IP address of the NAT gateway."
  value       = one(aws_eip.nat[*].public_ip)
}

output "public_network_acl_id" {
  description = "ID of the public network ACL."
  value       = one(aws_network_acl.public[*].id)
}

output "private_network_acl_id" {
  description = "ID of the private network ACL."
  value       = one(aws_network_acl.private[*].id)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "is_ipv6_enabled" {
  description = "Enable dual-stack IPv6 (Amazon-provided IPv6 CIDR) on the VPC and subnets."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the main VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "sn_details" {
  description = "Subnet definitions. 'az' is a zero-based index into the AZ names returned by data.aws_availability_zones."
  type = list(object({
    name   = string
    az     = number
    public = bool
  }))
  default = [
    { name = "web-1", az = 0, public = true },
    { name = "web-2", az = 1, public = true },
    { name = "web-3", az = 2, public = true },
    { name = "app-1", az = 0, public = false },
    { name = "app-2", az = 1, public = false },
    { name = "app-3", az = 2, public = false },
    { name = "database-1", az = 0, public = false },
    { name = "database-2", az = 1, public = false },
    { name = "database-3", az = 2, public = false },
    { name = "reserved-1", az = 0, public = false },
    { name = "reserved-2", az = 1, public = false },
    { name = "reserved-3", az = 2, public = false },
  ]
}

locals {
  any_ipv4 = "0.0.0.0/0"
  any_ipv6 = "::/0"
  tls_port = 443
  ssh_port = 22
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "main-vpc"
  }
}

module "ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block

  networks = [
    for i, sn in var.sn_details : {
      name     = sn.name
      netnum   = i
      new_bits = 4
    }
  ]
}

module "ipv6_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.ipv6_cidr_block

  networks = [
    for i, sn in var.sn_details : {
      name     = sn.name
      netnum   = i
      new_bits = 8
    }
  ]
}

resource "aws_subnet" "main" {
  for_each = { for sn in var.sn_details : sn.name => sn }

  vpc_id            = aws_vpc.main.id
  cidr_block        = module.ipv4_subnets.network_cidr_blocks[each.key]
  ipv6_cidr_block   = var.is_ipv6_enabled ? module.ipv6_subnets.network_cidr_blocks[each.key] : null
  availability_zone = data.aws_availability_zones.available.names[each.value.az]

  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  map_public_ip_on_launch         = false

  tags = {
    Name = each.value.name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = local.any_ipv4
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = local.any_ipv6
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = { for sn in var.sn_details : sn.name => sn if sn.public }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Security group for the public web tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "web_https" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Public TLS entry point"
  cidr_ipv4         = local.any_ipv4
  from_port         = local.tls_port
  to_port           = local.tls_port
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "web_ssh" {
  security_group_id = aws_security_group.web_sg.id
  description       = "SSH from within the VPC only"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "web_to_app" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "TLS egress to the app tier"
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = local.tls_port
  to_port                      = local.tls_port
  ip_protocol                  = "tcp"
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Security group for the private app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "app_from_web" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS ingress from the web tier"
  referenced_security_group_id = aws_security_group.web_sg.id
  from_port                    = local.tls_port
  to_port                      = local.tls_port
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "app_to_db" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS egress to the database tier"
  referenced_security_group_id = aws_security_group.db_sg.id
  from_port                    = local.tls_port
  to_port                      = local.tls_port
  ip_protocol                  = "tcp"
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for the private database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "db_from_app" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "TLS ingress from the app tier"
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = local.tls_port
  to_port                      = local.tls_port
  ip_protocol                  = "tcp"
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the main VPC."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "ipv4_subnet_cidr_blocks" {
  description = "Map of subnet name to calculated IPv4 CIDR block."
  value       = module.ipv4_subnets.network_cidr_blocks
}

output "ipv6_subnet_cidr_blocks" {
  description = "Map of subnet name to calculated IPv6 CIDR block."
  value       = module.ipv6_subnets.network_cidr_blocks
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "web_sg_id" {
  description = "ID of the web tier security group."
  value       = aws_security_group.web_sg.id
}

output "app_sg_id" {
  description = "ID of the app tier security group."
  value       = aws_security_group.app_sg.id
}

output "db_sg_id" {
  description = "ID of the database tier security group."
  value       = aws_security_group.db_sg.id
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Controls if the VPC and its dependent resources should be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix used for all resources and auto-generated Name tags"
  type        = string
  default     = "vpc"
}

variable "environment" {
  description = "Environment name used for tagging"
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "A map of additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "A boolean flag to enable/disable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "A boolean flag to enable/disable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "map_public_ip_on_launch" {
  description = "Specify true to indicate that instances launched into public subnets receive a public IP"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be created for the VPC"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways are provisioned for private subnets"
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "Controls if a single shared NAT Gateway should be created instead of one per private subnet"
  type        = bool
  default     = false
}

variable "azs" {
  description = "List of availability zone names or IDs used for subnet placement"
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "List of CIDR blocks for the private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "List of CIDR blocks for the isolated intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Optional explicit Name tags for public subnets (falls back to generated names)"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit Name tags for private subnets (falls back to generated names)"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit Name tags for intra subnets (falls back to generated names)"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix appended to public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix appended to private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix appended to intra subnet names"
  type        = string
  default     = "intra"
}

################################################################################
# Locals
################################################################################

locals {
  azs      = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names
  az_count = length(local.azs) > 0 ? length(local.azs) : 1

  common_tags = merge(
    var.tags,
    {
      Module      = "vpc"
      Environment = var.environment
    }
  )

  public_subnet_names_final = length(var.public_subnet_names) > 0 ? var.public_subnet_names : [
    for i in range(length(var.public_subnets)) :
    "${var.name}-${var.public_subnet_suffix}-${element(local.azs, i % local.az_count)}"
  ]

  private_subnet_names_final = length(var.private_subnet_names) > 0 ? var.private_subnet_names : [
    for i in range(length(var.private_subnets)) :
    "${var.name}-${var.private_subnet_suffix}-${element(local.azs, i % local.az_count)}"
  ]

  intra_subnet_names_final = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names : [
    for i in range(length(var.intra_subnets)) :
    "${var.name}-${var.intra_subnet_suffix}-${element(local.azs, i % local.az_count)}"
  ]
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(
    local.common_tags,
    {
      Name = var.name
    }
  )
}

################################################################################
# Public Subnets
################################################################################

resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnets) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = element(var.public_subnets, count.index)
  availability_zone       = element(local.azs, count.index % local.az_count)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = element(local.public_subnet_names_final, count.index)
      Tier = "public"
    }
  )
}

################################################################################
# Private Subnets
################################################################################

resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = element(var.private_subnets, count.index)
  availability_zone = element(local.azs, count.index % local.az_count)

  tags = merge(
    local.common_tags,
    {
      Name = element(local.private_subnet_names_final, count.index)
      Tier = "private"
    }
  )
}

################################################################################
# Intra Subnets
################################################################################

resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = element(var.intra_subnets, count.index)
  availability_zone = element(local.azs, count.index % local.az_count)

  tags = merge(
    local.common_tags,
    {
      Name = element(local.intra_subnet_names_final, count.index)
      Tier = "intra"
    }
  )
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-igw"
    }
  )
}

################################################################################
# Public Route Table
################################################################################

resource "aws_route_table" "public" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.public_subnet_suffix}-rt"
      Tier = "public"
    }
  )
}

resource "aws_route" "public_internet_gateway" {
  count = length(aws_route_table.public)

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = length(aws_route_table.public) > 0 ? length(aws_subnet.public) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT Gateways (Elastic IPs)
################################################################################

resource "aws_eip" "nat" {
  count = var.create_vpc && var.enable_nat_gateway && length(var.public_subnets) > 0 && length(var.private_subnets) > 0 ? (var.single_nat_gateway ? 1 : min(length(var.public_subnets), length(var.private_subnets))) : 0

  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-nat-eip-${count.index}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = var.create_vpc && var.enable_nat_gateway && length(var.public_subnets) > 0 && length(var.private_subnets) > 0 ? (var.single_nat_gateway ? 1 : min(length(var.public_subnets), length(var.private_subnets))) : 0

  allocation_id = element(aws_eip.nat[*].id, count.index)
  subnet_id     = element(aws_subnet.public[*].id, count.index)

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-nat-${count.index}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Private Route Tables
################################################################################

resource "aws_route_table" "private" {
  count = var.create_vpc && var.enable_nat_gateway && length(var.public_subnets) > 0 && length(var.private_subnets) > 0 ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.private_subnet_suffix}-rt-${count.index}"
      Tier = "private"
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  count = length(aws_route_table.private)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, var.single_nat_gateway ? 0 : count.index)
}

resource "aws_route_table_association" "private" {
  count = length(aws_route_table.private) > 0 ? length(aws_subnet.private) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

################################################################################
# Intra (isolated) Route Tables
################################################################################

resource "aws_route_table" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.name}-${var.intra_subnet_suffix}-rt-${count.index}"
      Tier = "intra"
    }
  )
}

resource "aws_route_table_association" "intra" {
  count = length(aws_subnet.intra)

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs"
  value       = aws_nat_gateway.this[*].id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of intra subnet IDs"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "The ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of private route table IDs"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of intra route table IDs"
  value       = aws_route_table.intra[*].id
}

output "azs" {
  description = "The list of availability zones used by the module"
  value       = local.azs
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "api_type" {
  type    = string
  default = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either http or rest."
  }
}

variable "api_name" {
  type    = string
  default = "benchmark-api"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "domain_name" {
  type    = string
  default = "api.example.com"
}

variable "hosted_zone_name" {
  type    = string
  default = "example.com"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "allowed_ip_cidrs" {
  type    = list(string)
  default = []
}

variable "target_port" {
  type    = number
  default = 443
}

variable "enable_vpc_link" {
  type    = bool
  default = false
}

variable "enable_custom_domain" {
  type    = bool
  default = false
}

variable "enable_route53_alias" {
  type    = bool
  default = false
}

variable "enable_authorizer" {
  type    = bool
  default = false
}

variable "enable_ip_restriction" {
  type    = bool
  default = false
}

variable "tags" {
  type    = map(string)
  default = {
    Project = "benchmark-api"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "authorizer_invoke" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["lambda:InvokeFunction"]

    resources = [one(aws_lambda_function.authorizer[*].arn)]
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]

    resources = [
      for arn in concat(
        [aws_cloudwatch_log_group.lambda_handler.arn],
        aws_cloudwatch_log_group.lambda_authorizer[*].arn
      ) : "${arn}:*"
    ]
  }
}

data "aws_iam_policy_document" "apigw_cloudwatch" {
  count = var.api_type == "rest" ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]

    resources = [
      one(aws_cloudwatch_log_group.api_access[*].arn),
      "${one(aws_cloudwatch_log_group.api_access[*].arn)}:*"
    ]
  }
}

data "aws_iam_policy_document" "ip_restriction" {
  count = var.api_type == "rest" && var.enable_ip_restriction ? 1 : 0

  statement {
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["execute-api:Invoke"]

    resources = ["execute-api:/*"]

    condition {
      test     = "NotIpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ip_cidrs
    }
  }
}

locals {
  stage_name = "${var.environment}-stage"

  azs       = data.aws_availability_zones.available.names
  region    = data.aws_region.current.name
  partition = data.aws_partition.current.partition

  http_routes = {
    "GET /" = {
      integration_type   = "AWS_PROXY"
      integration_method = "POST"
      integration_uri    = null
    }
    "GET /health" = {
      integration_type   = "AWS_PROXY"
      integration_method = "POST"
      integration_uri    = null
    }
  }

  rest_resources = {
    items = {
      path_part = "items"
      parent    = "root"
    }
    item = {
      path_part = "{id}"
      parent    = "items"
    }
  }

  rest_methods = {
    get_items = {
      resource         = "items"
      http_method      = "GET"
      path             = "/items"
      path_parameters  = []
      api_key_required = true
    }
    get_item = {
      resource         = "item"
      http_method      = "GET"
      path             = "/items/{id}"
      path_parameters  = ["id"]
      api_key_required = true
    }
  }

  validation_domains = var.enable_custom_domain ? concat(
    [var.domain_name],
    ["*.${var.domain_name}"]
  ) : []
}

data "archive_file" "handler" {
  type        = "zip"
  output_path = "${path.module}/handler.zip"

  source_content          = <<-PYTHON
    def handler(event, context):
        return {
            "statusCode": 200,
            "body": "ok"
        }
  PYTHON
  source_content_filename = "index.py"
}

data "archive_file" "authorizer" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/authorizer.zip"

  source_content = <<-JS
    exports.handler = async (event) => {
      return {
        principalId: "user",
        policyDocument: {
          Version: "2012-10-17",
          Statement: [
            {
              Action: "execute-api:Invoke",
              Effect: "Allow",
              Resource: event.methodArn
            }
          ]
        }
      };
    };
  JS
  source_content_filename = "index.js"
}

resource "aws_cloudwatch_log_group" "api_access" {
  count = var.api_type == "rest" ? 1 : 0

  name              = "/aws/apigateway/${var.api_name}"
  retention_in_days = 30

  tags = {
    Name = "${var.api_name}-api-access"
  }
}

resource "aws_cloudwatch_log_group" "lambda_handler" {
  name              = "/aws/lambda/${var.api_name}-handler"
  retention_in_days = 30

  tags = {
    Name = "${var.api_name}-handler-logs"
  }
}

resource "aws_cloudwatch_log_group" "lambda_authorizer" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  name              = "/aws/lambda/${var.api_name}-authorizer"
  retention_in_days = 30

  tags = {
    Name = "${var.api_name}-authorizer-logs"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.api_name}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name = "${var.api_name}-lambda-exec"
  }
}

resource "aws_iam_role_policy" "lambda_logging" {
  name   = "${var.api_name}-lambda-logging"
  role   = aws_iam_role.lambda_exec.id
  policy = data.aws_iam_policy_document.lambda_logging.json
}

resource "aws_iam_role" "authorizer_invocation" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  name               = "${var.api_name}-authorizer-invocation"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json

  tags = {
    Name = "${var.api_name}-authorizer-invocation"
  }
}

resource "aws_iam_role_policy" "authorizer_invocation" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  name   = "${var.api_name}-authorizer-invoke"
  role   = one(aws_iam_role.authorizer_invocation[*].id)
  policy = one(data.aws_iam_policy_document.authorizer_invoke[*].json)
}

resource "aws_iam_role" "apigw_cloudwatch" {
  count = var.api_type == "rest" ? 1 : 0

  name               = "${var.api_name}-apigw-cloudwatch"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json

  tags = {
    Name = "${var.api_name}-apigw-cloudwatch"
  }
}

resource "aws_iam_role_policy" "apigw_cloudwatch" {
  count = var.api_type == "rest" ? 1 : 0

  name   = "${var.api_name}-apigw-cloudwatch"
  role   = one(aws_iam_role.apigw_cloudwatch[*].id)
  policy = one(data.aws_iam_policy_document.apigw_cloudwatch[*].json)
}

resource "aws_api_gateway_account" "this" {
  count = var.api_type == "rest" ? 1 : 0

  cloudwatch_role_arn = one(aws_iam_role.apigw_cloudwatch[*].arn)
}

resource "aws_lambda_function" "handler" {
  function_name    = "${var.api_name}-handler"
  filename         = data.archive_file.handler.output_path
  source_code_hash = data.archive_file.handler.output_base64sha256
  handler          = "index.handler"
  runtime          = "python3.12"
  role             = aws_iam_role.lambda_exec.arn

  depends_on = [
    aws_cloudwatch_log_group.lambda_handler,
    aws_iam_role_policy.lambda_logging
  ]

  tags = {
    Name = "${var.api_name}-handler"
  }
}

resource "aws_lambda_function" "authorizer" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  function_name    = "${var.api_name}-authorizer"
  filename         = one(data.archive_file.authorizer[*].output_path)
  source_code_hash = one(data.archive_file.authorizer[*].output_base64sha256)
  handler          = "index.handler"
  runtime          = "nodejs22.x"
  role             = aws_iam_role.lambda_exec.arn

  depends_on = [
    aws_cloudwatch_log_group.lambda_authorizer,
    aws_iam_role_policy.lambda_logging
  ]

  tags = {
    Name = "${var.api_name}-authorizer"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.api_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.api_name}-igw"
  }
}

resource "aws_subnet" "public" {
  for_each = toset(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, index(local.azs, each.key))
  availability_zone       = each.key
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.api_name}-public-${each.key}"
  }
}

resource "aws_subnet" "private" {
  for_each = toset(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, index(local.azs, each.key) + 10)
  availability_zone = each.key

  tags = {
    Name = "${var.api_name}-private-${each.key}"
  }
}

resource "aws_eip" "nat" {
  count = length(local.azs)

  domain = "vpc"

  tags = {
    Name = "${var.api_name}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "nat" {
  count = length(local.azs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[local.azs[count.index]].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.api_name}-nat-${count.index}"
  }
}

resource "aws_route_table" "public" {
  for_each = toset(local.azs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.api_name}-public-rt-${each.key}"
  }
}

resource "aws_route_table" "private" {
  for_each = toset(local.azs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[index(local.azs, each.key)].id
  }

  tags = {
    Name = "${var.api_name}-private-rt-${each.key}"
  }
}

resource "aws_route_table_association" "public" {
  for_each = toset(local.azs)

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[each.key].id
}

resource "aws_route_table_association" "private" {
  for_each = toset(local.azs)

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

resource "aws_security_group" "alb" {
  name        = "${var.api_name}-alb-sg"
  description = "ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.api_name}-alb-sg"
  }
}

resource "aws_security_group" "vpc_link" {
  name        = "${var.api_name}-vpc-link-sg"
  description = "VPC link security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description     = "HTTPS to ALB"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "HTTPS within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.api_name}-vpc-link-sg"
  }
}

resource "aws_apigatewayv2_api" "this" {
  count = var.api_type == "http" ? 1 : 0

  name                       = var.api_name
  protocol_type              = "HTTP"
  route_selection_expression = "$request.method $request.path"

  tags = {
    Name = "${var.api_name}-http"
  }
}

resource "aws_apigatewayv2_integration" "this" {
  for_each = var.api_type == "http" ? local.http_routes : {}

  api_id                 = one(aws_apigatewayv2_api.this[*].id)
  integration_type       = each.value.integration_type
  integration_method     = each.value.integration_method
  integration_uri        = each.value.integration_type == "AWS_PROXY" ? aws_lambda_function.handler.invoke_arn : each.value.integration_uri
  payload_format_version = each.value.integration_type == "AWS_PROXY" ? "2.0" : null

  connection_type = each.value.integration_type == "HTTP_PROXY" && var.enable_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id   = each.value.integration_type == "HTTP_PROXY" && var.enable_vpc_link ? one(aws_apigatewayv2_vpc_link.http[*].id) : null
}

resource "aws_apigatewayv2_route" "this" {
  for_each = var.api_type == "http" ? local.http_routes : {}

  api_id    = one(aws_apigatewayv2_api.this[*].id)
  route_key = each.key
  target    = "integrations/${aws_apigatewayv2_integration.this[each.key].id}"

  authorization_type = "NONE"
}

resource "aws_apigatewayv2_stage" "this" {
  count = var.api_type == "http" ? 1 : 0

  api_id      = one(aws_apigatewayv2_api.this[*].id)
  name        = local.stage_name
  auto_deploy = true

  tags = {
    Name = local.stage_name
  }
}

resource "aws_lambda_permission" "http" {
  count = var.api_type == "http" ? 1 : 0

  statement_id  = "AllowAPIGatewayInvokeHttp"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${one(aws_apigatewayv2_api.this[*].execution_arn)}/*/*"
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count = var.api_type == "http" && var.enable_vpc_link ? 1 : 0

  name               = "${var.api_name}-vpc-link"
  subnet_ids         = [for subnet in aws_subnet.private : subnet.id]
  security_group_ids = [aws_security_group.vpc_link.id]

  tags = {
    Name = "${var.api_name}-vpc-link"
  }
}

resource "aws_api_gateway_rest_api" "this" {
  count = var.api_type == "rest" ? 1 : 0

  name = var.api_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name = "${var.api_name}-rest"
  }
}

resource "aws_api_gateway_rest_api_policy" "this" {
  count = var.api_type == "rest" && var.enable_ip_restriction ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.this[*].id)
  policy      = one(data.aws_iam_policy_document.ip_restriction[*].json)
}

resource "aws_api_gateway_resource" "this" {
  for_each = var.api_type == "rest" ? local.rest_resources : {}

  rest_api_id = one(aws_api_gateway_rest_api.this[*].id)
  parent_id   = try(aws_api_gateway_resource.this[each.value.parent].id, one(aws_api_gateway_rest_api.this[*].root_resource_id))
  path_part   = each.value.path_part
}

resource "aws_api_gateway_method" "this" {
  for_each = var.api_type == "rest" ? local.rest_methods : {}

  rest_api_id   = one(aws_api_gateway_rest_api.this[*].id)
  resource_id   = aws_api_gateway_resource.this[each.value.resource].id
  http_method   = each.value.http_method
  authorization = var.enable_authorizer ? "CUSTOM" : "NONE"
  authorizer_id = var.enable_authorizer ? one(aws_api_gateway_authorizer.this[*].id) : null

  api_key_required = each.value.api_key_required

  request_parameters = {
    for parameter in each.value.path_parameters :
    "method.request.path.${parameter}" => true
  }
}

resource "aws_api_gateway_integration" "this" {
  for_each = var.api_type == "rest" ? local.rest_methods : {}

  rest_api_id             = one(aws_api_gateway_rest_api.this[*].id)
  resource_id             = aws_api_gateway_resource.this[each.value.resource].id
  http_method             = aws_api_gateway_method.this[each.key].http_method
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = aws_lambda_function.handler.invoke_arn
}

resource "aws_lambda_permission" "rest" {
  for_each = var.api_type == "rest" ? local.rest_methods : {}

  statement_id  = "AllowAPIGatewayInvoke-${each.key}"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${one(aws_api_gateway_rest_api.this[*].execution_arn)}/*/${each.value.http_method}${each.value.path}"
}

resource "aws_api_gateway_deployment" "this" {
  count = var.api_type == "rest" ? 1 : 0

  rest_api_id = one(aws_api_gateway_rest_api.this[*].id)

  triggers = {
    redeployment = sha1(jsonencode({
      methods      = [for method in aws_api_gateway_method.this : method.id]
      integrations = [for integration in aws_api_gateway_integration.this : integration.id]
      resources    = [for resource in aws_api_gateway_resource.this : resource.id]
    }))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.this,
    aws_api_gateway_integration.this,
    aws_api_gateway_resource.this,
    aws_api_gateway_rest_api_policy.this
  ]
}

resource "aws_api_gateway_stage" "this" {
  count = var.api_type == "rest" ? 1 : 0

  rest_api_id   = one(aws_api_gateway_rest_api.this[*].id)
  stage_name    = local.stage_name
  deployment_id = one(aws_api_gateway_deployment.this[*].id)

  access_log_settings {
    destination_arn = one(aws_cloudwatch_log_group.api_access[*].arn)

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [aws_api_gateway_account.this]

  tags = {
    Name = local.stage_name
  }
}

resource "aws_api_gateway_usage_plan" "this" {
  count = var.api_type == "rest" ? 1 : 0

  name = "${var.api_name}-usage-plan"

  api_stages {
    api_id = one(aws_api_gateway_rest_api.this[*].id)
    stage  = one(aws_api_gateway_stage.this[*].stage_name)
  }

  throttle_settings {
    burst_limit = 100
    rate_limit  = 50
  }

  quota_settings {
    limit  = 10000
    period = "MONTH"
  }

  depends_on = [aws_api_gateway_stage.this]

  tags = {
    Name = "${var.api_name}-usage-plan"
  }
}

resource "aws_api_gateway_api_key" "this" {
  count = var.api_type == "rest" ? 1 : 0

  name        = "${var.api_name}-key"
  description = "API key for ${var.api_name}"
  enabled     = true

  tags = {
    Name = "${var.api_name}-key"
  }
}

resource "aws_api_gateway_usage_plan_key" "this" {
  count = var.api_type == "rest" ? 1 : 0

  key_id        = one(aws_api_gateway_api_key.this[*].id)
  key_type      = "API_KEY"
  usage_plan_id = one(aws_api_gateway_usage_plan.this[*].id)
}

resource "aws_ssm_parameter" "api_key" {
  count = var.api_type == "rest" ? 1 : 0

  name      = "/${var.api_name}/api-key"
  type      = "SecureString"
  value     = one(aws_api_gateway_api_key.this[*].value)
  overwrite = true

  lifecycle {
    ignore_changes = [value]
  }

  tags = {
    Name = "${var.api_name}-api-key"
  }
}

resource "aws_api_gateway_authorizer" "this" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  name        = "${var.api_name}-authorizer"
  rest_api_id = one(aws_api_gateway_rest_api.this[*].id)

  authorizer_uri = "arn:${local.partition}:apigateway:${local.region}:lambda:path/2015-03-31/functions/${one(aws_lambda_function.authorizer[*].arn)}/invocations"
  type           = "TOKEN"

  identity_source                  = "method.request.header.Authorization"
  authorizer_result_ttl_in_seconds = 300
  authorizer_credentials           = one(aws_iam_role.authorizer_invocation[*].arn)
}

resource "aws_lambda_permission" "authorizer" {
  count = var.api_type == "rest" && var.enable_authorizer ? 1 : 0

  statement_id  = "AllowAPIGatewayInvokeAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = one(aws_lambda_function.authorizer[*].function_name)
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${one(aws_api_gateway_rest_api.this[*].execution_arn)}/*"
}

resource "aws_route53_zone" "this" {
  count = var.enable_custom_domain ? 1 : 0

  name = var.hosted_zone_name

  tags = {
    Name = var.hosted_zone_name
  }
}

resource "aws_acm_certificate" "this" {
  count = var.enable_custom_domain ? 1 : 0

  domain_name               = var.domain_name
  validation_method         = "DNS"
  subject_alternative_names = ["*.${var.domain_name}"]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = var.domain_name
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = var.enable_custom_domain ? toset(local.validation_domains) : toset([])

  zone_id = one(aws_route53_zone.this[*].zone_id)
  name    = [for dvo in one(aws_acm_certificate.this[*].domain_validation_options) : dvo.resource_record_name if dvo.domain_name == each.key][0]
  type    = [for dvo in one(aws_acm_certificate.this[*].domain_validation_options) : dvo.resource_record_type if dvo.domain_name == each.key][0]
  records = [[for dvo in one(aws_acm_certificate.this[*].domain_validation_options) : dvo.resource_record_value if dvo.domain_name == each.key][0]]
  ttl     = 60

  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count = var.enable_custom_domain ? 1 : 0

  certificate_arn         = one(aws_acm_certificate.this[*].arn)
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "this" {
  count = var.api_type == "http" && var.enable_custom_domain ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = one(aws_acm_certificate_validation.this[*].certificate_arn)
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = {
    Name = var.domain_name
  }
}

resource "aws_apigatewayv2_api_mapping" "this" {
  count = var.api_type == "http" && var.enable_custom_domain ? 1 : 0

  api_id      = one(aws_apigatewayv2_api.this[*].id)
  domain_name = one(aws_apigatewayv2_domain_name.this[*].id)
  stage       = one(aws_apigatewayv2_stage.this[*].id)
}

resource "aws_api_gateway_domain_name" "rest" {
  count = var.api_type == "rest" && var.enable_custom_domain ? 1 : 0

  domain_name              = var.domain_name
  regional_certificate_arn = one(aws_acm_certificate_validation.this[*].certificate_arn)
  security_policy          = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name = var.domain_name
  }
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count = var.api_type == "rest" && var.enable_custom_domain ? 1 : 0

  api_id      = one(aws_api_gateway_rest_api.this[*].id)
  stage_name  = one(aws_api_gateway_stage.this[*].stage_name)
  domain_name = one(aws_api_gateway_domain_name.rest[*].domain_name)
}

resource "aws_route53_record" "http_alias" {
  count = var.api_type == "http" && var.enable_custom_domain && var.enable_route53_alias ? 1 : 0

  zone_id = one(aws_route53_zone.this[*].zone_id)
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "rest_alias" {
  count = var.api_type == "rest" && var.enable_custom_domain && var.enable_route53_alias ? 1 : 0

  zone_id = one(aws_route53_zone.this[*].zone_id)
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

resource "aws_lb" "internal" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  name               = "${var.api_name}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [for subnet in aws_subnet.private : subnet.id]

  tags = {
    Name = "${var.api_name}-alb"
  }
}

resource "aws_lb_listener" "internal" {
  count = var.api_type == "rest" && var.enable_vpc_link && var.enable_custom_domain ? 1 : 0

  load_balancer_arn = one(aws_lb.internal[*].arn)
  port              = var.target_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = one(aws_acm_certificate_validation.this[*].certificate_arn)

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

resource "aws_lb" "nlb" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = [for subnet in aws_subnet.private : subnet.id]

  tags = {
    Name = "${var.api_name}-nlb"
  }
}

resource "aws_lb_target_group" "nlb" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  name        = "${var.api_name}-nlb-tg"
  port        = var.target_port
  protocol    = "TCP"
  target_type = "alb"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled  = true
    protocol = "HTTPS"
    path     = "/"
    matcher  = "200"
    port     = "traffic-port"
  }

  tags = {
    Name = "${var.api_name}-nlb-tg"
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  target_group_arn = one(aws_lb_target_group.nlb[*].arn)
  target_id        = one(aws_lb.internal[*].arn)
  port             = var.target_port
}

resource "aws_lb_listener" "nlb" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  load_balancer_arn = one(aws_lb.nlb[*].arn)
  port              = var.target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = one(aws_lb_target_group.nlb[*].arn)
  }
}

resource "aws_api_gateway_vpc_link" "this" {
  count = var.api_type == "rest" && var.enable_vpc_link ? 1 : 0

  name        = "${var.api_name}-vpc-link"
  target_arns = [one(aws_lb.nlb[*].arn)]

  tags = {
    Name = "${var.api_name}-vpc-link"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

###############################################################################
# Static provider metadata / account lookups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables
###############################################################################

variable "tags" {
  description = "Common tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project     = "cloudtrail-audit"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "s3_bucket_name" {
  description = "Name of the CloudTrail log bucket. When empty a unique name is generated from account ID, region and a deterministic suffix."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether to delete all objects in the CloudTrail log bucket when the bucket is destroyed."
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Enable versioning on the CloudTrail log bucket."
  type        = bool
  default     = false
}

variable "cloudwatch_log_group_retention_days" {
  description = "Retention in days for the CloudTrail CloudWatch log group."
  type        = number
  default     = 90
}

variable "kms_key_deletion_window_days" {
  description = "Waiting period (in days) before the CloudTrail KMS key is deleted."
  type        = number
  default     = 30
}

variable "kms_key_alias_prefix" {
  description = "Prefix used when building the CloudTrail KMS key alias (alias/<prefix>-cloudtrail)."
  type        = string
  default     = "cloudtrail"
}

variable "kms_decrypt_role_arn" {
  description = "Optional IAM role ARN that is granted kms:Decrypt on the CloudTrail KMS key."
  type        = string
  default     = ""
}

variable "cloudtrail_s3_key_prefix" {
  description = "S3 key prefix under which CloudTrail delivers log files."
  type        = string
  default     = "cloudtrail-logs"
}

variable "cloudtrail_enable_log_file_validation" {
  description = "Enable CloudTrail log file validation (digest files)."
  type        = bool
  default     = true
}

variable "cloudtrail_include_global_service_events" {
  description = "Include global service events (IAM, STS, CloudFront) in the trail."
  type        = bool
  default     = true
}

variable "cloudtrail_is_multi_region_trail" {
  description = "Create a multi-region trail."
  type        = bool
  default     = true
}

variable "cloudtrail_enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "cloudtrail_is_organization_trail" {
  description = "Create the trail as an organization trail."
  type        = bool
  default     = false
}

variable "cloudtrail_event_selector_read_write_type" {
  description = "Read/write type for the CloudTrail management event selector (All, ReadOnly, WriteOnly)."
  type        = string
  default     = "All"
}

variable "cloudtrail_event_selector_include_management_events" {
  description = "Include management events in the CloudTrail event selector."
  type        = bool
  default     = true
}

variable "cloudtrail_data_resources" {
  description = "Optional list of data resources (S3 objects, Lambda functions, ...) to select as data events."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "cloudtrail_insight_types" {
  description = "Optional list of CloudTrail Insights types to enable (for example ApiCallRateInsight)."
  type        = list(string)
  default     = []
}

variable "sns_topic_creation_enabled" {
  description = "Create a dedicated SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic created for CloudTrail notifications."
  type        = string
  default     = "cloudtrail-alerts"
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN used for CloudTrail notifications when sns_topic_creation_enabled is false."
  type        = string
  default     = ""
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  name_prefix = "cloudtrail"

  # Deterministic 8-character lowercase suffix derived from stable inputs.
  # Uses only the AWS provider's built-in functions (no extra provider binary).
  bucket_suffix = substr(
    sha256("${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${local.name_prefix}"),
    0,
    8,
  )

  cloudtrail_name = "${local.name_prefix}-trail"
  cloudtrail_arn  = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.cloudtrail_name}"

  cloudtrail_s3_bucket_name = (
    var.s3_bucket_name != ""
    ? var.s3_bucket_name
    : "${local.name_prefix}-logs-${local.account_id}-${local.region}-${local.bucket_suffix}"
  )

  cloudwatch_log_group_name = "/aws/cloudtrail/${local.name_prefix}"

  cloudtrail_sns_topic_arn = (
    var.sns_topic_creation_enabled
    ? aws_sns_topic.cloudtrail[0].arn
    : var.sns_topic_arn
  )

  common_tags = var.tags
}

###############################################################################
# KMS key for CloudTrail log file encryption
###############################################################################

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail log files and the CloudTrail log bucket"
  deletion_window_in_days = var.kms_key_deletion_window_days
  enable_key_rotation     = true

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = [aws_kms_key.cloudtrail.arn]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogFiles"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.cloudtrail.arn]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsToEncryptLogGroup"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.cloudtrail.arn]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryptionUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.cloudtrail.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  dynamic "statement" {
    for_each = var.kms_decrypt_role_arn != "" ? [var.kms_decrypt_role_arn] : []

    content {
      sid    = "AllowDecryptForProvidedRole"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]

      resources = [aws_kms_key.cloudtrail.arn]
    }
  }
}

resource "aws_kms_key_policy" "cloudtrail" {
  key_id = aws_kms_key.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_kms.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_key_alias_prefix}-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

###############################################################################
# CloudTrail log storage bucket
###############################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.cloudtrail_s3_bucket_name
  force_destroy = var.s3_force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Disabled"
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/${var.cloudtrail_s3_key_prefix}/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_arn]
    }
  }

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.cloudtrail.arn,
      "${aws_s3_bucket.cloudtrail.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

###############################################################################
# CloudWatch Logs delivery
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_group_retention_days

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_assume_role" {
  statement {
    sid     = "AllowCloudTrailToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${local.name_prefix}-cloudwatch-logs-role"
  description        = "Role assumed by CloudTrail to deliver events to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_logs" {
  statement {
    sid    = "AllowCloudTrailCreateLogStreamAndPutLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.cloudtrail.arn,
      "${aws_cloudwatch_log_group.cloudtrail.arn}:log-stream:*",
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "${local.name_prefix}-cloudwatch-logs-policy"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_logs.json
}

###############################################################################
# Optional SNS notification topic
###############################################################################

resource "aws_sns_topic" "cloudtrail" {
  count = var.sns_topic_creation_enabled ? 1 : 0

  name = var.sns_topic_name
  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_sns" {
  count = var.sns_topic_creation_enabled ? 1 : 0

  statement {
    sid    = "AllowCloudTrailToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.sns_topic_creation_enabled ? 1 : 0

  arn    = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.cloudtrail_sns[0].json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "this" {
  name                          = local.cloudtrail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = var.cloudtrail_s3_key_prefix
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  enable_log_file_validation    = var.cloudtrail_enable_log_file_validation
  include_global_service_events = var.cloudtrail_include_global_service_events
  is_multi_region_trail         = var.cloudtrail_is_multi_region_trail
  enable_logging                = var.cloudtrail_enable_logging
  is_organization_trail         = var.cloudtrail_is_organization_trail
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.cloudtrail_sns_topic_arn != "" ? local.cloudtrail_sns_topic_arn : null

  event_selector {
    read_write_type           = var.cloudtrail_event_selector_read_write_type
    include_management_events = var.cloudtrail_event_selector_include_management_events

    dynamic "data_resource" {
      for_each = var.cloudtrail_data_resources

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.cloudtrail_insight_types

    content {
      insight_type = insight_selector.value
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
    aws_kms_key_policy.cloudtrail,
  ]
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  type        = string
  description = "Name of the EKS cluster used as the base identifier for all IAM roles, the instance profile, and the Cluster Autoscaler policy."
  default     = "legion"
}

locals {
  cluster_name = var.cluster_name

  role_tags = {
    Cluster = var.cluster_name
  }
}

# ---------------------------------------------------------------------------
# EKS control plane (master) role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = local.role_tags
}

data "aws_iam_policy" "amazon_eks_cluster_policy" {
  name = "AmazonEKSClusterPolicy"
}

data "aws_iam_policy" "amazon_eks_service_policy" {
  name = "AmazonEKSServicePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = data.aws_iam_policy.amazon_eks_cluster_policy.arn
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = data.aws_iam_policy.amazon_eks_service_policy.arn
}

# ---------------------------------------------------------------------------
# EKS worker node role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "EKSNodeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = local.role_tags
}

data "aws_iam_policy" "amazon_eks_worker_node_policy" {
  name = "AmazonEKSWorkerNodePolicy"
}

data "aws_iam_policy" "amazon_eks_cni_policy" {
  name = "AmazonEKS_CNI_Policy"
}

data "aws_iam_policy" "amazon_ec2_container_registry_read_only" {
  name = "AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_worker_node_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.amazon_eks_worker_node_policy.arn
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.amazon_eks_cni_policy.arn
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_ec2_container_registry_read_only" {
  role       = aws_iam_role.eks_node.name
  policy_arn = data.aws_iam_policy.amazon_ec2_container_registry_read_only.arn
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name

  tags = local.role_tags
}

# ---------------------------------------------------------------------------
# Cluster Autoscaler policy for the worker node role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  statement {
    sid    = "ClusterAutoscalerGlobalDescribe"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ClusterAutoscalerScalingActions"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Allows the Kubernetes Cluster Autoscaler running on EKS worker nodes to describe Auto Scaling resources globally and to modify the desired capacity of Auto Scaling groups tagged for the ${var.cluster_name} cluster."
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json

  tags = local.role_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "cluster_role_arn" {
  description = "ARN of the IAM role used by the EKS control plane."
  value       = aws_iam_role.eks_cluster.arn
}

output "node_role_arn" {
  description = "ARN of the IAM role used by the EKS worker nodes."
  value       = aws_iam_role.eks_node.arn
}

output "node_role_name" {
  description = "Name of the IAM role used by the EKS worker nodes."
  value       = aws_iam_role.eks_node.name
}

output "node_instance_profile_arn" {
  description = "ARN of the EC2 instance profile attached to the EKS worker nodes."
  value       = aws_iam_instance_profile.eks_node.arn
}

output "node_instance_profile_name" {
  description = "Name of the EC2 instance profile attached to the EKS worker nodes."
  value       = aws_iam_instance_profile.eks_node.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Account metadata (derived at plan time - never hardcode account IDs)
################################################################################

data "aws_caller_identity" "current" {}

################################################################################
# Input variables (safe defaults so apply is unattended)
################################################################################

variable "namespace" {
  description = "Organization / namespace identifier used as the primary naming prefix."
  type        = string
  default     = "acme"
}

variable "environment" {
  description = "Environment identifier (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Base name identifier for the IAM access management framework."
  type        = string
  default     = "iam"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "attributes" {
  description = "Additional attributes appended to the shared CloudPosse label context."
  type        = list(string)
  default     = []
}

variable "admin_user_names" {
  description = "List of IAM user names that should be created and added to the admin group."
  type        = list(string)
  default     = []
}

variable "non_admin_user_names" {
  description = "List of IAM user names that should be created and added to the non-admin group."
  type        = list(string)
  default     = []
}

################################################################################
# CloudPosse standardized labels
################################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
  attributes  = var.attributes
}

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
  attributes  = concat(var.attributes, ["admin"])
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
  attributes  = concat(var.attributes, ["non-admin"])
}

################################################################################
# Locals
################################################################################

locals {
  # Self-service resource ARNs scoped to the calling IAM user.
  # "$${aws:username}" escapes the policy variable so Terraform does not interpolate it.
  self_user_arn = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
  self_mfa_arn  = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"

  # AWS managed policy required for the administrative role.
  administrator_access_policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

################################################################################
# IAM groups (IAM groups are not taggable - no tags argument)
################################################################################

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = "/"
}

################################################################################
# Self-management policy document
################################################################################

data "aws_iam_policy_document" "self_management" {
  # Account-level read/list operations that are not user scoped.
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"

    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ListAccessKeys",
    ]

    resources = ["*"]
  }

  # Password and access key self-management scoped to the calling user.
  statement {
    sid    = "AllowManageOwnPasswordAndAccessKeys"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
    ]

    resources = [local.self_user_arn]
  }

  # Virtual MFA device creation scoped to the calling user.
  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
    ]

    resources = [local.self_mfa_arn]
  }

  # MFA device activation / re-synchronization scoped to the calling user.
  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"

    actions = [
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [local.self_mfa_arn]
  }

  # Deactivating / deleting a virtual MFA device requires an active MFA session.
  statement {
    sid    = "AllowDeactivateOwnVirtualMFAWithMFA"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [local.self_mfa_arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.this.id}-self-management"
  description = "Allows users to manage their own password, access keys and virtual MFA devices, with MFA required to deactivate an MFA device."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.this.tags
}

################################################################################
# Assume admin role policy (attached to the admin group only)
################################################################################

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid     = "AllowAssumeAdminRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.admin_label.id}-assume-admin-role"
  description = "Allows members of the admin group to assume the dedicated administrative role, requiring MFA."
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = module.admin_label.tags
}

################################################################################
# Administrative role
################################################################################

data "aws_iam_policy_document" "admin_trust" {
  statement {
    sid     = "AllowAccountRootAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "${module.admin_label.id}-role"
  description          = "Dedicated administrative role that can only be assumed by principals presenting a valid MFA session."
  assume_role_policy   = data.aws_iam_policy_document.admin_trust.json
  max_session_duration = 3600
  tags                 = module.admin_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = local.administrator_access_policy_arn
}

################################################################################
# Policy attachments to groups (one resource per attachment - never
# aws_iam_policy_attachment, which is destructive)
################################################################################

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

################################################################################
# Optional member users (created only when names are supplied)
################################################################################

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)

  name = "${module.admin_label.id}-${each.value}"
  path = "/"
  tags = module.admin_label.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)

  name = "${module.non_admin_label.id}-${each.value}"
  path = "/"
  tags = module.non_admin_label.tags
}

################################################################################
# Group memberships (conditional - no resource created for empty lists)
################################################################################

resource "aws_iam_group_membership" "admin" {
  for_each = length(var.admin_user_names) > 0 ? { "admin" = var.admin_user_names } : {}

  name  = "${module.admin_label.id}-membership"
  group = aws_iam_group.admin.name
  users = [for user_name in each.value : aws_iam_user.admin[user_name].name]
}

resource "aws_iam_group_membership" "non_admin" {
  for_each = length(var.non_admin_user_names) > 0 ? { "non-admin" = var.non_admin_user_names } : {}

  name  = "${module.non_admin_label.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for user_name in each.value : aws_iam_user.non_admin[user_name].name]
}

################################################################################
# Outputs
################################################################################

output "admin_group_name" {
  description = "Name of the administrative IAM group."
  value       = aws_iam_group.admin.name
}

output "admin_group_arn" {
  description = "ARN of the administrative IAM group."
  value       = aws_iam_group.admin.arn
}

output "non_admin_group_name" {
  description = "Name of the non-administrative IAM group."
  value       = aws_iam_group.non_admin.name
}

output "non_admin_group_arn" {
  description = "ARN of the non-administrative IAM group."
  value       = aws_iam_group.non_admin.arn
}

output "self_management_policy_arn" {
  description = "ARN of the shared user self-management policy."
  value       = aws_iam_policy.self_management.arn
}

output "admin_assume_role_policy_arn" {
  description = "ARN of the MFA-gated administrative role assumption policy."
  value       = aws_iam_policy.admin_assume_role.arn
}

output "admin_role_arn" {
  description = "ARN of the dedicated administrative IAM role."
  value       = aws_iam_role.admin.arn
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Module toggles
###############################################################################

variable "enable" {
  description = "Master toggle. When false, no resource of this module is created."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "true = create a new security group and its rules, false = attach rules to var.existing_security_group_id."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID used for the new security group. When empty, the module provisions a fallback VPC (10.0.0.0/16)."
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "ID of an existing security group managed when create_new_security_group = false. Never hardcoded."
  type        = string
  default     = ""
}

###############################################################################
# Fallback VPC networking
###############################################################################

variable "map_public_ip_on_launch" {
  description = "Auto-assign public IPv4 addresses to instances launched in the internet-routed subnet tier. Disabled by default (good practice); opt in explicitly when required."
  type        = bool
  default     = false
}

###############################################################################
# Managed prefix list
###############################################################################

variable "create_managed_prefix_list" {
  description = "Create a managed prefix list when no pre-existing prefix list IDs are supplied."
  type        = bool
  default     = false
}

variable "existing_prefix_list_ids" {
  description = "Pre-existing managed prefix list IDs. When non-empty, no new prefix list is created."
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries accepted by the managed prefix list."
  type        = number
  default     = 5

  validation {
    condition     = var.prefix_list_max_entries > 0 && var.prefix_list_max_entries <= 5
    error_message = "prefix_list_max_entries must be greater than 0 and lower than or equal to 5."
  }
}

variable "prefix_list_entries" {
  description = "CIDR entries of the managed prefix list."
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []

  validation {
    condition     = alltrue([for entry in var.prefix_list_entries : can(cidrhost(entry.cidr, 0))])
    error_message = "Every prefix_list_entries.cidr value must be a valid CIDR block."
  }
}

###############################################################################
# Ingress rules
###############################################################################

variable "ingress_cidr_blocks" {
  description = "Ingress rules scoped by CIDR block."
  type = list(object({
    cidr        = string
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = string
  }))
  default = []

  validation {
    condition     = alltrue([for rule in var.ingress_cidr_blocks : can(cidrhost(rule.cidr, 0))])
    error_message = "Every ingress_cidr_blocks.cidr value must be a valid IPv4 or IPv6 CIDR block."
  }

  validation {
    condition = alltrue([
      for rule in var.ingress_cidr_blocks :
      !contains(["0.0.0.0/0", "::/0"], rule.cidr) || (
        rule.ip_protocol != "-1" &&
        rule.from_port >= 80 &&
        rule.to_port <= 443 &&
        rule.from_port <= rule.to_port
      )
    ])
    error_message = "Internet facing ingress (0.0.0.0/0 or ::/0) is only allowed on public web ports (80-443). SSH (22), RDP (3389) and database ports must never be exposed to the internet."
  }
}

variable "ingress_self" {
  description = "Ingress rules that reference the managed security group itself."
  type = list(object({
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = string
  }))
  default = []
}

variable "ingress_source_security_group_ids" {
  description = "Ingress rules scoped by source security group."
  type = list(object({
    security_group_id = string
    from_port         = number
    to_port           = number
    ip_protocol       = string
    description       = string
  }))
  default = []
}

variable "ingress_prefix_list_ids" {
  description = "Ingress rules scoped by managed prefix list. Leave prefix_list_id empty to use the module managed prefix list."
  type = list(object({
    prefix_list_id = string
    from_port      = number
    to_port        = number
    ip_protocol    = string
    description    = string
  }))
  default = []
}

###############################################################################
# Egress rules
###############################################################################

variable "egress_cidr_blocks" {
  description = "Egress rules scoped by CIDR block."
  type = list(object({
    cidr        = string
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = string
  }))
  default = []

  validation {
    condition     = alltrue([for rule in var.egress_cidr_blocks : can(cidrhost(rule.cidr, 0))])
    error_message = "Every egress_cidr_blocks.cidr value must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "egress_self" {
  description = "Egress rules that reference the managed security group itself."
  type = list(object({
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = string
  }))
  default = []
}

variable "egress_destination_security_group_ids" {
  description = "Egress rules scoped by destination security group."
  type = list(object({
    security_group_id = string
    from_port         = number
    to_port           = number
    ip_protocol       = string
    description       = string
  }))
  default = []
}

variable "egress_prefix_list_ids" {
  description = "Egress rules scoped by managed prefix list. Leave prefix_list_id empty to use the module managed prefix list."
  type = list(object({
    prefix_list_id = string
    from_port      = number
    to_port        = number
    ip_protocol    = string
    description    = string
  }))
  default = []
}

###############################################################################
# Naming / tagging inputs
###############################################################################

variable "name" {
  description = "Logical name of the workload/boundary this security group protects."
  type        = string
  default     = "network"
}

variable "environment" {
  description = "Environment name used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project name used for naming and tagging."
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Additional tags merged into every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Label contract
#
# Reproduces the naming and tagging contract of the git based label module
#   module "labels" {
#     source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
#     ...
#   }
# locally so the module stays self contained (same <id>, <id>-sg and
# <id>-prefix-list contract) and applies unattended.
###############################################################################

locals {
  label_id = lower(replace(
    join("-", compact([var.project, var.environment, var.name])),
    "/[^a-zA-Z0-9-]+/",
    "-"
  ))

  security_group_name = "${local.label_id}-sg"
  prefix_list_name    = "${local.label_id}-prefix-list"
  fallback_vpc_name   = "${local.label_id}-vpc"

  labels_tags = {
    Name        = local.label_id
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "Terraform"
  }

  common_tags = merge(local.labels_tags, var.tags)

  # ---- creation gates (variable/known values only, plan-time resolvable) ---
  create_fallback_vpc   = var.enable && var.create_new_security_group && var.vpc_id == ""
  create_security_group = var.enable && var.create_new_security_group
  create_prefix_list = (
    var.enable &&
    var.create_managed_prefix_list &&
    length(var.existing_prefix_list_ids) == 0
  )

  # Rules are managed when the master toggle is on and a security group is
  # either created by this module or explicitly supplied by the caller. This
  # expression must stay variable-only so it can gate `for_each`.
  manage_rules = var.enable && (var.create_new_security_group || var.existing_security_group_id != "")

  # A usable default prefix list exists when we create one or the caller
  # supplied pre-existing IDs. Variable-only so it can gate `for_each`.
  default_prefix_list_available = (
    var.create_managed_prefix_list || length(var.existing_prefix_list_ids) > 0
  )

  # ---- resolved identifiers (may be unknown until apply; attribute only) ----
  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.fallback[0].id, "")

  security_group_id = (
    var.create_new_security_group
    ? try(aws_security_group.this[0].id, "")
    : var.existing_security_group_id
  )

  prefix_list_id = (
    local.create_prefix_list
    ? try(aws_ec2_managed_prefix_list.this[0].id, "")
    : (length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids[0] : "")
  )

  availability_zones = slice(
    data.aws_availability_zones.available.names,
    0,
    min(2, length(data.aws_availability_zones.available.names))
  )
}

###############################################################################
# Fallback VPC (only when a new security group is requested without a VPC id)
###############################################################################

resource "aws_vpc" "fallback" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.fallback_vpc_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Internet-routed subnet tier: reaches the internet through the internet
# gateway route table. Instances do NOT auto-receive public IP addresses
# (map_public_ip_on_launch defaults to false); opt in explicitly only when
# genuinely required.
resource "aws_subnet" "public" {
  count = local.create_fallback_vpc ? length(local.availability_zones) : 0

  vpc_id                  = aws_vpc.fallback[0].id
  cidr_block              = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.label_id}-public-${count.index + 1}"
    Tier = "public"
  })
}

# Private tier: no IGW route, no auto-assigned public IP addresses.
resource "aws_subnet" "private" {
  count = local.create_fallback_vpc ? length(local.availability_zones) : 0

  vpc_id            = aws_vpc.fallback[0].id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index + 100)
  availability_zone = local.availability_zones[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.label_id}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "fallback" {
  count = local.create_fallback_vpc ? 1 : 0

  vpc_id = aws_vpc.fallback[0].id

  tags = merge(local.common_tags, {
    Name = "${local.label_id}-igw"
  })
}

resource "aws_route_table" "public" {
  count = local.create_fallback_vpc ? 1 : 0

  vpc_id = aws_vpc.fallback[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.fallback[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${local.label_id}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.create_fallback_vpc ? length(aws_subnet.public) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private tier route table. No NAT gateway is provisioned by default (cost
# driven decision); attach a NAT gateway route here if private egress is
# required by the workload.
resource "aws_route_table" "private" {
  count = local.create_fallback_vpc ? 1 : 0

  vpc_id = aws_vpc.fallback[0].id

  tags = merge(local.common_tags, {
    Name = "${local.label_id}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = local.create_fallback_vpc ? length(aws_subnet.private) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, entry in var.prefix_list_entries : tostring(idx) => entry }

    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(local.common_tags, {
    Name = local.prefix_list_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Security group
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_security_group ? 1 : 0

  name        = local.security_group_name
  description = "Managed security group for ${local.label_id} workloads"
  vpc_id      = local.vpc_id

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Ingress rules
#
# Any rule allowing 0.0.0.0/0 or ::/0 is a deliberate, justified exception and
# is restricted to public web ports (80-443) by variable validation; SSH, RDP
# and database ports can only be reached from a scoped CIDR, a source security
# group, the security group itself or a managed prefix list.
#
# All for_each maps are derived from input variables and known locals only, so
# every key is resolvable at plan time.
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "cidr" {
  for_each = local.manage_rules ? {
    for idx, rule in var.ingress_cidr_blocks : tostring(idx) => rule
  } : {}

  security_group_id = local.security_group_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? -1 : each.value.to_port
  cidr_ipv4         = strcontains(each.value.cidr, ":") ? null : each.value.cidr
  cidr_ipv6         = strcontains(each.value.cidr, ":") ? each.value.cidr : null

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "self" {
  for_each = local.manage_rules ? {
    for idx, rule in var.ingress_self : tostring(idx) => rule
  } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = local.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "source_security_group" {
  for_each = local.manage_rules ? {
    for idx, rule in var.ingress_source_security_group_ids : tostring(idx) => rule
  } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "prefix_list" {
  for_each = local.manage_rules ? {
    for idx, rule in var.ingress_prefix_list_ids : tostring(idx) => rule
    if rule.prefix_list_id != "" || local.default_prefix_list_available
  } : {}

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != "" ? each.value.prefix_list_id : local.prefix_list_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

###############################################################################
# Egress rules
#
# No egress rule is created by default: outbound traffic is deny-by-default and
# must be declared explicitly through the egress_* inputs (least privilege).
###############################################################################

resource "aws_vpc_security_group_egress_rule" "cidr" {
  for_each = local.manage_rules ? {
    for idx, rule in var.egress_cidr_blocks : tostring(idx) => rule
  } : {}

  security_group_id = local.security_group_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? -1 : each.value.to_port
  cidr_ipv4         = strcontains(each.value.cidr, ":") ? null : each.value.cidr
  cidr_ipv6         = strcontains(each.value.cidr, ":") ? each.value.cidr : null

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "self" {
  for_each = local.manage_rules ? {
    for idx, rule in var.egress_self : tostring(idx) => rule
  } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = local.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "destination_security_group" {
  for_each = local.manage_rules ? {
    for idx, rule in var.egress_destination_security_group_ids : tostring(idx) => rule
  } : {}

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "prefix_list" {
  for_each = local.manage_rules ? {
    for idx, rule in var.egress_prefix_list_ids : tostring(idx) => rule
    if rule.prefix_list_id != "" || local.default_prefix_list_available
  } : {}

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != "" ? each.value.prefix_list_id : local.prefix_list_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? -1 : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? -1 : each.value.to_port

  tags = local.common_tags
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the managed security group (newly created or caller supplied)."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group (empty when an existing security group is managed)."
  value       = try(aws_security_group.this[0].arn, "")
}

output "security_group_name" {
  description = "Name of the newly created security group (empty when an existing security group is managed)."
  value       = try(aws_security_group.this[0].name, "")
}

output "vpc_id" {
  description = "VPC hosting the security group, either supplied or the module provisioned fallback VPC."
  value       = local.vpc_id
}

output "fallback_vpc_id" {
  description = "ID of the fallback VPC when it was provisioned, otherwise an empty string."
  value       = try(aws_vpc.fallback[0].id, "")
}

output "managed_prefix_list_id" {
  description = "ID of the effective managed prefix list (created or first caller supplied)."
  value       = local.prefix_list_id
}

output "ingress_rule_ids" {
  description = "IDs of all managed ingress rules, keyed by rule category and index."
  value = merge(
    { for k, r in aws_vpc_security_group_ingress_rule.cidr : "cidr-${k}" => r.id },
    { for k, r in aws_vpc_security_group_ingress_rule.self : "self-${k}" => r.id },
    { for k, r in aws_vpc_security_group_ingress_rule.source_security_group : "source-sg-${k}" => r.id },
    { for k, r in aws_vpc_security_group_ingress_rule.prefix_list : "prefix-list-${k}" => r.id },
  )
}

output "egress_rule_ids" {
  description = "IDs of all managed egress rules, keyed by rule category and index."
  value = merge(
    { for k, r in aws_vpc_security_group_egress_rule.cidr : "cidr-${k}" => r.id },
    { for k, r in aws_vpc_security_group_egress_rule.self : "self-${k}" => r.id },
    { for k, r in aws_vpc_security_group_egress_rule.destination_security_group : "destination-sg-${k}" => r.id },
    { for k, r in aws_vpc_security_group_egress_rule.prefix_list : "prefix-list-${k}" => r.id },
  )
}

output "availability_zones" {
  description = "Availability zones used by the fallback VPC subnets."
  value       = local.availability_zones
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.91.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "4.0.5"
    }
    local = {
      source  = "hashicorp/local"
      version = "2.5.1"
    }
    time = {
      source  = "hashicorp/time"
      version = "0.12.1"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

variable "kubernetes_version" {
  description = "Kubernetes version used for the EKS control plane and the worker node bootstrap"
  type        = string
  default     = "1.30"
}

locals {
  aws_region         = "us-east-1"
  cluster_name       = "demo-eks"
  vpc_cidr           = "10.0.0.0/16"
  public_subnet_cidr = "10.0.0.0/24"
  private_subnet_cidrs = {
    a = "10.0.1.0/24"
    b = "10.0.2.0/24"
    c = "10.0.3.0/24"
  }
  common_tags = {
    Project     = "demo-eks"
    Environment = "demo"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "eks" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "eks" {
  vpc_id = aws_vpc.eks.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.eks.id
  cidr_block              = local.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.cluster_name}-public-${data.aws_availability_zones.available.names[0]}"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.eks.id
  cidr_block        = local.private_subnet_cidrs.a
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${data.aws_availability_zones.available.names[0]}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.eks.id
  cidr_block        = local.private_subnet_cidrs.b
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${data.aws_availability_zones.available.names[1]}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_subnet" "private_c" {
  vpc_id            = aws_vpc.eks.id
  cidr_block        = local.private_subnet_cidrs.c
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${data.aws_availability_zones.available.names[2]}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.eks]

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "eks" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.eks]

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.eks.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eks.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.eks.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.eks.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_c" {
  subnet_id      = aws_subnet.private_c.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# KMS key used to encrypt EKS secrets
# ---------------------------------------------------------------------------

resource "aws_kms_key" "eks" {
  description             = "Customer managed key used to encrypt ${local.cluster_name} EKS secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-eks-secrets"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${local.cluster_name}-eks-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

# ---------------------------------------------------------------------------
# EKS control plane IAM role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSClusterAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cluster_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "eksClusterSecretsKMSAccess"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowUseOfEKSSecretsKey"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Security groups (control plane <-> worker nodes)
# ---------------------------------------------------------------------------

resource "aws_security_group" "cluster" {
  name        = "${local.cluster_name}-cluster-sg"
  description = "EKS control plane security group for ${local.cluster_name}"
  vpc_id      = aws_vpc.eks.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-cluster-sg"
  })
}

resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node-sg"
  description = "EKS worker node security group for ${local.cluster_name}"
  vpc_id      = aws_vpc.eks.id

  ingress {
    description = "Unrestricted communication between worker nodes"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-node-sg"
  })
}

# Node -> control plane
resource "aws_security_group_rule" "node_egress_https_to_cluster" {
  type                     = "egress"
  description              = "Worker nodes to EKS control plane API over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node.id
  source_security_group_id = aws_security_group.cluster.id
}

resource "aws_security_group_rule" "node_egress_kubelet_to_cluster" {
  type                     = "egress"
  description              = "Worker nodes to EKS control plane over 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node.id
  source_security_group_id = aws_security_group.cluster.id
}

# Control plane -> node
resource "aws_security_group_rule" "node_ingress_https_from_cluster" {
  type                     = "ingress"
  description              = "EKS control plane to worker nodes over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node.id
  source_security_group_id = aws_security_group.cluster.id
}

resource "aws_security_group_rule" "node_ingress_kubelet_from_cluster" {
  type                     = "ingress"
  description              = "EKS control plane to worker kubelet over 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node.id
  source_security_group_id = aws_security_group.cluster.id
}

# Reciprocal rules on the cluster security group
resource "aws_security_group_rule" "cluster_egress_https_to_node" {
  type                     = "egress"
  description              = "EKS control plane to worker nodes over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.cluster.id
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_egress_kubelet_to_node" {
  type                     = "egress"
  description              = "EKS control plane to worker kubelet over 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_security_group.cluster.id
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_ingress_https_from_node" {
  type                     = "ingress"
  description              = "Worker nodes to EKS control plane API over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.cluster.id
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_ingress_kubelet_from_node" {
  type                     = "ingress"
  description              = "Worker nodes to EKS control plane over 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_security_group.cluster.id
  source_security_group_id = aws_security_group.node.id
}

# ---------------------------------------------------------------------------
# EKS cluster (private API endpoint, secrets encrypted with CMK)
# ---------------------------------------------------------------------------

resource "aws_eks_cluster" "demo_eks" {
  name                          = local.cluster_name
  version                       = var.kubernetes_version
  role_arn                      = aws_iam_role.eks_cluster.arn
  bootstrap_self_managed_addons = false

  vpc_config {
    subnet_ids              = [aws_subnet.private_a.id, aws_subnet.private_b.id, aws_subnet.private_c.id]
    security_group_ids      = [aws_security_group.cluster.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_cluster_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms,
  ]

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Worker node IAM role, instance profile and SSH key pair
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eks_node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSNodeAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_ssm_core" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-demo-node"
  role = aws_iam_role.eks_node.name

  tags = local.common_tags
}

resource "tls_private_key" "node" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  content         = tls_private_key.node.private_key_pem
  filename        = "${pathexpand("~")}/.ssh/eks-aws.pem"
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.node.public_key_openssh

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Worker node launch template
# ---------------------------------------------------------------------------

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${var.kubernetes_version}/amazon-linux-2/recommended/image_id"
}

resource "aws_launch_template" "eks_node" {
  name                   = "${local.cluster_name}-node-lt"
  description            = "Launch template for the ${local.cluster_name} unmanaged worker nodes"
  image_id               = data.aws_ssm_parameter.eks_ami.value
  instance_type          = "t3.medium"
  key_name               = aws_key_pair.eks_kp.key_name
  vpc_security_group_ids = [aws_security_group.node.id]
  update_default_version = true

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node.name
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name                                          = "${local.cluster_name}-node"
      "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name = "${local.cluster_name}-node-volume"
    }
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace

    /etc/eks/bootstrap.sh ${local.cluster_name} \
      --apiserver-endpoint '${aws_eks_cluster.demo_eks.endpoint}' \
      --b64-cluster-ca '${aws_eks_cluster.demo_eks.certificate_authority[0].data}'

    /opt/aws/bin/cfn-signal --exit-code $? \
      --stack eks-cluster-stack \
      --resource NodeGroup \
      --region ${local.aws_region}
  EOT
  )

  tags = local.common_tags
}

resource "time_sleep" "wait_for_launch_template" {
  create_duration = "30s"

  depends_on = [aws_launch_template.eks_node]
}

# ---------------------------------------------------------------------------
# CloudFormation managed Auto Scaling Group for the unmanaged worker nodes
# ---------------------------------------------------------------------------

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name               = "eks-cluster-stack"
  timeout_in_minutes = 10
  on_failure         = "ROLLBACK"

  parameters = {
    NodeLaunchTemplateName = aws_launch_template.eks_node.name
    PrivateSubnetIds       = join(",", [aws_subnet.private_a.id, aws_subnet.private_b.id, aws_subnet.private_c.id])
    MinSize                = "1"
    DesiredCapacity        = "3"
    MaxSize                = "4"
  }

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "Unmanaged EKS worker node Auto Scaling Group for the ${local.cluster_name} cluster"

    Parameters = {
      NodeLaunchTemplateName = {
        Type        = "String"
        Description = "Name of the EC2 launch template used by the worker node Auto Scaling Group"
      }
      PrivateSubnetIds = {
        Type        = "CommaDelimitedList"
        Description = "Private subnet IDs the Auto Scaling Group launches worker nodes into"
      }
      MinSize = {
        Type    = "Number"
        Default = 1
      }
      DesiredCapacity = {
        Type    = "Number"
        Default = 3
      }
      MaxSize = {
        Type    = "Number"
        Default = 4
      }
    }

    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"

        Properties = {
          AutoScalingGroupName = "${local.cluster_name}-node-asg"
          VPCZoneIdentifier    = { Ref = "PrivateSubnetIds" }
          MinSize              = { Ref = "MinSize" }
          DesiredCapacity      = { Ref = "DesiredCapacity" }
          MaxSize              = { Ref = "MaxSize" }
          LaunchTemplate = {
            LaunchTemplateName = { Ref = "NodeLaunchTemplateName" }
            Version            = "$Latest"
          }
          Tags = [
            {
              Key               = "Name"
              Value             = "${local.cluster_name}-node"
              PropagateAtLaunch = true
            }
          ]
        }

        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }
      }
    }

    Outputs = {
      NodeGroupAsgId = {
        Description = "ID of the Auto Scaling Group running the EKS worker nodes"
        Value       = { Ref = "NodeGroup" }
      }
    }
  })

  depends_on = [
    time_sleep.wait_for_launch_template,
    aws_launch_template.eks_node,
    aws_iam_instance_profile.eks_node,
    aws_security_group.node,
    aws_eks_cluster.demo_eks,
  ]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "node_instance_role_arn" {
  description = "ARN of the IAM role attached to the EKS worker nodes"
  value       = aws_iam_role.eks_node.arn
}

output "node_security_group_id" {
  description = "ID of the EKS worker node security group"
  value       = aws_security_group.node.id
}

output "node_group_asg_id" {
  description = "ID of the Auto Scaling Group created by the eks-cluster-stack CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeGroupAsgId"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "= 2.4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

variable "stacks" {
  description = "Map of EKS stack name to metadata used to provision per-stack state locking, IAM access and generated backend files."
  type = map(object({
    region = string
  }))
  default = {
    "platform" = {
      region = "us-east-1"
    }
    "workloads" = {
      region = "us-east-1"
    }
  }
}

variable "replica_region" {
  description = "Secondary AWS region used for the cross-region replica state bucket and its dedicated KMS key."
  type        = string
  default     = "us-west-2"
}

variable "tags" {
  description = "Additional tags merged into the standardized state-management tag set."
  type        = map(string)
  default     = {}
}

locals {
  account_id     = data.aws_caller_identity.current.account_id
  primary_region = data.aws_region.current.name
  partition      = data.aws_partition.current.partition

  common_tags = merge(
    {
      Project     = "eks-remote-state"
      Purpose     = "terraform-state"
      ManagedBy   = "Terraform"
      Environment = "shared"
      Component   = "remote-state"
    },
    var.tags,
  )

  primary_bucket_name = "tfstate-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  replica_bucket_name = "tfstate-${data.aws_caller_identity.current.account_id}-${var.replica_region}"

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "primary" {
  description             = "Customer managed key for Terraform remote state in ${local.primary_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/tfstate-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }

  depends_on = [aws_s3_bucket_versioning.primary]
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.primary.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid    = "AllowReplicationRoleAccess"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*",
        ]
      },
    ]
  })
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "Customer managed key for replicated Terraform remote state in ${var.replica_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/tfstate-replica"
  target_key_id = aws_kms_key.replica.key_id
}

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.replica.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid    = "AllowReplicationRoleAccess"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*",
        ]
      },
    ]
  })
}

resource "aws_iam_role" "replication" {
  name = "tfstate-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "replication" {
  name        = "tfstate-replication-policy"
  description = "Least-privilege permissions for S3 cross-region replication of Terraform state"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSourceObjectRead"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*",
        ]
      },
      {
        Sid    = "AllowDecryptSourceObjects"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = [
          aws_kms_key.primary.arn,
        ]
      },
      {
        Sid    = "AllowDestinationReplication"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*",
        ]
      },
      {
        Sid    = "AllowEncryptReplicaObjects"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = [
          aws_kms_key.replica.arn,
        ]
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-state-objects"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }

      metrics {
        status = "Enabled"
      }

      replication_time {
        status = "Enabled"

        time {
          minutes = 15
        }
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_s3_bucket_public_access_block.primary,
    aws_s3_bucket_public_access_block.replica,
    aws_s3_bucket_ownership_controls.primary,
    aws_s3_bucket_ownership_controls.replica,
    aws_s3_bucket_policy.primary,
    aws_s3_bucket_policy.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

resource "aws_dynamodb_table" "state_lock" {
  for_each = var.stacks

  name         = "${each.key}-tfstate-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(
    local.common_tags,
    {
      Stack = each.key
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "stack_state_access" {
  for_each = var.stacks

  name        = "${each.key}-tfstate-access"
  description = "Scoped state access policy for the ${each.key} EKS stack"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowStackStateLocking"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:UpdateItem",
          "dynamodb:DescribeTable",
          "dynamodb:ConditionCheckItem",
        ]
        Resource = [
          aws_dynamodb_table.state_lock[each.key].arn,
        ]
      },
      {
        Sid      = "AllowListStackStatePrefix"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.primary.arn]
        Condition = {
          StringLike = {
            "s3:prefix" = "${each.key}/*"
          }
        }
      },
      {
        Sid    = "AllowStackStateObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:GetObjectTagging",
          "s3:PutObjectTagging",
        ]
        Resource = [
          "${aws_s3_bucket.primary.arn}/${each.key}/*",
        ]
      },
      {
        Sid    = "AllowStackStateEncryptionKeyUse"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = [
          aws_kms_key.primary.arn,
        ]
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Stack = each.key
    },
  )
}

resource "aws_iam_role" "stack_state_access" {
  for_each = var.stacks

  name = "${each.key}-tfstate-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowStackTerraformAutomation"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringLike = {
            "aws:PrincipalArn" = "arn:${local.partition}:iam::${local.account_id}:role/${each.key}-*"
          }
        }
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Stack = each.key
    },
  )
}

resource "aws_iam_role_policy_attachment" "stack_state_access" {
  for_each = var.stacks

  role       = aws_iam_role.stack_state_access[each.key].name
  policy_arn = aws_iam_policy.stack_state_access[each.key].arn
}

resource "local_file" "stack_backend" {
  for_each = var.stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.primary.id}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${local.primary_region}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.primary.arn}"
        dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
      }
    }
  EOT
}

output "primary_bucket_name" {
  description = "Name of the primary Terraform state bucket."
  value       = aws_s3_bucket.primary.id
}

output "primary_bucket_arn" {
  description = "ARN of the primary Terraform state bucket."
  value       = aws_s3_bucket.primary.arn
}

output "replica_bucket_name" {
  description = "Name of the disaster recovery replica state bucket."
  value       = aws_s3_bucket.replica.id
}

output "replica_bucket_arn" {
  description = "ARN of the disaster recovery replica state bucket."
  value       = aws_s3_bucket.replica.arn
}

output "primary_kms_key_arn" {
  description = "ARN of the primary state encryption KMS key."
  value       = aws_kms_key.primary.arn
}

output "primary_kms_key_alias" {
  description = "Alias of the primary state encryption KMS key."
  value       = aws_kms_alias.primary.name
}

output "replica_kms_key_arn" {
  description = "ARN of the replica state encryption KMS key."
  value       = aws_kms_key.replica.arn
}

output "replica_kms_key_alias" {
  description = "Alias of the replica state encryption KMS key."
  value       = aws_kms_alias.replica.name
}

output "replication_role_arn" {
  description = "ARN of the IAM role used for S3 cross-region replication."
  value       = aws_iam_role.replication.arn
}

output "state_lock_table_names" {
  description = "Map of stack name to its DynamoDB state locking table name."
  value       = { for name, table in aws_dynamodb_table.state_lock : name => table.name }
}

output "stack_state_access_role_arns" {
  description = "Map of stack name to its scoped state access IAM role ARN."
  value       = { for name, role in aws_iam_role.stack_state_access : name => role.arn }
}

output "backend_file_paths" {
  description = "Map of stack name to its generated backend.tf file path."
  value       = { for name, file in local_file.stack_backend : name => file.filename }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "west2"
  region = "us-west-2"
}

###############################################################################
# Variables
###############################################################################

variable "primary_bucket_name" {
  description = "Base name for the primary (us-east-1) S3 bucket. The AWS account ID is appended."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name for the secondary (us-west-2) S3 bucket. The AWS account ID is appended."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point (must be created in us-west-2)."
  type        = string
  default     = "example-mrap"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project     = "s3-mrap"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id

  primary_bucket_name   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${local.account_id}"

  mrap_name = var.mrap_name
}

###############################################################################
# KMS keys (customer managed, rotation enabled)
###############################################################################

resource "aws_kms_key" "primary" {
  description             = "CMK for primary S3 bucket ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "primary" {
  key_id = aws_kms_key.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3AndReplicationUsage"
        Effect = "Allow"
        Principal = {
          AWS     = aws_iam_role.replication.arn
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "secondary" {
  provider = aws.west2

  description             = "CMK for secondary S3 bucket ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "secondary" {
  provider = aws.west2
  key_id   = aws_kms_key.secondary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3AndReplicationUsage"
        Effect = "Allow"
        Principal = {
          AWS     = aws_iam_role.replication.arn
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# S3 buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  bucket        = local.primary_bucket_name
  force_destroy = false

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.west2

  bucket        = local.secondary_bucket_name
  force_destroy = false

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Ownership controls (BucketOwnerPreferred / private ACL posture)
###############################################################################

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.west2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

###############################################################################
# Public access blocks
###############################################################################

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.west2
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Versioning (required for replication and as MRAP backing buckets)
###############################################################################

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.west2
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Default SSE-KMS encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.west2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Bucket policies — enforce TLS-only access
###############################################################################

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_policy" "secondary" {
  provider = aws.west2
  bucket   = aws_s3_bucket.secondary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.secondary.arn,
          "${aws_s3_bucket.secondary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# IAM role assumed by S3 for replication
###############################################################################

resource "aws_iam_role" "replication" {
  name = "s3-mrap-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  name = "s3-mrap-replication-policy"
  role = aws_iam_role.replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketRead"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketWrite"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.secondary.arn}/*"
        ]
      },
      {
        Sid    = "SourceKeyDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.primary.arn
        ]
      },
      {
        Sid    = "DestinationKeyEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.secondary.arn
        ]
      }
    ]
  })
}

###############################################################################
# Replication configuration (primary -> secondary)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  role = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary
  ]
}

###############################################################################
# Multi-Region Access Point (control plane in us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.west2

  details {
    name = local.mrap_name

    public_access_block {
      block_public_acls       = true
      block_public_policy     = true
      ignore_public_acls      = true
      restrict_public_buckets = true
    }

    region {
      bucket = aws_s3_bucket.primary.bucket
    }

    region {
      bucket = aws_s3_bucket.secondary.bucket
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider = aws.west2

  details {
    name = local.mrap_name

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "AllowOwningAccountGetPut"
          Effect = "Allow"
          Principal = {
            AWS = "arn:aws:iam::${local.account_id}:root"
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = [
            aws_s3control_multi_region_access_point.mrap.arn,
            "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
          ]
          Condition = {
            StringEquals = {
              "aws:PrincipalAccount" = local.account_id
            }
          }
        }
      ]
    })
  }

  depends_on = [
    aws_s3control_multi_region_access_point.mrap
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 5.100.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment / deployment stage used for tagging."
  type        = string
  default     = "dev"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table targeted by the backup automation."
  type        = string
  default     = "dynamodb-backup-target"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this template."
  type        = map(string)
  default     = {}
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  lambda_log_group_arn_pattern = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"

  common_tags = merge(
    {
      ManagedBy   = "Terraform"
      Environment = var.environment
      Purpose     = "dynamodb-backup-automation"
    },
    var.tags
  )

  lambda_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

###############################################################################
# Target DynamoDB table (backs the concrete ARNs used by the IAM policies)
###############################################################################

resource "aws_dynamodb_table" "backup_target" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM roles assumable by Lambda
###############################################################################

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  description        = "Lambda execution role permitted to create DynamoDB backups."
  assume_role_policy = local.lambda_assume_role_policy

  tags = local.common_tags
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  description        = "Lambda execution role permitted to list and delete DynamoDB backups."
  assume_role_policy = local.lambda_assume_role_policy

  tags = local.common_tags
}

###############################################################################
# Customer-managed IAM policies
###############################################################################

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Least-privilege permissions required to create DynamoDB backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CreateAndDescribeTableBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup",
          "dynamodb:DescribeTable",
          "dynamodb:ListBackups",
          "dynamodb:DescribeBackup",
        ]
        Resource = [
          aws_dynamodb_table.backup_target.arn,
          "${aws_dynamodb_table.backup_target.arn}/backup/*",
        ]
      },
      {
        Sid      = "ListDynamoDbTables"
        Effect   = "Allow"
        Action   = "dynamodb:ListTables"
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Least-privilege permissions required to list and delete DynamoDB backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageDynamoDbBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups",
          "dynamodb:DescribeBackup",
          "dynamodb:DeleteBackup",
        ]
        Resource = [
          aws_dynamodb_table.backup_target.arn,
          "${aws_dynamodb_table.backup_target.arn}/backup/*",
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "CloudWatch Logs write permissions for Lambda execution roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteLambdaLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          local.lambda_log_group_arn_pattern,
          "${local.lambda_log_group_arn_pattern}:*",
        ]
      }
    ]
  })

  tags = local.common_tags
}

###############################################################################
# Policy attachments (aws_iam_role_policy_attachment only)
###############################################################################

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_create_policy" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_remove_policy" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

###############################################################################
# Outputs
###############################################################################

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by the DynamoDB backup-creation Lambda."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role used by the DynamoDB backup-creation Lambda."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by the DynamoDB backup-removal Lambda."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role used by the DynamoDB backup-removal Lambda."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "lambda_logging_policy_arn" {
  description = "ARN of the shared CloudWatch Logs policy attached to both roles."
  value       = aws_iam_policy.lambda_logging.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project_name = "projectvpc"

  common_tags = {
    Project = local.project_name
  }
}

resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.project_name
  })
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.projectvpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-public"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.projectvpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-private"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.projectvpc.id

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.projectvpc.id

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.projectvpc.id

  tags = merge(local.common_tags, {
    Name = "${local.project_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "environment" {
  description = "Deployment environment tag applied to the resources created by this configuration."
  type        = string
  default     = "production"
}

variable "owner" {
  description = "Owner tag applied to the resources created by this configuration."
  type        = string
  default     = "endpoint-backup"
}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  account_root_principal = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "Terraform"
  }
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer managed key used to encrypt the endpoint-backup S3 bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountKeyAdministration"
        Effect    = "Allow"
        Principal = {
          AWS = local.account_root_principal
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowAccountKeyUsage"
        Effect    = "Allow"
        Principal = {
          AWS = local.account_root_principal
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyNonTls12OrHigher"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          NumericLessThan = {
            "s3:TlsVersion" = "1.2"
          }
        }
      },
      {
        Sid       = "DenyObjectLockComplianceRetentionBeyond90Days"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:PutObject",
          "s3:PutObjectRetention",
          "s3:BypassGovernanceRetention"
        ]
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          StringEquals = {
            "s3:object-lock-mode" = "COMPLIANCE"
          }
          NumericGreaterThan = {
            "s3:object-lock-remaining-retention-days" = "90"
          }
        }
      }
    ]
  })
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = local.common_tags
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants list, read, write, delete, version, retention, and restore access to the endpoint-backup S3 bucket, plus decrypt, generate data key, and describe key access on the customer managed KMS key used for the bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetBucketLocation",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:AbortMultipartUpload"
        ]
        Resource = aws_s3_bucket.endpoint_backup.arn
      },
      {
        Sid    = "ObjectLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention",
          "s3:GetObjectVersionRetention",
          "s3:RestoreObject",
          "s3:GetObjectAttributes"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.endpoint_backup.arn
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "endpoint_backup_bucket_read_write_access" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

# The default (unaliased) AWS provider — primary source region us-east-1 — is
# injected and configured by the deployment harness. Only the task-specific
# regional aliases required for cross-region replication are declared here.
provider "aws" {
  alias  = "secondary_source"
  region = var.secondary_region
}

provider "aws" {
  alias  = "replica1"
  region = var.replica_region1
}

provider "aws" {
  alias  = "replica2"
  region = var.replica_region2
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "env" {
  description = "Environment tag value applied to all taggable resources."
  type        = string
  default     = "dev"
}

variable "primary_region" {
  description = "Primary source region (descriptive metadata only; the region itself is set by the harness-injected default provider)."
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Secondary source region."
  type        = string
  default     = "us-west-2"
}

variable "replica_region1" {
  description = "First replica region."
  type        = string
  default     = "eu-west-1"
}

variable "replica_region2" {
  description = "Second replica region."
  type        = string
  default     = "ap-southeast-2"
}

# ---------------------------------------------------------------------------
# Context / lookups
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  source_buckets_primary = {
    log1a = "log1a.veerum-${local.account_id}"
    log1b = "log1b.veerum-${local.account_id}"
  }

  source_buckets_secondary = {
    log2a = "log2a.veerum-${local.account_id}"
    log2b = "log2b.veerum-${local.account_id}"
  }

  replica1_buckets = merge(
    { for k, v in local.source_buckets_primary : k => "${v}-replica1-${local.account_id}" },
    { for k, v in local.source_buckets_secondary : k => "${v}-replica1-${local.account_id}" },
  )

  replica2_buckets = merge(
    { for k, v in local.source_buckets_primary : k => "${v}-replica2-${local.account_id}" },
    { for k, v in local.source_buckets_secondary : k => "${v}-replica2-${local.account_id}" },
  )
}

# ---------------------------------------------------------------------------
# IAM role assumed by S3 to perform cross-region replication
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json

  tags = {
    Env = var.env
  }
}

# ---------------------------------------------------------------------------
# KMS customer-managed keys (one per region) and aliases
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableRootAccountAdminAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationRoleUse"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "source1" {
  description             = "Customer-managed key for source buckets in ${var.primary_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = {
    Env = var.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "source2" {
  provider                = aws.secondary_source
  description             = "Customer-managed key for source buckets in ${var.secondary_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = {
    Env = var.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "Customer-managed key for replica buckets in ${var.replica_region1}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = {
    Env = var.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "Customer-managed key for replica buckets in ${var.replica_region2}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = {
    Env = var.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_alias" "source2" {
  provider      = aws.secondary_source
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# ---------------------------------------------------------------------------
# S3 buckets
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "source_primary" {
  for_each = local.source_buckets_primary
  bucket   = each.value

  tags = {
    Env  = var.env
    Name = each.value
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "source_secondary" {
  provider = aws.secondary_source
  for_each = local.source_buckets_secondary
  bucket   = each.value

  tags = {
    Env  = var.env
    Name = each.value
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = local.replica1_buckets
  bucket   = each.value

  tags = {
    Env  = var.env
    Name = each.value
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = local.replica2_buckets
  bucket   = each.value

  tags = {
    Env  = var.env
    Name = each.value
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Versioning (required before replication can be configured)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "source_primary" {
  for_each = local.source_buckets_primary
  bucket   = aws_s3_bucket.source_primary[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "source_secondary" {
  provider = aws.secondary_source
  for_each = local.source_buckets_secondary
  bucket   = aws_s3_bucket.source_secondary[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = local.replica1_buckets
  bucket   = aws_s3_bucket.replica1[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = local.replica2_buckets
  bucket   = aws_s3_bucket.replica2[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Block all public access
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "source_primary" {
  for_each = local.source_buckets_primary
  bucket   = aws_s3_bucket.source_primary[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "source_secondary" {
  provider = aws.secondary_source
  for_each = local.source_buckets_secondary
  bucket   = aws_s3_bucket.source_secondary[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider = aws.replica1
  for_each = local.replica1_buckets
  bucket   = aws_s3_bucket.replica1[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider = aws.replica2
  for_each = local.replica2_buckets
  bucket   = aws_s3_bucket.replica2[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Default SSE-KMS encryption with the region's customer-managed key
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "source_primary" {
  for_each = local.source_buckets_primary
  bucket   = aws_s3_bucket.source_primary[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.source1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source_secondary" {
  provider = aws.secondary_source
  for_each = local.source_buckets_secondary
  bucket   = aws_s3_bucket.source_secondary[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.source2.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = local.replica1_buckets
  bucket   = aws_s3_bucket.replica1[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = local.replica2_buckets
  bucket   = aws_s3_bucket.replica2[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica2.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Replication IAM policy (least privilege) and attachment
# ---------------------------------------------------------------------------

locals {
  source_bucket_arns = concat(
    [for b in aws_s3_bucket.source_primary : b.arn],
    [for b in aws_s3_bucket.source_secondary : b.arn],
  )

  source_object_arns = [for arn in local.source_bucket_arns : "${arn}/*"]

  replica_object_arns = concat(
    [for b in aws_s3_bucket.replica1 : "${b.arn}/*"],
    [for b in aws_s3_bucket.replica2 : "${b.arn}/*"],
  )
}

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid    = "SourceBucketLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
    ]

    resources = local.source_bucket_arns
  }

  statement {
    sid    = "SourceObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = local.source_object_arns
  }

  statement {
    sid    = "ReplicaObjectLevelPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionTagging",
    ]

    resources = local.replica_object_arns
  }

  statement {
    sid    = "DecryptWithSourceKeys"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
  }

  statement {
    sid    = "EncryptWithReplicaKeys"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least-privilege permissions for S3 cross-region replication of the log buckets."
  policy      = data.aws_iam_policy_document.s3_replication.json

  tags = {
    Env = var.env
  }
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# ---------------------------------------------------------------------------
# Replication configurations (two rules per source bucket)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "source_primary" {
  for_each = local.source_buckets_primary

  bucket = aws_s3_bucket.source_primary[each.key].id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source_primary,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}

resource "aws_s3_bucket_replication_configuration" "source_secondary" {
  provider = aws.secondary_source
  for_each = local.source_buckets_secondary

  bucket = aws_s3_bucket.source_secondary[each.key].id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source_secondary,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}
